/* ITOps — the script of guide.html (BT90: moved out of the page, so the page policy allows no inline scripts). */
var APP_NAME='ITOps';   // BT20: the client's app name (replaced from /api/branding)
const CONTENT = {"app":"ITOps","tagline":"Microsoft 365 administration","intro":"ITOps is your IT team’s single place to run the organization’s Microsoft 365 tenant: people and their accounts, onboarding and offboarding, email, devices, licenses, security and the tenant’s security posture. This guide explains, in plain language, what each part does and how to use it.","categories":[{"cat":"Getting started","topics":[{"title":"What ITOps is and how it fits together","for":"everyone","body":[{"p":"ITOps is your organization's one place to ask IT and Operations for help, follow your requests, and find the how-to guides and procedures that apply to you."},{"p":"The left-hand menu only shows the areas your role allows, so two people can see quite different menus. The groups are:"},{"bullets":["Dashboard: your starting page, with live counts and your most recent tickets.","Service Desk: Tickets (requests and problems), plus Calendar, Reports, Scorecard and Standards & Audits for the teams that use them.","Knowledge: Knowledge Base (how-to articles), Ask IT (a question-and-answer assistant), SOPs (procedures you read and acknowledge), Job Descriptions and My Signatures (documents waiting for your e-signature).","Assets & Vendors: Equipment, My Equipment (gear on loan to you), Credentials, Contracts and Vendors.","IT Operations, Administration and Logs & Integrations: tools for IT staff and managers."]},{"h":"How a request travels"},{"steps":["A request comes in: you create a ticket in the app, fill in a web form, or email the help-desk mailbox.","It gets a ticket number such as TK-2026-0142. Keep it; it links every message about that request.","The support team sets the category and priority and assigns it to a person.","You and the team talk through comments on the ticket (or by email). Files can be attached.","The ticket is marked resolved, then closed."]},{"tip":"If a menu item or button you expect is missing, your role doesn't include it. Ask your ITOps administrator; they manage access under Administration → Roles & Permissions."}]},{"title":"About ITOps⁠: ownership and license","for":"everyone","body":[{"p":"ITOps⁠ is an IT Operations Management Platform. It is designed, developed and owned by Indisse-BTS, drawing on 30 years managing IT operations for multiple companies in Puerto Rico and Florida."},{"p":"ITOps⁠ is an independent product. It was developed by its owner as an independent developer, not as an employee, contractor or consultant of any company or organization, and it is not a work made for hire for any organization that uses it. Using it, testing it or asking for features gives no organization any ownership of it."},{"p":"© 2026 Indisse-BTS. All rights reserved. ITOps⁠ is proprietary software: it is licensed, not sold. Your organization uses it under the ITOps⁠ Terms of Use and, where it has one, its own written license agreement with the owner."},{"bullets":["The name people see in the app can be your organization's own (Settings → Branding). The product, its owner and these notices stay as they are.","Your organization owns its own data. The owner of ITOps⁠ claims no right to it.","A license does not transfer ownership of the software, its source code, design, database structure, documentation, or any change made to it.","Unless your license agreement allows it in writing: no copying beyond the licensed installation and its backups, no redistribution, resale or hosting for others, no reverse engineering, and no removal of these notices.","Names of other products (for example Microsoft 365 or vTiger) only identify the services ITOps⁠ connects to. They belong to their owners and imply no affiliation or endorsement."]},{"p":"Terms of Use: the first time you sign in, the app shows the Terms of Use with “I agree” and “Sign out”, and the app opens once you agree. They are also accepted once for the whole organization, by a person whose role may do it (for now: Super Admin; Roles & Permissions → “Terms of Use · accept for the organization”). Each acceptance is recorded with the date, the time and the version, and the Terms of Use page lists who has accepted (for the people who manage users). Read them again at any time from the Help Center: the “Terms of Use” button at the top."},{"p":"About & ownership (the button at the top of the Help Center): everyone sees who owns the product, that it is licensed and to which organization. The license details (the agreement, its term, modules and users, the license terms, the installation ID, LICENSE.txt and the third-party components) are shown to the roles your organization gave “License details” (Administration → Roles & Permissions). Nothing on these pages can be changed in the app."}]},{"title":"Signing in","for":"everyone","body":[{"p":"You sign in to ITOps with your work email and password, or with your Microsoft 365 account if your organisation has turned that on."},{"steps":["Open the ITOps link your administrator gave you.","Type your email and password and choose \"Sign In\".","Or, if you see \"Sign in with Microsoft 365\", choose it and pick your work account at the Microsoft prompt.","If your account uses two-factor authentication, a \"Two-step verification\" box appears. Type the 6-digit code from your authenticator app and choose \"Verify\". Lost your phone? Choose \"Use a backup code instead\".","If your organisation requires two-factor and you haven't set it up yet, you'll be asked to do it now before you can continue."]},{"h":"Limits that protect your account"},{"p":"Your session lives in a protected browser cookie that the page itself cannot read; nothing about your sign-in is kept in the browser's storage."},{"bullets":["After 8 wrong passwords within 15 minutes for the same account (from anywhere), or 30 wrong passwords from the same network for any accounts, you'll see \"Too many failed attempts. Please wait about 15 minutes and try again.\" Attempts sent at the same moment are taken one at a time.","You have 10 minutes to enter your 2FA code after your password. After that, sign in again.","A 2FA code works once. If a code was just used (or refused), wait for the next one in your authenticator app.","6 wrong 2FA codes within 15 minutes pauses 2FA sign-in for about 15 minutes.","ITOps signs you out after a period with no mouse or keyboard activity (30 minutes unless your administrator changed it). A warning appears about a minute before. The server ends the session too, so a tab left open does not stay signed in."]},{"qa":[{"q":"I forgot my password. Is there a reset link?","a":"No. ITOps has no self-service password reset. Ask your ITOps administrator to set a new one for you. If you normally use \"Sign in with Microsoft 365\", reset your Microsoft password the usual way instead."},{"q":"It says \"Invalid email or password\" but I'm sure it's right.","a":"Check for typos and Caps Lock. The same message appears if your account is inactive or was set up for Microsoft sign-in only; your administrator can check."},{"q":"I don't see \"Sign in with Microsoft 365\".","a":"Microsoft sign-in hasn't been set up for your organisation. Use your email and password."}]},{"p":"Administrators: set a new password under Administration → Users → edit the user → \"Password\".","mod":"users:edit"}]},{"title":"Turning on two-factor authentication (2FA)","for":"everyone","body":[{"p":"Two-factor authentication adds a second check when you sign in with a password: a 6-digit code from an authenticator app on your phone. Use it to protect your account; your organisation may require it."},{"steps":["Click your name at the top right to open \"My profile\".","Under \"Two-factor authentication\", choose \"Set up 2FA\".","Open an authenticator app (Microsoft Authenticator, Google Authenticator, 1Password and similar) and scan the QR code. If you can't scan, type the \"Manual key\" shown under it.","Type the 6-digit code the app shows and choose \"Verify & turn on\".","ITOps shows 10 backup codes (like AB12-CD34). Choose \"Copy codes\" and store them somewhere safe, then choose \"Done\". They are not shown again."]},{"p":"From then on, after your password you'll be asked for a code. Each backup code works once, in place of an app code."},{"h":"Moving to a new phone or turning it off"},{"steps":["Open \"My profile\" and choose \"Turn off\" next to \"On — codes from your authenticator app\".","Enter a current 6-digit code, or your password, and confirm. Your old backup codes stop working.","Choose \"Set up 2FA\" again on the new phone. You get a fresh set of backup codes."]},{"warn":"If your organisation requires 2FA, turning it off means you'll be asked to set it up again the next time you sign in."},{"qa":[{"q":"I lost my phone and my backup codes.","a":"Ask a Super Admin to reset your 2FA. You can then sign in with just your password and set it up again."},{"q":"I sign in with Microsoft 365 and there's no \"Set up 2FA\" button.","a":"Your second step is handled by Microsoft, so My profile says it's managed by your organisation's Microsoft account."},{"q":"My code is always rejected.","a":"Make sure the time on your phone is set automatically. Codes change every 30 seconds."}]},{"p":"Super Admins: to reset someone's 2FA, open the person in Administration → Users and choose \"Reset 2FA\" under \"Two-factor authentication\" (it shows whether their 2FA is on). To require 2FA, go to Administration → Settings → General → Session security → \"Require two-factor authentication for\" and choose \"Admins only (Super Admin & Dept Admin)\" or \"All password (local) users\". Microsoft 365 sign-in users are always exempt.","mod":"settings:edit"}]},{"title":"My profile: password, two-factor and where you are signed in","for":"everyone","body":[{"p":"My profile holds your personal settings. Open it by clicking your name (with your initials) at the top right. It is a page of its own."},{"bullets":["Your details: name, email, role, department, how you sign in, your last sign-in. The role and department are set by an administrator.","\"My name\": change your display, first and last name (accounts that sign in with email and password). Accounts that sign in with Microsoft 365 get their name from Microsoft.","\"Password\": change your own password (see below).","\"Two-factor authentication\": set it up, see that it is on, or turn it off. See \"Turning on two-factor authentication (2FA)\".","\"Where you are signed in\": every browser and device signed in to your account, with its address and when it was last used. \"Sign out\" ends one; \"Sign out of the others\" ends all but this browser.","\"Recent activity\": your last sign-ins and password changes. Something you don't recognise? Change your password, sign out of the other devices and tell IT.","\"Preferences\": the language of the emails ITOps sends you, and light or dark mode."]},{"h":"Changing your password"},{"steps":["Open My profile → \"Password\".","Type your current password, then the new one twice.","The new password needs at least 12 characters, a letter and a number, and must not contain your name, your email or a common word. The list under the fields turns green as each rule is met.","Click \"Change password\". You are signed out everywhere else; this browser stays signed in."]},{"p":"After five wrong current passwords, changing it waits about 15 minutes. If you sign in with Microsoft 365, your password is changed in Microsoft (myaccount.microsoft.com)."},{"qa":[{"q":"I only see the two-factor section and a notice.","a":"Your organisation requires 2FA and you haven't set it up. Finish the setup and the rest of ITOps opens."},{"q":"Emails still arrive in the wrong language.","a":"Check the email language in My profile → Preferences. \"Organisation default\" follows the setting your administrator chose."},{"q":"I forgot my password.","a":"Ask your ITOps administrator to set a new one (Administration → Users). Every session you have open ends when they do."}]},{"p":"Administrators can also set a user's email language and password under Administration → Users. Super Admins reset someone's 2FA on that person: Administration → Users → open the person → \"Reset 2FA\".","mod":"users:edit"}]},{"title":"Finding your way around","for":"everyone","body":[{"p":"This topic explains the screen layout so you can find things quickly."},{"h":"The left menu"},{"bullets":["Dashboard is always at the top, with \"Announcements\" right under it (a red number shows how many are new or waiting for your confirmation). Below them are groups: Service Desk, Knowledge, Assets & Vendors (Equipment, Credentials, Contracts, Invoices, IT Budget, Vendors), Microsoft 365 (Home, People — including onboarding and offboarding —, Email, Devices, Licenses, Security, Posture, Collaboration & activity), IT Operations (Server Guardian, Server performance, Uptime, Backups), Administration (users, roles, categories, forms, import, onboarding templates, Settings) and Logs & Integrations (What's New first, then audit and event logs, integrations and Integration Audit). Click a group to open it.","You only see the items your role allows. If you open a page you can't use, you'll see \"No access\" and a \"Back to Dashboard\" button.","Click the logo or the menu icon (three lines) to shrink the menu to icons. On a phone, the menu icon opens and closes it."]},{"h":"The top bar, left to right"},{"bullets":["The page name, then the search box \"Search tickets, KB, SOPs…\". Type 2 or more letters to search tickets, articles, SOPs, vendors and contracts you're allowed to see. Choosing a result opens that page.","The bell: your notifications, with a red count of unread ones. See \"Your notifications (the bell)\".","Your name: opens Account (email language, 2FA, sign out).","The camera: \"Capture\" a photo, video or screenshot and attach it to a ticket.","The question mark: opens this Help Center in a side panel. The ↗ button opens it in a full page.","The half-moon: switches between light and dark mode.","The door: signs you out."]},{"tip":"A coloured banner across the top of the page is a short notice from your administrators, for example planned maintenance. A bar that says an announcement is waiting takes you to the Announcements page."},{"p":"For your security, ITOps signs you out after a period with no activity (30 minutes unless changed). Anything you haven't saved is lost, so save forms before you step away."},{"p":"Administrators set the idle sign-out time in Administration → Settings → General → Session security → \"Idle timeout (minutes)\", then \"Save\".","mod":"settings:edit"},{"h":"Dropdown lists"},{"p":"Every dropdown list in ITOps looks and works the same way, on every computer and browser — in the app, on the public help and form pages, and in the separate editor window. Click the field to open the list and click a choice. The current choice is highlighted."},{"bullets":["The list always opens on top of the page, so a table or a panel never cuts it off. Near the bottom of the window it opens upward.","Keyboard: move to the field with Tab, then ↓ or ↑ opens the list and moves through it; Home and End jump to the first and last choice; Enter or Space chooses; Esc closes without changing anything.","Type the first letters of a choice to jump to it — handy in long lists such as people or roles.","A click anywhere else, or scrolling the page, closes the list without changing the choice.","A greyed-out dropdown cannot be changed right now, usually because something else on the screen has to be chosen first or your role does not allow it."]},{"h":"Previews and times"},{"bullets":["Every report or document made in the newer areas (IT Budget, the budget document, Calendar reports, Uptime reports, the branding sample) opens as a preview first. Check it, then download it from the preview as PDF, Word or CSV. Previews are written to the Audit Log as previews; downloads as exports.","All times are shown in the installation's time zone (Settings → General → Time zone) in 12-hour format with AM and PM — for example 10/10/2026 2:05 PM."]}]},{"title":"Your notifications (the bell)","for":"everyone","body":[{"p":"The bell at the top right collects short in-app messages about things that need your attention, so you don't have to rely on email."},{"h":"What you might see"},{"bullets":["\"New comment\": someone commented on a ticket you opened or are assigned to. It shows the ticket number and the start of the comment.","\"Ticket assigned to you\": you are the new assignee of a ticket.","\"Update · TK-…\" or a custom title: a support agent sent you a message about a ticket with the Notify button.","\"Response SLA due soon\", \"Resolution SLA breached\" and similar: a ticket you are assigned to is close to, or past, its target time.","Procedure reminders such as \"Please acknowledge SOP: …\", signature requests, equipment return requests and overdue loans, and onboarding task reminders.","Announcements sent to you, and reminders for the ones you have not confirmed. Clicking one opens the Announcements page."]},{"h":"Using it"},{"steps":["Click the bell. Unread items are highlighted and listed first (the latest 50 are shown).","Click an item to mark it read and jump to the related page, for example Tickets. Then open the ticket from the list.","Choose \"Mark all read\" to clear the red count."]},{"p":"The bell checks for new items every minute and each time you open it."},{"qa":[{"q":"I replied by email but the assignee says they got no alert.","a":"Email replies are added to the ticket, but they don't create a bell notification. For anything urgent, add a comment in the app instead."},{"q":"Clicking a notification doesn't open the ticket itself.","a":"It opens the Tickets page. Find the ticket number from the notification in the list."}]}]},{"title":"Getting help","for":"everyone","body":[{"p":"Use this Help Center first. If it doesn't answer your question, raise a ticket so the right person can help."},{"bullets":["In ITOps, click the question mark in the top bar to open the Help Center beside your work.","Use the search box at the top of the Help Center to jump to any topic.","The Help Center only shows topics for the features your role can use. If you aren't signed in you see the general topics; sign in to see the rest.","The full User Guide, the Administrator Guide and the quick starts are Word files your IT team keeps outside the app. Ask them for a copy."]},{"p":"Your team's own articles (for example how to connect to the office Wi-Fi) are in Knowledge → Knowledge Base. Search them with the top search box.","mod":"kb"},{"p":"Knowledge → Ask IT lets you type a question in plain words (for example \"I can't get my email on my phone\") and choose \"Send\". It answers from the published Knowledge Base.","mod":"kb_assist"},{"p":"Still stuck? Create a ticket in Service Desk → Tickets → \"+ New Ticket\", or use the request form or help-desk email address your team shared."}]},{"title":"How New and Edit screens open","for":"everyone","body":[{"p":"When you create, edit or open a record (a ticket, an equipment item, a loan, a vendor, a policy, a finding and so on), it opens as a full page in place of the list. Nothing pops up over the screen."},{"bullets":["\"← Back\" (or ✕) at the top returns you to the list exactly as you left it: the same filters, search and scroll position.","Save and Cancel are always reachable: in the bar at the top next to \"← Back\", or pinned to the bottom of the screen on longer forms.","Some screens lead to another one. For example, an equipment item's page has \"Loan this item\". The new page replaces it, and \"← Back\" returns to the item.","Small questions still appear as a box: \"Are you sure?\" confirmations, file uploads, a one-time password or Temporary Access Pass that is shown only once, and choosing an icon."]},{"h":"A list and the record side by side"},{"p":"A few screens keep the list in sight while you work on one record:"},{"bullets":["Microsoft 365 → People: the account opens in a panel over the right part of the list, below the tabs. \"Edit Microsoft 365 info\" opens inside the same panel.","Administration → Onboarding Templates: the templates are listed on the left, the one you work on is on the right.","Logs & Integrations → What's New: the builds on the left, the notes of the one you pick on the right.","When something was changed and not saved, opening another record or closing asks first: \"Leave without saving\" or \"Keep editing\".","On a narrow screen or a phone the record takes the whole width, with a button to go back to the list."]},{"h":"\"About this screen\""},{"p":"Many screens have a round ⓘ \"About this screen\" button in the top bar, next to the page title. Click it to read what the screen does, what it needs and what to expect. It opens over the page and never pushes the screen down; a click anywhere else or Esc closes it. When something the screen needs is missing, the button says so in red (\"1 missing\") without being opened. On a narrow screen only the ⓘ is shown."}]},{"title":"Using ITOps on a phone","for":"everyone","body":[{"p":"ITOps works in the phone browser. The menu icon (three lines) opens the left menu; tap a group, then a page."},{"bullets":["Every New, Edit and detail screen opens as a full page (see \"How New and Edit screens open\"). The Save / Cancel buttons stay on screen while you scroll: in the bar at the top next to \"← Back\", or pinned to the bottom of the screen for longer forms such as tickets and equipment.","On the Tickets page the category panel starts collapsed on a phone. Tap the small arrow at the top left of the list to open it.","On a narrow screen the top bar shows only the menu, search, notifications, your avatar, Capture and Help. Tap your avatar to switch light/dark mode or to sign out.","If a button is still hidden behind the browser bar, scroll a little: the page fits itself to the visible area on current iPhone and Android browsers."]}]},{"title":"Using ITOps inside Microsoft Teams","for":"everyone","body":[{"p":"If your organization added ITOps to Teams, you can use it without leaving Teams and without signing in: Teams tells ITOps who you are. Everything also keeps working in your browser, exactly as before."},{"h":"Opening it"},{"steps":["In Teams, look for ITOps in the bar on the left (or under \"…\" → more apps, where you can right-click it and choose \"Pin\").","Click it. The first time, Teams may ask you to allow the app to use your account: accept. You are then signed in automatically.","The app has two tabs at the top: the whole of ITOps, and \"Announcements\"."]},{"h":"Notifications in Teams"},{"bullets":["New announcements (and, if your administrators switched them on, ticket updates and alerts) also appear in your Teams \"Activity\" feed. Click one to open the matching page inside Teams.","The bell inside ITOps still holds everything. Teams notifications arrive a few minutes after the bell.","An announcement posted in a Teams channel has a button that opens the Announcements page inside Teams, where you click \"✓ I have read this\".","To mute them: Teams → Settings → Notifications and activity."]},{"h":"What is different inside Teams"},{"bullets":["There is no sign-out button: you are signed in as the person signed in to Teams.","If automatic sign-in does not work, a message at the top says why and the normal email and password form is shown. \"Sign in with Microsoft\" is not offered there; use it in the browser.","Links to other sites open in your browser. If a download (CSV, PDF) does not start inside Teams, open ITOps in your browser for that step."]},{"qa":[{"q":"I do not see ITOps in Teams.","a":"It has not been added for you yet, or the change has not reached your Teams (it can take a few hours). Search for it under Apps, or ask IT."},{"q":"It says \"Automatic sign-in from Teams did not work\".","a":"Click \"Try again\". If it keeps failing, send the message to IT: it names the cause. You can still sign in with your email and password, or use the browser."},{"q":"Does ITOps see my computer through Teams?","a":"No. It only records which operating system and Teams client you opened it with, like any website can see, so IT knows what kinds of devices are in use."}]}]}]},{"cat":"Administration & setup","topics":[{"title":"Settings: the page and its four access areas","for":"admin","mod":["settings","branding","email_cfg","sla_cfg"],"body":[{"p":"Administration → Settings is where ITOps itself is configured. It has one tab per area, and Roles & Permissions grants each area separately, so a person only sees the tabs they are allowed to use."},{"bullets":["General (Settings · General): backend connection and API base URL, About (build number), session security (idle timeout and the 2FA rule — Super Admin saves these), trusted redirect hosts.","Branding (Settings · Branding): application name, logo, favicon and the navigation icons.","Email and Email templates (Settings · Email): outbound mail, the help-desk intake mailbox, the notification switches and the English/Spanish templates.","SLA & Hours (Settings · SLA & Hours): SLA warning thresholds, the daily digest and the business-hours clock.","Sign-in & AI (Settings · General): Microsoft 365 sign-in (SSO) and the AI assistant. Changing the tenant, app or secret is Super Admin only.","Help visuals: who sees each interactive page of the Help Center. Super Admin only.","Maintenance: database updates. Super Admin only, always.","Some settings are Super Admin only, whatever the role: who sees every case and the Change Advisory Board, the trusted redirect hosts and the public form redirect, the scheduler key, sign-in lockout and session rules, break-glass and Teams settings, Microsoft 365 (including the mailbox the app reads and sends mail from). A refused change is written to the Audit Log."]},{"tip":"This page used to be called \"Connection\". Older screenshots and notes that say Administration → Connection mean Administration → Settings."}]},{"title":"Branding","for":"admin","mod":"branding:edit","body":[{"p":"Branding puts your organisation's name, logo and browser-tab icon on ITOps and on its public pages. Set it once after installing, and again whenever your logo changes."},{"p":"Where it lives: Administration → Settings → \"Branding\" tab. You need Settings with Edit to save changes."},{"steps":["Open Administration → Settings and click the \"Branding\" tab.","Under \"Application name\", type the name people should see (for example \"Example Co. IT\") and click \"Save\". If you leave it blank, the product name \"ITOps⁠\" is used.","Under \"Logo\", click \"Upload\" and choose the image. Do the same under \"Favicon\". Click \"Remove\" to go back to none. (The logo and the icon are always uploaded; an address cannot be typed in.)","Optional: in \"Public form redirect URL\", enter the page people should land on after they submit a web form and click Done, then click \"Save\". Leave it blank to send them back to the page they came from.","Optional: in the \"Navigation icons\" card, click \"Change\" next to any menu item (the groups and the top bar too) to pick a different emoji below the list, or paste your own, then click \"Save icons\": the menu changes at once. Other windows already open — another browser tab, or the installed app on a Mac, Windows PC or phone — pick the change up when they come back to the front (and every 10 minutes): no need to sign out. \"Reset to defaults\" puts the original icons back."]},{"h":"Where each item shows"},{"bullets":["Application name: everywhere people see the app — the menu, sign-in screen and browser tab, every screen and message, all emails (the [name] tag in subjects, the email header and the {{app_name}} placeholder), this Help Center, the public request, form and signing pages, the What’s New page and the label in authenticator apps (for 2FA set up after the change). Names of the policies and rules the app creates in Microsoft 365 keep the product name \"ITOps⁠\", because that is how the app finds them again.","Logo: the sidebar, the sign-in screen, public forms, the request page and the help portal. It can also go at the top of every email: tick \"Show the logo (Branding tab) at the top\" under Email templates → \"Header, footer & language\".","Favicon: the small icon in the browser tab.","Navigation icons: the sidebar and top bar, for everyone."]},{"h":"Documents (PDF and Word)"},{"p":"The \"Documents (PDF and Word)\" part of the Branding tab sets what every document made by the app carries — the IT budget document and the calendar reports: the organization's name, its logo on the cover and at the top of each page, the footer (\"Confidential — for internal use\" to start) and the colour of headings and tables. Upload the organization's logo if it differs from the app logo (PNG or JPG; a wide logo prints best). \"Sample PDF\" and \"Sample Word\" show the result. Every change is in the Audit Log with the values before and after."},{"p":"\"Preview a sample\" shows a one-page sample with the current name, logo, footer and colour before you make any real document; download it as PDF or Word from the preview."},{"warn":"Use PNG, JPG, GIF, WEBP or ICO files up to 5 MB. SVG files are refused for security reasons, so convert an SVG logo to PNG first."},{"qa":[{"q":"I uploaded a new logo but still see the old one.","a":"Hard-refresh the page (Ctrl+Shift+R on Windows, Cmd+Shift+R on Mac). Other people see the new logo on their next page load."},{"q":"I can see the Branding tab but saving gives an error.","a":"Your role has Settings with View only. Ask a Super Admin to add Edit, or to make the change for you."}]}]},{"title":"Sign-in page: the line under the logo and Microsoft first","for":"admin","mod":"branding:edit","body":[{"p":"Administration → Settings → Branding → \"Sign-in page\" decides two things about the page people sign in on."},{"bullets":["The line under the logo: type your own (up to 80 characters) and click Save. Empty it to go back to \"IT Master Operations Hub\".","How people sign in first: \"Email and password\" (the fields, with the Microsoft button under them) or \"Microsoft 365\" (only the Microsoft button; email and password appear after \"Sign in with a local account\")."]},{"p":"With Microsoft 365 first, local accounts and the Super Admin can always still sign in through \"Sign in with a local account\". If Microsoft sign-in is not set up yet (Settings → Integrations → Microsoft 365), the page keeps showing email and password, so nobody is locked out. Inside Teams, people are signed in by Teams as before."}]},{"title":"The license file: what it decides, the trial and the notice","for":"admin","mod":"license","body":[{"p":"Each installation has a license file, itops-license.php, in its folder next to config.php. Indisse-BTS issues it for that installation (it names the installation ID shown in About & ownership). It says which plan and modules are included, how many users, and for how long."},{"bullets":["The file is signed by Indisse-BTS. Any change to it, even one character, makes the signature fail; About & ownership → License record shows \"Signature: Genuine\" when it is unchanged.","Never edit the file. For a different plan, more users or a new term, ask Indisse-BTS for a new file and replace the old one.","Settings → Modules shows what the file includes; a Super Admin can still switch included modules off."]},{"h":"No file, or a file that is not valid"},{"bullets":["Without a valid file (none, edited, damaged, issued for another installation, or a term that ended more than 14 days ago), every module works as a 30-day trial.","After the trial only the core stays on: sign-in, users, roles, settings, logs, Help and About & ownership. Nothing is deleted: the modules and their data come back as soon as a valid file is in place.","When the term has ended, everything keeps working for 14 more days so there is time to renew.","Super Admins and the people with \"License details\" see a notice at the top of every page saying what is wrong and until when."]},{"h":"Installing a new license file"},{"steps":["Indisse-BTS sends the file itops-license.php.","Upload it to the installation folder (next to config.php), replacing the old one.","Open About & ownership: the License record shows the new number and \"Signature: Genuine\", and the notice at the top is gone."]}]},{"title":"Business hours","for":"admin","mod":"sla_cfg:edit","body":[{"p":"Business hours make SLA due times count working time only, so a ticket logged late on Friday isn't already overdue on Monday morning."},{"p":"Where it lives: Administration → Settings → \"SLA & Hours\" tab → \"Business hours (SLA clock)\" card. Saving needs Settings with Edit."},{"steps":["Tick \"Count SLA in business hours\".","Set \"Day starts\" and \"Day ends\". The defaults are 09:00 and 17:00.","Type the \"Time zone\" in the standard IANA format, for example America/New_York (the default) or America/Chicago.","Click the \"Working days\" buttons to switch days on or off. Monday to Friday are on by default.","In \"Holidays\", type one date per line as YYYY-MM-DD, for example 2026-12-25.","Click \"Save business hours\"."]},{"h":"What happens next"},{"bullets":["Only tickets created after you save use the new clock. Existing due times don't move.","Evenings, non-working days and holidays are skipped. Example: with 9–5, Monday to Friday, an 8-hour target on a ticket created at 3 pm Friday is due at 3 pm Monday.","To go back to plain calendar time, untick the box and save."]},{"warn":"Check the time zone spelling carefully. If ITOps doesn't recognise it, it quietly uses UTC and every due time will be off by several hours. If \"Day ends\" is not later than \"Day starts\", ITOps uses 09:00–17:00 instead."},{"tip":"Add next year's holidays in December. Lines that are not in YYYY-MM-DD format are dropped when you save."},{"qa":[{"q":"A ticket's due time looks wrong.","a":"Check the time zone first. Then check when the ticket was created: tickets created before you changed business hours keep their old due times."},{"q":"The Save button gives an error.","a":"Your role has Settings with View only. You need Edit."}]}]},{"title":"Setting up the AI assistant","for":"admin","mod":"settings:edit","body":[{"p":"AI assist gives agents a ticket summary, a suggested category and priority, and a draft reply. The same key also powers Ask IT and the AI helpers for SOPs. It is optional and stays off until you turn it on."},{"p":"Where it lives: Administration → Settings → \"Sign-in & AI\" tab → \"AI assist\" card. Saving needs Settings with Edit."},{"steps":["Tick \"Enable AI assist\".","Choose the \"Provider\": \"Anthropic (Claude)\" or \"OpenAI\".","Type the \"Model\" name. If you leave it blank, ITOps uses claude-haiku-4-5-20251001 (Anthropic) or gpt-4o-mini (OpenAI) for ticket help.","Paste your \"API key\" (only a Super Admin can save or replace keys). After saving, the label says a key is saved. Leave the field blank later to keep it.","Optional: paste a \"Transcription key — OpenAI Whisper\" so agents can transcribe audio and video attachments. With OpenAI as the provider, you can leave it blank and the main key is used.","Click \"Save AI settings\"."]},{"h":"What happens next"},{"bullets":["Agents with access to Tickets see the AI options on a ticket. Each use sends one request to the provider you picked, which may cost money.","Keys are stored encrypted on your server and are never shown again in the browser.","Ask IT answers from your published Knowledge Base. Questions it can't answer collect under Knowledge → KB Content Gaps."]},{"warn":"Your server must be able to reach api.anthropic.com or api.openai.com. If a firewall blocks it, the AI buttons return an error."},{"qa":[{"q":"Agents say the AI gives an error about the key.","a":"The message \"No AI API key is configured\" means no key has been saved. Paste it again and click \"Save AI settings\"."},{"q":"Transcription doesn't work with Anthropic.","a":"Transcription uses OpenAI Whisper. Add a \"Transcription key — OpenAI Whisper\"."}]}]},{"title":"Outbound email: how ITOps sends mail","for":"admin","mod":"email_cfg:edit","body":[{"p":"Outbound email is how ITOps sends every system email: ticket acknowledgements and replies, SLA alerts, reminders, signature requests and onboarding emails. Set it up first, because nothing is sent until it's on."},{"p":"Where it lives: Administration → Settings → \"Email\" tab, in the lower half of the card, \"Outbound email — acknowledgements & replies\". Saving needs Settings with Edit."},{"steps":["Tick \"Enabled\" next to \"Outbound email — acknowledgements & replies\". It is off on a new install.","Enter the \"From name\" (default IT Help Desk) and the \"From address\".","Choose \"Send via\": \"Server mail (PHP mail)\", \"SMTP\" or \"Microsoft 365 (Graph)\".","For SMTP, fill in \"SMTP host\", \"Port\" (587), \"Security\" (STARTTLS), \"SMTP user\" and \"SMTP password\". For an Office 365 mailbox, click \"Use Office 365 preset\" first. A blank SMTP user or password reuses the mailbox username or password from the intake section.","For Microsoft 365 (Graph), fill in the \"Microsoft 365 / Azure\" card on the \"Integrations\" tab, including \"Help-desk mailbox (Graph send/receive)\".","Choose the ticket emails you want with the tick boxes (see below).","Click \"Save settings\", then click \"Send test email to myself\"."]},{"h":"The tick boxes"},{"bullets":["\"Acknowledge new emails\": whoever emails the help desk gets a \"Request received\" reply. Off by default.","\"Email requester on reply\": the requester gets agent replies. Off by default.","\"Email requester on status change\": the requester hears when the status changes, including resolved and closed. Off by default.","\"Email assignee when a ticket is assigned\": on by default.","All other emails (web-form acknowledgements, SLA alerts, reminders, signatures, onboarding) are switched on or off one by one under the \"Email templates\" tab."]},{"h":"The outbound email log"},{"p":"The table at the bottom shows the last 40 send attempts: When, To, Subject, Type, Via and Result. A failed row shows the error message. With Microsoft 365, sent emails also appear in the mailbox's Sent Items."},{"warn":"Emails that are skipped because outbound email is off, or because that email is switched off under Email templates, are not written to the log. If an email is missing and not in the log, check those two switches first."},{"qa":[{"q":"Nobody is receiving emails.","a":"Check that \"Enabled\" is ticked and saved, then use \"Send test email to myself\" and read the Result column in the log."},{"q":"Sending through Microsoft 365 fails with a permissions error.","a":"The Azure app needs the Mail.Send application permission, with admin consent. See \"Microsoft 365 sign-in\"."},{"q":"Requester replies create new tickets instead of threading.","a":"The reply subject must still contain the ticket number (for example TK-2026-0142), and \"Replies\" in the intake section must be \"Thread onto existing ticket\"."}]}]},{"title":"Editing the emails ITOps sends (English & Spanish)","for":"admin","mod":"email_cfg:edit","body":[{"p":"The Email templates screen lets you change the wording of every email ITOps sends, in English and Spanish, and switch individual emails off."},{"p":"Where it lives: Administration → Settings → \"Email templates\" tab. Settings with View lets you read the templates; changing them needs Edit."},{"p":"There are 41 emails in five groups: Tickets (9, including \"Requester replied\", \"Backup on a ticket\" and \"New ticket — nobody assigned\"), SLA & digests (5), Reminders (8), People & equipment (10, including the two device-setup invitations) and Security rollout (9 — the Business Premium rollout communications, sent from Microsoft 365 → Home → Rollout). Each one shows On, Off, or \"Off (switch)\"."},{"steps":["Pick an email in the list on the left.","Use the On/Off switch at the top to turn that email on or off.","Choose the English or Español tab and edit \"Subject\" and \"Message\".","To add a value such as the ticket number, click where it should go, then click a chip under \"Placeholders — click to insert at the cursor\". The {{app_name}} chip inserts your app name (Settings → Branding), so the emails follow it if you rename the app later.","Check the live preview, which uses sample data. Click \"Send test to me\" to receive it.","Click \"Save\". \"Discard changes\" throws away unsaved edits.","To undo your edits, click \"Reset English to default\" or \"Reset Spanish to default\". \"History\" lists past changes. Click \"Load this version\" to bring one back, then Save."]},{"h":"Formatting you can use"},{"bullets":["**bold** for bold text.","[link text](https://…) for a link. Plain https:// addresses become links automatically.","A line starting with \"- \" becomes a bullet. A blank line starts a new paragraph.","Values typed by people (subjects, comments, names) always appear as plain text, never as links or formatting."]},{"h":"Header, footer & language"},{"p":"Click \"Header, footer & language\" to set the \"Language for people without their own setting\" (English, Español, or both), the \"Brand colour\", \"Show the logo (Branding tab) at the top\", and an optional header and a footer for each language. Header and footer can only use the common placeholders. A person's own Email language (under their Account, or on their user record) always wins over the organisation default."},{"p":"The {{portal_link}} placeholder is the \"Follow it online\" box with an \"Open TK-… in ITOps\" button that opens the ticket in the app. It appears only for people who have an ITOps account; outside requesters don't see it. The five requester ticket emails include it at the end, and it is added back automatically if an edited template leaves it out. Ticket links in agent emails ({{link}}) also open that exact ticket."},{"warn":"Ticket email subjects must keep {{ticket_number}}. Replies are matched to tickets by it, so Save stays blocked until it's back."},{"qa":[{"q":"An email shows \"Off (switch)\".","a":"The email is on here, but its master switch on the \"Email\" tab is off (for example \"Email requester on reply\"). Turn that on too."},{"q":"People still get the old wording.","a":"Check you saved both languages. People with Español as their email language get the Spanish text."}]}]},{"title":"Microsoft 365 sign-in","for":"admin","mod":"settings:edit","body":[{"p":"Connecting an Azure (Entra ID) app registration lets staff sign in with their Microsoft 365 account. The same app can also send and receive help-desk email through Microsoft Graph."},{"p":"Where it lives: Administration → Settings → \"Sign-in & AI\" tab → \"Microsoft 365 / Azure\" card. Saving needs Settings with Edit."},{"steps":["In the Azure portal, open App registrations and create (or open) the ITOps app.","Under Authentication, add the Web platform and enter the Redirect URI: your ITOps address, as shown greyed-out in the \"Redirect URI (SSO)\" field.","Under API permissions, add delegated User.Read for sign-in. For Graph email, also add application Mail.Send and Mail.ReadWrite. Then click Grant admin consent.","Create a client secret and copy its value.","In ITOps, fill in \"Directory (tenant) ID\", \"Application (client) ID\", \"Client secret\" and \"Redirect URI (SSO)\". For Graph email, also fill in \"Help-desk mailbox (Graph send/receive)\".","Tick \"Enable SSO\", click \"Save\", then click \"Test Graph connection\"."]},{"warn":"Changing the tenant, client ID, redirect URI, secret or turning SSO on/off is Super Admin only — these decide who can sign in to ITOps."},{"h":"What happens when someone signs in with Microsoft"},{"bullets":["They are matched to an ITOps user: first by their Microsoft account ID once linked, otherwise by email address. The first sign-in links the two only when the Microsoft account is a member of your organisation (not a guest) and the ITOps account is not an administrator and does not use ITOps's own 2FA. For any other account, a Super Admin ticks \"Allow Microsoft sign-in to link\" on the user (Administration → Users → edit); the next Microsoft sign-in links it and the tick clears itself. After that, only that same Microsoft account can sign in to that ITOps user.","Only accounts from YOUR tenant are accepted: the \"Directory (tenant) ID\" must be your tenant's ID, not \"common\".","If there is no matching user, an account is created for them automatically with the Viewer role. Change their role under Administration → Users if they need more.","Accounts with a status other than Active are refused.","Microsoft handles their multi-factor sign-in. ITOps's own 2FA policy doesn't apply to them.","When a Microsoft or Teams sign-in fails, the screen gives a short message; the details for the administrator are in the Audit Log (o365_login_rejected, teams_login_rejected, o365_link_refused)."]},{"p":"One app registration, one configuration: the tenant, client ID and client secret entered here are the same ones used by the Microsoft 365 area and the Server Guardian page (Logs & Integrations → Integrations → \"System\" → \"Microsoft 365 connection\"). Saving the secret in either place replaces it everywhere. The secret is stored encrypted and never shown again."},{"tip":"Save before you test. The client secret is write-only: once saved, leave the field blank to keep it."},{"qa":[{"q":"The card says PHP cURL isn't available.","a":"Microsoft 365 needs the PHP cURL extension. Ask your host to enable it."},{"q":"Sign-in fails with a redirect error from Microsoft.","a":"The Redirect URI in Azure must match \"Redirect URI (SSO)\" exactly, including https and the trailing slash."}]}]},{"title":"Security: 2FA policy and idle timeout","for":"admin","mod":"settings:edit","body":[{"p":"These two settings decide who must use two-factor authentication (2FA) and how long an unused session stays signed in."},{"p":"Where it lives: Administration → Settings → \"General\" tab → \"Session security\" card. Only a Super Admin can save these settings. Anyone else gets an error."},{"steps":["Set \"Idle timeout (minutes)\". The default is 30.","Choose \"Require two-factor authentication for\": \"Nobody (opt-in)\", \"Admins (roles that manage people, settings, the vault or Microsoft 365 / vTiger accounts)\" or \"All password (local) users\".","Click \"Save\"."]},{"h":"What happens next"},{"bullets":["Idle timeout: a person who does nothing gets a warning about a minute before the limit, then is signed out. The server checks it too (the bell and other background checks do not count as activity). The new value applies on each person's next sign-in or page load.","2FA: people in scope who haven't set up 2FA must do it at their next sign-in, before they can use ITOps. They scan a QR code with an authenticator app and get 10 backup codes.","\"Admins\" covers every role that can manage people (Users), settings, integrations, the vault (Credentials), Microsoft 365 accounts or vTiger accounts, whatever the role is called, and the Super Admin.","People who sign in with Microsoft 365 are always exempt. Microsoft handles their MFA.","After 8 wrong passwords in 15 minutes the account is blocked for about 15 minutes (from any network), and a network location with 30 wrong passwords waits as well. After 6 wrong 2FA codes, the account is blocked for about 15 minutes. A 2FA code works once."]},{"h":"Resetting someone's 2FA"},{"p":"If someone loses their phone, a Super Admin opens the person in Administration → Users and clicks \"Reset 2FA\" under \"Two-factor authentication\". The person can then sign in with just their password and set up 2FA again. Resetting someone's 2FA also signs them out everywhere."},{"warn":"Setting 0 turns the idle sign-out off completely. That's convenient on a shared kiosk you watch, but risky on laptops: prefer a longer value such as 240."},{"qa":[{"q":"Saving gives \"Only a Super Admin can change ...\".","a":"These are protected settings. Ask a Super Admin to change them."}]}]},{"title":"Users: adding people and giving them a role","for":"admin","mod":["users","roles"],"body":[{"p":"The Users page is where you add people to ITOps, choose how they sign in, and give them a role that decides what they can see and do."},{"p":"Where it lives: Administration → Users. Your role's Users permission decides what you can do: View to see the list, Create to add, Edit to change, Delete to remove."},{"steps":["Click \"+ New User\".","Fill in \"Display name\" and \"Email\" (both required), and optionally \"First name\" and \"Last name\".","Pick a \"Role\". See \"Recommended role setups\" if you're unsure.","Pick a \"Department\".","Set \"Status\": Active, Inactive or Pending. Only Active users can sign in.","Set \"Auth provider\" (Super Admin only): Local (ITOps password), Microsoft 365, or Both.","Optional: set \"Email language\" (Organisation default, English or Español).","For Local or Both, type a \"Password\" and give it to the person securely. Then save."]},{"h":"Good to know"},{"bullets":["Without Users · All records (the Department Admin role, for example) you see and manage the people of your own department only: new people are added in your department, and accounts cannot be moved to another one. Roles that managed everyone's accounts before this version kept that (All records was ticked for them).","People who sign in with Microsoft 365 for the first time get an account automatically with the Viewer role. Check Users regularly and change their roles.","To stop someone signing in, set Status to Inactive. Deleting a user turns the account off (status Inactive) and ends its sessions straight away: it can no longer sign in, and its history (tickets, cases, the Audit Log) keeps the name. You can't delete your own account.","Only a Super Admin can give someone the Super Admin role, change or delete a Super Admin's account, change \"Auth provider\" or tick \"Allow Microsoft sign-in to link\".","A new role takes effect on the person's next page load.","To add many people at once, use Administration → Bulk Import."]},{"qa":[{"q":"Someone can't sign in.","a":"Check their Status is Active and their Auth provider matches how they sign in. After 8 wrong passwords they're blocked for about 15 minutes. If they lost their authenticator, a Super Admin can reset their 2FA."},{"q":"I don't see \"+ New User\".","a":"Your role needs Users with Create."},{"q":"Saving gives \"Only a Super Admin can grant the Super Admin role\".","a":"Pick a different role, or ask a Super Admin."}]}]},{"title":"Roles & Permissions: how the permission grid works","for":"admin","mod":["users","roles"],"body":[{"p":"A role is a set of permissions, module by module. Every user has one role, and it controls which menu items they see and which actions ITOps accepts from them."},{"p":"Where it lives: Administration → Roles & Permissions. Roles: View shows the list read-only. Only a Super Admin can create, change or delete roles, so nobody can give themselves more access."},{"steps":["Click \"New Role\", or click an existing role to edit it.","Enter a \"Role name\" and a short \"Description\". The \"Slug\" fills itself in.","Optional: under \"Start from a preset\", click Read-only, Help Desk Agent, Manager, Auditor or IT Administrator. \"Clear all\" empties the grid.","Tick the boxes in the grid. Each group has \"View all\", \"Full\" and \"None\" buttons, and each row has an \"All\" box.","Check the \"Sidebar preview\" on the right: it lists exactly what a user with this role will see.","Click \"Create Role\" or \"Save Changes\". People get the new access on their next page load."]},{"h":"What the columns mean"},{"bullets":["View: the page appears in the menu and can be opened. Without View it is hidden, and blocked even if someone has the link.","Create: add new records. Edit: change existing ones.","Delete: remove records.","All records (Tickets only): see every ticket, which is the agent queue, and read and write internal notes. Without it, people see only tickets they opened, own or back up, and never see internal notes.","Ticking any other box ticks View too, and unticking View clears the row. \"—\" means that action doesn't exist for the module."]},{"h":"Personal pages and sensitive modules"},{"bullets":["PERSONAL (My Signatures, My Equipment): on for every role by default, showing only the person's own items. Untick to hide.","SENSITIVE (Credentials, the Microsoft 365 change permissions — Accounts, Credentials, Directory roles, Tenant configuration —, Users, Integrations, Integration Audit, Settings · General, Settings · Email): grant with care. Credentials View reveals stored passwords.","Everyone always has the Dashboard, their own profile and notifications.","\"Full access to everything\" makes the role the same as Super Admin. Use it sparingly."]},{"h":"Always Super Admin only"},{"p":"Changing roles; granting Super Admin; the Maintenance tab (database updates); Server Guardian server actions; the 2FA policy and idle timeout; resetting someone's 2FA; vTiger provisioning and Integrations → \"System\"."},{"h":"The Settings page has four access areas"},{"bullets":["Settings · General: the General and \"Sign-in & AI\" tabs (backend connection, session security, Microsoft 365 sign-in, AI assist). Secrets, the 2FA policy and the idle timeout are still saved by a Super Admin only.","Settings · Branding: application name, logo, favicon and the navigation icons.","Settings · Email: the Email and Email templates tabs (outbound mail, the help-desk mailbox, notification switches, the English & Spanish templates). Mailbox passwords and the cron token stay Super Admin only.","Settings · SLA & Hours: SLA warning thresholds, digests and the business-hours clock.","A person sees only the tabs of the areas they hold. Give a help-desk lead \"Settings · SLA & Hours\" and \"Settings · Email\" without opening the connection settings, for example.","Roles saved before this change kept exactly the access they had: the old single \"Settings\" grant was copied to all four areas by the database update."]},{"tip":"System roles can't be deleted, and a role still held by users can't be deleted either. The Super Admin role always has full access. Only its name and description can change. A role saved by an older version shows a notice: review it and click Save to convert it."}]},{"title":"Recommended role setups","for":"admin","mod":["users","roles"],"body":[{"p":"These four setups cover most organisations. Build each one under Administration → Roles & Permissions (Super Admin only), starting from the preset named, then adjust."},{"h":"Requester (all staff)"},{"p":"Start from \"Read-only\" (the same as the built-in Viewer role)."},{"bullets":["Tickets: View + Create. No Edit and no All records, so they only see their own tickets and never see internal notes.","Knowledge Base, Ask IT, SOPs (to read and acknowledge), Job Descriptions, Calendar, What's New: View.","My Signatures and My Equipment: leave on.","The preset also gives View on Equipment, Contracts and Vendors. Untick them if staff shouldn't browse those lists."]},{"h":"Support agent"},{"p":"Start from \"Help Desk Agent\"."},{"bullets":["Tickets: all five boxes, including All records (the queue).","Calendar: full. Reports: View. Ticket Categories: View.","Knowledge Base: View, Create, Edit. Consider adding KB Content Gaps (View + Edit) so agents can turn unanswered questions into articles.","Equipment: View, Create, Edit. Contracts and Vendors: View.","Leave Credentials off unless the agent really needs vault passwords."]},{"h":"IT manager"},{"p":"Start from \"IT Administrator\" for someone who runs the system, or \"Manager\" for a team lead who shouldn't touch settings."},{"bullets":["IT Administrator gives every module, including Users, Credentials, every Microsoft 365 change permission except Directory roles, Integrations, all four Settings areas, Audit Log and Event Log. It can't change roles or run database updates.","Manager is the agent set plus Scorecard, Standards & Audits (View + Edit), SOP and Job Description authoring, full Contracts and Vendors, Onboarding templates & history, the two vTiger Provisioning permissions, KB Content Gaps, and View on Credentials, Users, Microsoft 365 and Server Guardian.","Unassigned-ticket SLA alerts, the weekly digests and the \"Admins only\" 2FA rule apply only to the built-in Super Admin, Admin and Department Admin roles. If your IT manager should get those alerts, give them the built-in Department Admin role and adjust its grid."]},{"h":"HR / People Ops"},{"p":"Start from \"Read-only\", then add:"},{"bullets":["Onboarding templates & history: View (to follow joiners and leavers in Microsoft 365 → People → History). Add Edit if HR maintains the onboarding templates.","Job Descriptions: View, Create, Edit. SOPs: View.","Equipment: View, to see what a person has been issued.","Leave the Microsoft 365 change permissions off unless HR onboards and offboards people themselves. Onboard / Offboard need \"Microsoft 365 · Accounts\"; the license, group and vTiger parts need \"Microsoft 365 · Licenses\", \"· Groups\" and the two \"Provisioning\" permissions. Otherwise IT runs them.","Leave Credentials and Users off."]},{"tip":"Anyone who reviews activity (for example an external auditor) can use the \"Auditor\" preset: read-only everywhere, including the Audit Log and Event Log."}]},{"title":"Bulk import","for":"admin","mod":"import","body":[{"p":"Bulk Import creates many users, vendors, contracts or vault credentials at once from a CSV file, instead of entering them one by one."},{"p":"Where it lives: Administration → Bulk Import. You need Bulk Import with View, plus Create on the module you are importing into (Users, Vendors, Contracts or Credentials)."},{"steps":["Click the type you want: \"Users\", \"Vendors\", \"Contracts\" or \"Credentials\".","Click \"Download template\" to get a CSV with the right header row.","Fill it in with a spreadsheet program and save it as CSV. Columns can be in any order.","Click \"Upload CSV file\", or paste the rows into the box.","Check the \"Preview\". It shows how many rows were found and the first three.","Click the \"Import …\" button.","Read the \"Result\": how many rows were created, skipped as duplicates, or had errors, with the row number and reason."]},{"h":"What each type needs"},{"bullets":["Users: email and display_name are required. role is a role name or slug; if it's blank or not recognised, Viewer is used. status is active, inactive or pending. If password is blank, a random one is set, so the person signs in with Microsoft 365 or gets a password from you. Existing emails are skipped.","Vendors: name is required. risk_tier is low, medium, high or critical (medium if blank). Existing names are skipped.","Contracts: title, start_date and end_date are required (use YYYY-MM-DD). vendor must match an existing vendor name. owner is a user's email.","Credentials: name is required. username, password, api_key and notes are encrypted as they are imported. owner is a user's email (you, if blank). rotation_days defaults to 90."]},{"warn":"Contracts and credentials are not checked for duplicates. Importing the same file twice creates everything twice."},{"warn":"A credentials CSV holds passwords in plain text. Delete the file from your computer as soon as the import is done."},{"tip":"Up to 5,000 rows can be imported at a time. Each import is recorded in the Audit Log."},{"qa":[{"q":"The Users button fails with \"Insufficient permissions\".","a":"Your role has Bulk Import but not Create on Users. The same applies to the other types. A row with the Super Admin role is refused unless a Super Admin runs the import."}]},{"p":"Every record an import creates is in the Audit Log (\"imported\", with its values; never a password or secret), plus one summary line. Without Users · All records, people are added to your own department only."}]},{"title":"Updating ITOps to a new build","for":"admin","mod":"settings:edit","body":[{"p":"Every ITOps release comes as one full zip, and the same zip is used for new installs and for updates. Follow these steps to update without losing settings or files."},{"p":"Who can do it: someone with cPanel access to the server, plus a Super Admin in ITOps for the database step."},{"h":"Why it's safe"},{"p":"Since 0621-BT90 the app comes compiled (app.js) and its libraries are in the vendor folder: the browser loads nothing from other sites. The source of the app is in the src folder (closed to the web)."},{"bullets":["The zip never contains config.php, only config.sample.php, so your configuration can't be overwritten.","The zip never contains files inside public/uploads/, so uploaded logos, attachments and evidence are untouched."]},{"steps":["Read the new build's entry at the top of CHANGELOG.txt in the zip.","In cPanel File Manager, upload the zip into the same ITOps folder and choose Extract, letting it overwrite existing files. Files must sit at the folder root, not in a subfolder.","If the entry says \"DB UPDATE REQUIRED\": signed in as a Super Admin, open https://YOUR-SITE/db-update.php and click \"Apply updates now\". Or use Settings → Maintenance → \"Apply updates now\".","If the entry says a new vTiger bridge build is needed: upload vtiger-bridge/itops-bridge.php from the zip to the vTiger web root, replacing the old file. Keep the same URL and the same secret (itops-bridge.secret stays as it is). Then click \"Test bridge\" in the vTiger provisioning card (Administration → Onboarding Templates).","Hard-refresh the browser (Ctrl+Shift+R or Cmd+Shift+R).","Check the build stamp. Settings → General → About → Version (for example \"build 0621-BT6\") must match the CHANGELOG entry. Logs & Integrations → What's New should show the new entry at the top."]},{"tip":"Take a backup before you extract: the database with Settings → Maintenance → \"⬇ Download backup\" (or cPanel), and the ITOps folder in cPanel. After the update, open https://YOUR-SITE/api/health. It should show {\"status\":\"ok\",\"database\":true}."},{"warn":"If the version still shows the old build after a hard refresh, the files didn't land in the right folder. Check that app.js and index.html in the ITOps folder have a new modified date."},{"qa":[{"q":"Do I need to run the installer again?","a":"No. The installer is only for new installs and refuses to run once ITOps is installed."},{"q":"Which vTiger bridge build is current?","a":"It's named at the top of vtiger-bridge/READ-ME.txt and in the CHANGELOG (currently build o8). If the CHANGELOG says no new bridge file, leave the vTiger server alone."}]}]},{"title":"Database updates","for":"admin","mod":"settings:edit","body":[{"p":"Some ITOps updates change how data is stored. A database update applies those changes, and you run it after installing a build whose CHANGELOG entry says \"DB UPDATE REQUIRED\"."},{"p":"Who can run it: Super Admin only. Other roles don't see the Maintenance tab."},{"steps":["Open Administration → Settings and click the \"Maintenance\" tab.","The \"Database Updates\" card shows either \"Your database is up to date.\" or how many updates are available.","Click \"Apply updates now\".","Wait for the message: \"Applied N updates\", \"Already up to date\", or an error."]},{"p":"Or open https://YOUR-SITE/db-update.php in the same browser while you're signed in as a Super Admin. It lists the pending updates and has its own \"Apply updates now\" button."},{"h":"Good to know"},{"bullets":["It's safe to run as often as you like. It only applies what is missing.","It never changes config.php or your uploaded files.","Each run is recorded in the Audit Log.","Some screens tell you to run it, for example if the integration tables or the outbound email log don't exist yet."]},{"qa":[{"q":"db-update.php says \"Please sign in to ITOps as an administrator first\".","a":"Sign in to ITOps as a Super Admin in the same browser, then reload the page."},{"q":"An update shows an error.","a":"Copy the message, don't keep retrying, and send it with the build number (Settings → General → About → Version) to whoever supports your install."}]},{"p":"Under \"Update history\" the card lists every database update with the date it was applied (pending ones first). Below it, \"Database health\" shows the database itself — see \"Database health, housekeeping and backup\"."}]},{"title":"Database health, housekeeping and backup","for":"admin","body":[{"p":"Administration → Settings → \"Maintenance\" shows what is happening inside the database, so you can watch it and look after it without going to the server, cPanel or phpMyAdmin. Super Admin only."},{"h":"What you see"},{"bullets":["Tiles: total size of the ITOps tables (and how much it grew in the last 7 days), number of tables, rows, open connections against the server limit, how long the database server has been up and how many checks need a look. Sizes and row counts come from the server's own statistics, so they are close estimates.","\"Size over time\": a small chart of the size, from one snapshot saved each day by the scheduled job (it starts filling in the day after you install this build).","\"Health checks\": core tables present, database updates applied, every table on InnoDB, one collation for all tables, no large wasted space, ID counters far from their limit, connections below the limit, and the database clock agreeing with the web server. Anything amber or red says what to do.","\"Server settings\": version, character set, time zone, buffer pool, slow queries, SQL mode and other server values, read-only.","Some shared hosts hide the server counters; the connection and uptime tiles then show \"—\" and everything else still works."]},{"h":"Tables"},{"bullets":["Every ITOps table with what it holds, its rows, size, index size, free space, growth over 7 days and when it last changed. Click a column header to sort, or search by name.","\"Maintain…\" on a row: \"Check for errors\", \"Analyze (refresh statistics)\" — helps the server plan queries after big changes — and \"Optimize (reclaim space)\", which rebuilds the table and locks it briefly (do it outside working hours). \"Fix collation\" appears on a table whose collation differs from the rest. The \"Mixed collations\" warning means some tables were created with the server default (utf8mb4_general_ci) instead of utf8mb4_unicode_ci. It is harmless — nothing is lost and ITOps works the same — but \"Fix collation\" on each flagged table (one at a time, outside working hours; the table is locked while it is rebuilt) makes the warning go away. From build BT35 a new installation creates every table with utf8mb4_unicode_ci, so it never appears on a fresh install.","If other applications share the same database, their tables are hidden; tick \"Show other apps' tables\" to see them. They can't be changed from here.","Every action is written to the Audit Log."]},{"h":"Housekeeping"},{"bullets":["Logs that only grow — expired sign-in sessions, read notifications, the Event Log, the outbound email log and finished webhook deliveries — show their row count, oldest entry and how many rows would be removed with the number of days you keep.","\"Remove now\" deletes those rows at once (you confirm first). Unread notifications and queued webhooks are never removed; each log keeps at least 30 days.","Tick \"Clean up automatically once a day\" and \"Save\" to let the scheduled job (cron-sla.php) do it every day with the days you set. The last run and what it removed are shown next to the switch and in the Event Log.","The Audit Log is a compliance record: it is never removed here."]},{"h":"Backup"},{"steps":["Click \"⬇ Download backup\".","Type BACKUP and confirm. A .sql.gz file with every ITOps table — structure and data — downloads to your computer.","Keep it somewhere safe: it contains password hashes and encrypted secrets. To restore, import it with phpMyAdmin (Import) or the mysql command into an empty database."]},{"warn":"The download is a copy for your records, not a replacement for your host's scheduled backups. Uploaded files (attachments, logos, evidence) are on disk in public/uploads and are not in the file — back that folder up with cPanel."},{"qa":[{"q":"The size chart is empty.","a":"One snapshot is saved per day, by the scheduled job or when this page is opened. The line appears from the second day."},{"q":"\"Mixed collations\" is amber.","a":"Some older tables were created with utf8mb4_general_ci. It does no harm today; use \"Maintain…\" → \"Fix collation\" on those tables outside working hours to align them."},{"q":"The backup is slow or stops on a very large database.","a":"Large databases can hit the host's time limits. Use cPanel → Backup or phpMyAdmin → Export instead."}]}]},{"title":"Security checklist after installing or updating","for":"admin","mod":"settings:edit","body":[{"p":"Work through this list after a new install and after each update, so the server and ITOps's powerful settings stay locked down."},{"h":"On the server"},{"steps":["Delete the install/ folder, or deny web access to it. The installer already refuses to run once ITOps is installed (\"ITOps is already installed. The installer is disabled.\"), but removing it is safer.","In a browser, open https://YOUR-SITE/config.php and https://YOUR-SITE/sql/. Both must return 403 Forbidden.","Open https://YOUR-SITE/api/health. It should show {\"status\":\"ok\",\"database\":true}.","Leave public/uploads/.htaccess in place. It stops uploaded files from running as scripts or web pages.","If the CHANGELOG entry says \"DB UPDATE REQUIRED\", run the database update (Settings → Maintenance)."]},{"h":"Inside ITOps"},{"steps":["Settings → General → \"Session security\": require 2FA (\"All password (local) users\" is the safest), and set an idle timeout.","Administration → Users: check who has the Super Admin role, and set leavers to Inactive.","Administration → Roles & Permissions: check which roles have SENSITIVE modules (Credentials, the Microsoft 365 change permissions, Users, Integrations, Settings).","Logs & Integrations → Integrations: revoke API keys nobody uses.","Logs & Integrations → Audit Log: look for login_lockout, mfa_failed and settings_updated entries you don't recognise."]},{"h":"What ITOps protects for you"},{"bullets":["Stored secrets (mailbox, SMTP, Azure, AI, vTiger) are never shown back in the browser. A blank field keeps the saved value.","Only a Super Admin can change: the Microsoft 365 and vTiger connections (Settings → Company systems → Set up…), Guardian settings, the 2FA policy and idle timeout, and any stored secret (mailbox and SMTP passwords, the Microsoft 365 sign-in secret, the AI keys).","An API key can never have more access than the person who created it, and can't reveal vault passwords.","Password hashes and 2FA secrets are never sent to the browser, the audit log or webhooks."]},{"tip":"Keep the vTiger bridge secret in itops-bridge.secret on the vTiger server (permissions 600, web access denied), and change it from time to time with \"Rotate secret…\" in the vTiger provisioning card."}]},{"title":"Security fixes in this version","for":"admin","mod":"settings","body":[{"p":"An October 2026 code audit of the whole app found places where a person could do more than their role should allow. This version closes the most urgent ones; nothing needs to be set up, but a few things now work differently."},{"bullets":["Planned changes: standard (pre-approved) only from a standard-change template; approvals are answered by their approver only; the owner withdraws the whole request to change it; the details are locked once approval is asked for; the owner never approves their own medium-risk or emergency change; a change needs a type and an approval to be resolved as successful. Run the database update: standard changes marked by hand before need approval (the update says how many).","Calendar: the person adding an event is its organizer (a Super Admin can name someone else); only the organizer or a Super Admin changes who is invited. Outlook sends invitations only for events their organizer made.","Tickets: without Tickets · All, tickets are filed in your own name with the app's due times and routing; the requester of a ticket changes its subject and details (or cancels it), the person working it also its category, priority and status. The ticket number and the response / resolve / close times are the app's own.","Bell notifications: the help desk and Super Admins message anyone; others only the people on a ticket they work (up to 50 people, 20 messages an hour).","Settings: security settings and any setting outside a role's areas are Super Admin only; the logo and icon are uploaded only; only a Super Admin changes the Microsoft 365 mailbox.","Deleting a user turns the account off and ends its sessions."]},{"h":"Public pages and email (second part)"},{"bullets":["Requests from the public page and forms sent with the address of a person of the app wait for that person to confirm them by email; until then they are from an outside contact, marked \"not confirmed yet\".","The acknowledgement email no longer repeats links from the subject.","Form files: the server decides the file name and type; files are reached only inside the app; files never sent are removed after 24 hours.","Email intake: messages that fail DMARC are treated as from an unknown sender (internal note only, nothing sent back).","Email settings: the saved password is only used with its server — changing or testing another server needs it typed again.","Every CSV export is safe to open in a spreadsheet (no cell starts a formula).","Knowledge Base: only articles marked public are on the public help portal (off for all articles at first — mark the ones meant for everyone); one vote per visitor.","Scheduled jobs: the token only in the header; the app calls itself at its own address (APP_URL), never at the address in the request; a public rating can be changed a few times only."]},{"h":"Microsoft 365 and integrations (third part)"},{"bullets":["Actions on Microsoft 365 admin accounts (password, MFA, block, sign-out, offboard) are Super Admin only, including roles held through groups or eligible in PIM; the high-risk directory roles too.","Bulk licence removal asks for REMOVE, switching a Conditional Access rule off for OFF.","Every Microsoft Graph address and report period is checked; Microsoft's \"slow down\" is waited out; the cached token is private and encrypted.","Webhooks and the assistant's trusted sources only reach public addresses; the AI provider is switched only by a Super Admin, with that provider's key.","Rollout emails typed by address stay inside your organization; a BitLocker key is shown only when Microsoft confirms its device."]},{"h":"Onboarding, offboarding and vTiger (fourth part)"},{"bullets":["vTiger steps (create the vTiger user, move the records, deactivate the user) need the Provisioning permissions, not only Onboarding · Edit; a vTiger admin is handled by a Super Admin only.","The new owner of a leaver's records is fixed on the step; only a Super Admin changes it.","Steps change only while the process is in progress, run one at a time, and a done step stays done; a completed process cannot be cancelled.","Each person sees the onboarding and offboarding records they started and those of their department; tick Onboarding · All records for the roles that should see every one.","The vTiger bridge build o8 refuses a copied request, passwords over plain http, vTiger's own tables and creating admins. Upload it after this version (see \"Connecting vTiger provisioning\")."]},{"h":"Sign-in and the browser (fifth part)"},{"bullets":["Wrong passwords are counted per account and per network, and attempts on one account are taken one at a time; a 2FA code works once; re-typing a password or code (2FA set-up and switch-off, the vault) is limited too.","Microsoft and Teams sign-in link an existing account by email only for a member of your organisation without ITOps 2FA, never an administrator; a Super Admin can allow one link per person.","The vault reveals the secrets of your own department unless your role has Credentials · All records; each reveal asks again (password, 2FA code, or a recent Microsoft sign-in).","Department Admins manage the people of their own department only.","The session is in a protected cookie only; the app is compiled before it is shipped and its libraries come with it, so the browser runs no code from other sites and no inline scripts.","The idle sign-out is checked on the server; a 2FA reset by a Super Admin signs the person out everywhere; sign-in errors no longer show technical details on screen."]},{"h":"IT operations and documents (sixth part)"},{"bullets":["Uptime checks go to the address the name had when it was checked, and never to link-local or \"this network\" addresses, also when written as IPv6.","The WHM token is sent only to a WHM whose certificate is checked: a public certificate, or the one a Super Admin trusted under Server Guardian settings → WHM certificate. Do this once after the update if your WHM uses its own certificate.","A server action WHM refuses shows as failed; \"Restart a service\" takes only WHM's own service names.","Links between records show only what you may open; making or removing a link needs Edit on the record (Standards & Audits · Edit for a requirement); an API key is never the owner of a requirement.","Signature requests take the title and version from the document and can no longer be signed once the document changed; outside signing links work for 30 days; cancelled requests cannot be signed.","The version of an SOP or job description moves only when its text changes; readers see published SOPs only; the HTML of articles, SOPs and job descriptions is cleaned when saved.","Smaller fixes: announcements keep their wording once someone confirmed them; a budget line is approved by someone else than who added it; Knowledge Base votes count once per person; vendor contacts, equipment and bulk imports are logged with their values."]},{"h":"Tickets and cases (seventh part)"},{"bullets":["A ticket's owner and backup read and write its internal notes; files can be internal too (the requester never sees them), and a requester removes only the files they added.","A reopened ticket gets a new resolution due time; a reply from the requester ends Pending; only an answer to the requester (Pending, Resolved, Closed, or a public reply) counts as the first response.","A major incident that is cancelled, merged or deleted stands down (banner back, linked tickets unlinked); merging is done in one step; a deleted ticket's files leave the server.","A case links only tickets its owner may open; a case's meeting is changed only through the case, and its text is for the case's people; requesters no longer see change windows and milestones.","A decided approval is reopened only by the case owner; change freezes are checked again when approval is asked for and given; timeline moves keep the order of tasks that wait for each other.","Connecting an existing Scorecard row to a measure needs Scorecard · Edit; satisfaction is shown to the help desk only; the Audit Log withholds private-event details and budget amounts from people without those rights."]},{"p":"Every refused attempt is in the Audit Log (case_refused, calendar_refused, ticket_field_refused, notification_refused, settings_refused, ob_task_refused, ob_refused, vtiger_admin_target_refused, user_refused, credential_reveal_denied, o365_link_refused, whm_cert_refused, guardian_action_refused, std_refused, link_refused, signature_refused, sop_refused, announcement_refused, budget_refused, document_refused, attachment_refused, case_refused, scorecard_refused). The other findings of the audit follow in the next versions."}]},{"title":"Scheduled jobs: cron, the in-app scheduler and the run history","for":"admin","mod":"settings","body":[{"p":"Some ITOps work runs on a timer rather than when someone clicks: reading the help-desk mailbox, SLA alerts, reminders, digests and scheduled offboarding. This topic explains how to keep that work running."},{"h":"Are they running? Logs & Integrations → Scheduled jobs"},{"bullets":["The page has three tabs. Scheduled jobs: the jobs on the left with their state; click one to see it on the right — the last run with its steps, the last success and failure, when it is expected next, its last runs (click one to open it), this month's history and the monthly report. Set up: the cron lines for cPanel. Alerts: who is told, the expected interval per job, and the outside monitor.","A job that has not had its first run yet (for example the weekly digest before its first Monday) shows \"Waiting for first run\" for a full interval; only after that does it count as \"never ran\".","History: the runs of the current month are kept. When a month starts, last month's runs become one line per job in the monthly report (runs, % finished OK, runs where a step failed, failed runs, runs with nothing to do, average and longest time) and are cleared. The newest run of each job is always kept. Runs that had nothing to do are counted into the report after a day."]},{"bullets":["Every run of cron-sla.php, cron-sla.php digest, cron-mail.php, cron-audit.php, cron-uptime.php and the in-app scheduler is recorded: when, how it started (cron, web call, in-app scheduler, Run now), how long, the result, and each step with its own result. A run stopped by a PHP error is closed as failed, with the error.","Each job shows: running normally, a step failed, failing, late (no run for twice its interval + 5 minutes; a weekly job: a day), stuck, never ran, or not needed (its feature is off). Click \"last run\" or a bar of the last 48 runs to see the steps.","Administrators are told once when a job is late, failing or stuck (bell and email), and once when it runs normally again. Change the expected interval and switch alerts per job under \"Alerts\"; \"Send me a test alert\" checks they arrive.","\"Run now\" starts the main scheduler or the email intake straight away.","\"Set up the cron jobs\" shows the exact lines for cPanel → Cron Jobs with this server's PHP and folder. If cron runs another PHP version than the website, the page says so.","Outside monitor: \"Make the URL\" gives a private address for an uptime service (UptimeRobot, Better Stack…). It answers 200 when every job is fine and 503 when one is late or failing, with job names and states only — it catches the case nothing inside the app can see: cron not running at all. The address is shown once; \"Stop\" ends it.","It needs the Scheduled jobs permission (View; Edit for alerts, Run now and the monitor). Super Admins have it."]},{"h":"Two ways to run it"},{"bullets":["In-app scheduler: Settings → \"Email\" tab → \"SCHEDULE\" → \"Run automatically while ITOps is open\" (on by default). About every 3 minutes, while anyone has ITOps open in a visible tab, it reads the mailbox and runs the SLA job. \"Last automatic run\" shows when it last worked.","cPanel cron jobs (recommended): they run even at night when nobody is signed in."]},{"h":"Setting up the cron jobs"},{"steps":["Save the Email settings at least once. This creates the cron token that the scheduler and the URL versions need.","In cPanel → Cron Jobs, add: */5 * * * * php /home/USER/public_html/itops/cron-mail.php (mailbox to tickets).","Add: */5 * * * * php /home/USER/public_html/itops/cron-sla.php (everything else).","Add: 0 7 * * 1 php /home/USER/public_html/itops/cron-sla.php digest (weekly SLA digest, Monday at 7:00).","Change /home/USER/public_html/itops to your real folder. If you can't run php commands, use the curl commands shown on the Email tab — they send the token in an \"X-ITOps-Cron-Token\" header so it never appears in web-server logs (older lines with ?token= keep working)."]},{"warn":"The cron token runs every scheduled job, including scheduled offboarding. Only a Super Admin can see it, and a Super Admin can issue a new one with \"Rotate token\" on the Email tab (update your cron lines afterwards)."},{"h":"What cron-sla.php does on each run"},{"bullets":["Contract, credential, SOP review and compliance review reminders.","SLA due-soon and breached alerts.","Scheduled offboarding that has reached its time.","Onboarding task reminders and overdue equipment loan reminders.","Server Guardian and Microsoft 365 alert checks, webhook retries and queued webhooks.","Scorecard auto-measurables, the monthly access re-check, and the daily alert and weekly operations digests if they're switched on under Server Guardian.","Announcements: publishing the scheduled ones, automatic reminders and the queued emails.","Teams notifications, when the Teams app is switched on.","Once a day: the database size snapshot (and the log cleanup, if you switched it on) and the Microsoft 365 device inventory sync."]},{"warn":"The weekly SLA digest runs only from \"cron-sla.php digest\". Scheduled offboarding at an exact time (for example 5 pm on someone's last day) needs a cron job, or someone with ITOps open at that moment."},{"tip":"To check it's working, open Logs & Integrations → Event Log and filter the channel to cron. Each run adds an Info entry, \"SLA scan complete\"."},{"qa":[{"q":"The SLA & Hours tab doesn't show any cron commands.","a":"Save the Email settings once to create the token, then reload."}]},{"p":"All times on this page, like everywhere in the app, are in the installation's time zone in 12-hour format (2:05 PM)."},{"qa":[{"q":"What is the Integration audit collectors job?","a":"The Integration Audit area can collect evidence by itself (server logs, metrics) through collectors. A collector runs only after an administrator approves it and switches it on (Integration Audit → Collectors). Until then cron-audit.php does nothing, and its cron line can be left out; the job then shows \"Not needed\"."},{"q":"Do the cron lines need the token?","a":"No. Lines that start with the PHP path (for example /usr/local/bin/php …/cron-sla.php) run on the server itself and need no token. Only the web versions (curl or wget to an address) need the token."},{"q":"The page says cron runs a different PHP version than the website.","a":"Use the website's PHP in the cron commands: the lines on the Set up tab already start with it (on cPanel, /opt/cpanel/ea-phpXY/root/usr/bin/php, XY being the website's version, for example ea-php81 for PHP 8.1). Or switch the website to the other version in cPanel → MultiPHP Manager — that changes every app on that domain, so test them first."}]},{"warn":"Over HTTP, the cron token goes only in the X-ITOps-Cron-Token header (as the lines shown in the app). Since this version an address with ?token= is refused (it would put the token in web logs): if one of your cron jobs still uses ?token=, replace it with the command shown in Settings → SLA & Hours or with the php command line. Backup check-ins from other servers now show the key in a header too; older ?key= addresses keep working."},{"tip":"The jobs print nothing when cron runs them, and the lines shown here end in \">/dev/null 2>&1\", so the server does not email you after every run (cPanel sends the output of every cron job to its \"Cron Email\" address). Every run is in Logs → Scheduled jobs instead. If you already receive one email per run, edit only the ITOps lines in cPanel → Cron Jobs and add >/dev/null 2>&1 at the end; other jobs keep their emails."}]},{"title":"Audit Log","for":"admin","mod":"audit","body":[{"p":"The Audit Log records who did what, and when: record changes, sign-ins, settings changes and admin actions. Use it to answer \"who changed this?\" or to give an auditor evidence."},{"p":"Where it lives: Logs & Integrations → Audit Log. You need Audit Log with View (included in the Auditor and IT Administrator presets). It's read-only: nobody can edit or delete entries from the screen."},{"steps":["Open Logs & Integrations → Audit Log. The newest entries are first, 50 per page, with Time, User, Action and Item.","To search, type in \"Search user, action, item…\" and press Enter or click \"Search\".","To narrow by kind of record, use the \"All types\" list (for example ticket, credential, user, role, auth or settings).","Under the headings, each column has its own filter: a date range for Time (from, to; both days included), and a box for User, Action and Item. Typed filters apply after a short pause or on Enter; \"Clear filters\" empties them.","\"Newest first\" and \"Oldest first\" choose the order, so the first or the last entry of a filtered list is at the top. Clicking a heading sorts by that column; click again to reverse it.","Click a row with ▾ to expand it. You see the IP address, the record number, and for edits each changed field as old → new.","Use \"‹ Prev\" and \"Next ›\" to page. Click \"CSV\" to download the entries that match your search and filters, in the order shown (up to 5,000)."]},{"h":"What you'll find in it"},{"bullets":["Records created, updated and deleted across ITOps, with the changed fields.","Sign-ins, under the person who signed in: login_first (the very first sign-in of an account), login_success (email and password), o365_login (Microsoft), teams_login (Teams); also login_failed, login_lockout, logout, and the 2FA events (mfa_enabled, mfa_failed, mfa_reset).","People: user_role_changed and user_department_changed show the old and the new role or department by name; created, updated and deleted show the person's name.","Settings: settings_updated (with the setting names), mail_settings_updated, o365_settings_updated, ai_config, branding uploads.","Admin actions: bulk_import, db_update, o365_auto_provision (a new Microsoft sign-in), notification_sent, onboarding and offboarding steps, access re-checks.","Automatic work, such as each mailbox check (mail_poll). These show the user as System."]},{"h":"Microsoft 365 and vTiger changes"},{"bullets":["Choose \"m365\" (or \"vtiger\") in the \"All types\" list to see only those, or search a person's sign-in name to see everything done to that account.","m365_user_update: contact information, manager or custom fields were changed. Open the row to see each field as old → new. One save can be several rows, one for each part (main fields, phone numbers, fax, custom fields, manager), each written as soon as Microsoft answered it.","m365_user_update_refused: a part of a change was not made. The row shows the value that was wanted and why: \"not changed\" (Microsoft refused it, or a manager removal did not match the account), \"outcome not known\" (no clear answer came back, so check the account) or \"not sent\" (the time for one save ran out; nothing was changed).","m365_users_bulk_update: a bulk edit ran. The row shows the instruction, the accounts and the result. Each changed account also has its own m365_user_update row, named \"… (bulk edit <run>)\".","m365_custom_fields_save: the custom field definitions or the company-wide values were changed, with the list before and after.","The same entries appear on the account itself: Microsoft 365 → People → pick a person → \"+ Show change history\".","\"Show change history\" on an account is for people who edit accounts (\"Microsoft 365 · Accounts\" with Edit) or who can read the Audit Log."]},{"tip":"Password hashes and 2FA secrets are never written to the log, and vault passwords are only ever stored encrypted."},{"qa":[{"q":"I don't see Audit Log in the menu.","a":"Your role needs Audit Log with View."},{"q":"What's the difference from the Event Log?","a":"The Audit Log is about people's actions. The Event Log is about the system itself: scheduled runs, integration errors and background jobs."}]},{"h":"What each role sees"},{"p":"A role reads only the entries of the areas it can open: Credentials entries need Credentials · View, Contracts need Contracts · View, Equipment needs Equipment · View, tickets need Tickets \"All records\", and so on. A person always sees what they did themselves. Entries that belong to no area are shown to Super Admins only. The type filter lists only the kinds the role may read; searching and the CSV export follow the same rule."},{"p":"An entry follows the rights of the record it is about. The details of a private calendar event show only to the people who can open the event (others see \"Private event\"), and the amounts of a project's IT Budget lines only to people with IT Budget · View. A Super Admin, and the person who made the change, read every entry in full."}]},{"title":"Event Log","for":"admin","mod":"event_log","body":[{"p":"The Event Log shows what ITOps's background parts did: scheduled runs, Microsoft 365 and Server Guardian actions, onboarding outcomes, webhook failures and alerts. Look here first when something automatic didn't happen."},{"p":"Where it lives: Logs & Integrations → Event Log. You need Event Log with View (included in the Auditor and IT Administrator presets). It's read-only."},{"steps":["Open Logs & Integrations → Event Log. You see the latest 100 matching events, newest first, with When, Level, Channel and Message.","Pick a level: \"Error\", \"Warning\", \"Info\" or \"Debug\" (or \"All levels\").","Pick a channel. The list only shows channels that have events, for example cron, onboarding, m365, guardian, webhook, backup or mailq.","To search, type in \"Search message…\" and press Enter. Click the refresh icon to reload."]},{"h":"Useful checks"},{"bullets":["Is scheduled work running? Channel cron should show \"SLA scan complete\" every few minutes.","Did a scheduled offboarding run? Channel onboarding shows \"Scheduled offboarding ran for …\" and the result.","Did the monthly access re-check find anyone? Channel onboarding shows \"Monthly access recertification: …\".","Why did a Microsoft 365 action fail? Filter the m365 channel to Warning or Error.","Is a webhook failing? Look at the webhook channel, then Logs & Integrations → Integrations → \"Delivery log\"."]},{"tip":"Only 100 events are shown at a time. Use the level, channel and search filters to find older ones."}]},{"title":"Sent emails","for":"admin","mod":"event_log","body":[{"p":"Logs & Integrations → Sent emails lists every email the app tried to send: when (in the installation's time zone), to whom, the subject, which email it was (for example \"Backup alert\" or \"Reply on a ticket\"), whether it went out — with the error when it did not — the linked ticket and who sent it (or \"the app\" for automatic emails)."},{"bullets":["Search an address or a subject; filter to sent or failed, to one kind of email, or to a period. The tiles count today, this month, failures in the last 7 days and everything kept.","\"Export CSV…\" shows the filtered list first (up to 10,000 rows); download it from the preview. The preview and the download are written to the Audit Log.","The text of the emails is not kept on purpose: some carry a temporary password or a sign-in link.","How long the list is kept is set in Settings → Maintenance → Housekeeping (Outbound email log)."]},{"p":"Permission: Event Log (view)."}]},{"title":"What's New (release notes)","for":"everyone","mod":"changelog","body":[{"p":"What's New shows the release notes for the ITOps build installed on your server, so you can see what changed and whether an update needs extra steps."},{"p":"Where it lives: Logs & Integrations → What's New. You need What's New with View. Every preset includes it. In a role built with the permission grid, it must be ticked."},{"h":"Reading it"},{"bullets":["It reads the CHANGELOG.txt file in the ITOps folder live. The builds are listed on the left, newest first; click one to read its notes on the right. A \"DB UPDATE\" tag marks a build that needs the database update.","Each entry starts with a build ID, such as 0621-BT6. It matches the version under Settings → General → About → Version.","The tag after the title tells admins what to do. \"[DB UPDATE REQUIRED]\" means run the database update. Some entries also say a new vTiger bridge file must be uploaded.","Entries list security fixes, new features and changed behaviour in plain words.","The search box looks in every build: the list keeps the builds that mention the words, and the words are highlighted in the notes."]},{"tip":"After an update, compare the top entry here with Settings → General → About → Version. If they don't match, hard-refresh the browser (Ctrl+Shift+R or Cmd+Shift+R)."},{"qa":[{"q":"It says \"Couldn't load the changelog\".","a":"CHANGELOG.txt is missing from the ITOps folder (the folder that holds index.html). Upload it from the install zip."},{"q":"I don't see What's New in the menu.","a":"Ask a Super Admin to tick What's New: View on your role."}]}]},{"title":"Modules and plans: what this installation includes","for":"admin","mod":"license","body":[{"p":"ITOps is built from modules: Service Desk, Cases & Projects, Knowledge Base, Microsoft 365, Servers, Equipment and so on. Administration → Settings → \"Modules\" lists every module, what it covers, whether this installation's license includes it, and whether it is on. Super Admins and the roles with \"License details\" see the page; only a Super Admin changes it."},{"h":"Where the list comes from"},{"bullets":["The license decides which modules are included. The license record names a plan (Complete, Service Desk, Microsoft 365 Admin or IT Operations) and may add modules one by one.","An installation without a license record, or with a record that names no plan, includes every module.","A Super Admin can switch an included module off, and on again. A module the license does not include cannot be switched on in the app.","Some modules need another one: Cases & Projects needs Service Desk, Onboarding & offboarding needs Microsoft 365. Switching the needed one off switches the other off too; the page says so before you save."]},{"h":"Switching a module off"},{"steps":["Open Administration → Settings → \"Modules\".","Untick the module. The page shows which other modules go off with it.","Click \"Save\". The change is written to the Audit Log (\"modules_changed\") with the names of the modules."]},{"h":"What happens while a module is off"},{"bullets":["Its pages leave the menu, and its permissions are refused for everyone, Super Admin included. The Roles page marks them \"MODULE OFF\"; what a role was given is kept.","The scheduled jobs skip its work and say so in Logs → Scheduled jobs (\"Skipped: … is not part of this installation\"). Examples: no SLA alerts without Service Desk, no uptime or backup checks without Servers, no renewal reminders without Contracts & Vendors.","The emails it would send are not sent, and they leave Settings → Email templates (their wording is kept).","Bell and Teams notifications that open it are not shown.","Its Help Center topics, dashboard tiles and search results are left out.","Nothing is deleted. Switching the module on again brings back its data, its settings and its notifications."]}]}]},{"cat":"Microsoft 365: onboarding & offboarding","topics":[{"title":"Onboarding & offboarding: how it works","for":"admin","mod":["m365","onboarding"],"body":[{"p":"Joiners and leavers are handled in Microsoft 365 → People: \"Onboard\" creates the person in Microsoft 365 and vTiger in one go (optionally from a template), \"Offboard\" runs one guided departure, and \"History\" keeps a record of every one of them."},{"bullets":["Templates live in Administration → Onboarding Templates. A template pre-fills Microsoft fields, picks the licenses and groups, and says whether to create the vTiger user (with its role and status).","Onboarding: the account is created, then the template groups are added, then the vTiger user is created with the same username, email and temporary password. The result and anything that failed are saved in History.","Offboarding: vTiger records are reassigned first (while the user is still active), then Microsoft 365 is closed down, then the vTiger user is deactivated. ITOps adds the auto-reply, mail forwarding, OneDrive handover, equipment check-in and \"schedule for their last day\".","History shows the records you started and those of your department; a Super Admin and roles with Onboarding · All records see every one. A step changes only while its process is in progress; a done step stays done, a required step is not skipped, and only a process in progress can be cancelled.","History lists every process (including ones from earlier builds) with each step's result, the access check and the metrics panel.","Every change is written to the Audit Log. Passwords are never stored."]},{"p":"Upgrading converted the old onboarding templates: their Microsoft 365 account, license, group and vTiger steps became the new template fields. Checklist-only steps (equipment, reading and signature, welcome email, manual tasks) were dropped — processes already started keep all their steps in History."}]},{"title":"Onboarding templates","for":"admin","mod":"onboarding","body":[{"p":"Administration → Onboarding Templates bundles the defaults for one kind of new hire, for example \"Sales Rep\". Picking it on the Onboard screen fills the form; everything stays editable."},{"steps":["The templates are listed on the left; the one you work on opens on the right, beside the list. On a wide screen the first template is already open. Click a template (or its \"Edit\") to open it, or \"New template\" for a new one.","Enter the \"Template name\" and an optional \"Description\".","Under \"Microsoft 365 · the person’s details\": the \"Usage location\" (two letters, required for licensing) and an optional \"Default manager\" (type a name).","\"Field defaults\": job title, department, company, office, phones and employee ID are always there; add more with \"Add a Microsoft field…\" (employee type, address, city, state, postal code, country, fax, preferred language). Empty fields are not saved.","\"Custom fields\": your organization's own fields (an extension, a cost center) are always listed here, without adding them; a field with choices is a dropdown. Type a value when it is the same for everyone of this kind. Leave it empty when it differs per person: it is still on the Onboard screen to fill in.","Click \"+ Licenses\" to open the list and tick; click \"+ Groups\" to search for groups to add. Folded, each heading says how many are chosen and names them.","\"Default password\" (optional): the first password every new person of this kind starts with. See \"A default password\" below.","Click \"Save template\". The template stays open beside the list."]},{"h":"Working on several templates"},{"bullets":["Click another template in the list to open it. If the one you were on has changes that are not saved (\"Not saved\" shows next to the title), ITOps asks first: \"Leave without saving\" or \"Keep editing\".","\"✕ Close\" (or \"Cancel\") closes the template, asking first the same way.","On a wide screen the template is laid out in two columns: the person’s details on the left; licenses, groups, the first password on the right.","On a narrow screen or a phone the template takes the whole width; \"← Templates\" goes back to the list."]},{"h":"A default password"},{"bullets":["When the template is picked on the Onboard screen, \"Use the default password of the template\" is the choice. The person creating the account can still choose \"Generate a strong temporary password\" or \"Type another password\" for that one account.","It needs at least 8 characters and three of these four: a lower-case letter, a capital letter, a digit, a symbol. Microsoft 365 refuses anything weaker.","It is stored encrypted. It is never shown on the template again and never sent back to a browser: an open template shows \"saved · leave empty to keep it\". Type a new one to replace it. \"Remove the saved password\" takes it off when you save.","An account created with it must always change it at first sign-in, because several people start with the same one. That tick cannot be taken off.","It is shown once, in the result after the account is created, so you can give it to the person.","The Audit Log records who set, replaced or removed a default password, on which template and when. It never holds the password."]},{"p":"\"Other company systems\" lists the systems switched on under Administration → Settings → Company systems. Tick the ones a person of this kind needs: they are pre-ticked on the Onboard screen and each becomes a step done by hand in that system. See \"Company systems in onboarding and offboarding\".","mod":["onboarding"]},{"p":"The list shows each template's licenses, groups, location and vTiger role, and \"default password set\" when it has one. \"Delete\" asks first; it cannot be undone. The \"vTiger provisioning\" tab on the same page is where the vTiger connection is set up."},{"qa":[{"q":"The template says \"Usage location must be a 2-letter country code.\"","a":"Use the two-letter code (US, PR, MX…) or leave it empty."},{"q":"No vTiger roles in the list.","a":"Roles are read from vTiger through the bridge. The bridge isn't set up or can't be reached — the message under the list says why. Open the \"vTiger provisioning\" tab and click \"Test bridge\"."},{"q":"Under \"Custom fields\" it says \"None yet\".","a":"No custom field has a name yet. Name the ones you use with the \"Custom fields\" button next to \"New template\". Once named, they are listed on every template and on the Onboard screen."},{"q":"A custom field I used to see is gone from the template.","a":"It was switched off or removed under \"Custom fields\". A template keeps values only for fields that are in use."},{"q":"\"The default password needs at least 8 characters and three of these four…\"","a":"The password is too short or too simple for Microsoft 365. Nothing was saved; the page stays open so you can type another."},{"q":"\"This installation cannot store secrets\".","a":"The default password is kept encrypted with the VAULT_ENCRYPTION_KEY in config.php, the same key that protects the Vault. It is missing or not valid. The template was not saved; save it without a default password, or have the key set first."},{"q":"I forgot what the default password is.","a":"It cannot be shown again. Type a new one on the template and save."}]}]},{"title":"Onboarding a new hire (the Onboard tab)","for":"admin","mod":"m365_users:edit","body":[{"steps":["Go to Microsoft 365 → People → \"Onboard\".","Pick a \"Template\" (optional). It fills job title, department, location, manager, more details, licenses, groups and the vTiger settings.","Type the \"First name\" and \"Last name\". \"Display name\" and \"Username\" fill themselves (first.last); change them if needed. Pick the \"Domain\" — \"Sign-in:\" shows the full address.","Check job title, department, \"Manager\" and \"Usage location\". Open \"+ More details\" for phones, company, employee ID, address, language and your organization's custom fields (an extension, for example). A template opens it by itself when it fills any of them.","Click \"+ Licenses\" and tick the licenses (each shows the seats left). Folded, the heading says how many are selected and names them. The groups of a template are under \"+ Groups from the template\".","Tick \"Also create a vTiger user\" and pick its role and status if they need vTiger.","Under \"First password\" choose one: \"Use the default password of the template\" (offered, and already chosen, when the template has one), \"Generate a strong temporary password\", or \"Type another password\". Leave \"Require change at first sign-in\" ticked; for a template's default it is always on.","Click \"Create account\"."]},{"p":"The result shows the new account, the password (the temporary one to copy now, or \"The template's default password — give it to the person\"), any warnings (for example \"License not assigned\"), the vTiger user that was created and each template group (✓ or ✕). \"Onboard another\" clears the form; \"See History\" opens the record."},{"bullets":["The vTiger user gets the same username, the Microsoft 365 address as email and the same first password.","Groups need \"Microsoft 365 · Groups\" and the vTiger user needs \"Provisioning · Onboard to vTiger\"; without them those parts show ✕ with the reason, and the account is still created.","New accounts take a few seconds to appear everywhere in Microsoft; ITOps waits and retries the manager, license and group steps for you.","Other company systems (phone, fax, forms, CRM…): tick them under \"Other company systems\". After the account is created each one shows a box to answer once the account is set up there. See \"Company systems in onboarding and offboarding\"."]},{"tip":"On a wide screen (1500 pixels and more) the Onboard form is in two columns: the person on the left (names, sign-in name, job, manager, usage location, more details); licenses, groups, the vTiger user, other company systems and the first password on the right. \"Create account\" is under both."},{"p":"The new account is on Microsoft 365 → People at once, without reloading the page. Microsoft's own list of accounts can take a little while to include a new one; until it does, the account is shown marked \"new\", and the list is read again from Microsoft every 20 seconds until the mark goes."}]},{"title":"Temporary passwords (shown once)","for":"admin","mod":["m365","onboarding"],"body":[{"p":"When ITOps creates an account or resets a password, it shows the temporary password once, with a \"Copy\" button, so you can hand it over."},{"p":"A generated temporary password has 16 characters with upper and lower case letters, digits and symbols. A password typed for a new vTiger user needs at least 12 characters with letters and digits. ITOps sends a new vTiger password only when the bridge address is https://."},{"bullets":["Onboard: in the result, under \"Temporary password — copy it now, it won't be shown again\". The same password is used for the vTiger user. When the template's default password was used, the box reads \"The template's default password — give it to the person\"; it must be changed at first sign-in.","Accounts → \"Reset password\": in the person's panel, right after \"Generate & reset\". It stays there while you keep working on that person.","Temporary access pass: shown once in the person's panel."]},{"warn":"ITOps never stores a temporary password. If one is lost, reset the password again (Microsoft 365 → People → the person → \"Reset password\"). The only first password ITOps keeps is the default password of an onboarding template: encrypted, and never shown on the template again."}]},{"title":"Offboarding a leaver (the Offboard tab)","for":"admin","mod":"m365_users:edit","body":[{"steps":["Go to Microsoft 365 → People → \"Offboard\" and type the person's name in \"Who is leaving?\". The card shows their status, licenses, groups and vTiger link.","Microsoft 365: sign-in is always blocked; choose \"Revoke active sessions\", \"Remove all licenses\" and \"Remove from all groups\".","Mailbox & files (ITOps): an auto-reply, forwarding new email to a colleague, and sharing their OneDrive with a colleague.","vTiger: \"Reassign vTiger records first\" — pick who receives them and all or some modules — and \"Deactivate the vTiger user\".","Equipment: add a check-in step for each item still on loan.","When: \"Run now\", or \"Schedule for their last day\" with a date and time.","Click \"Run offboarding\" (or \"Schedule offboarding\")."]},{"p":"The steps run in a safe order and appear one by one with ✓ or ✗. Then click \"Verify offboarding\" to re-read Microsoft 365, vTiger and Equipment. \"Open in History\" shows the saved record."},{"bullets":["A scheduled run waits in History and runs by itself at that time (it needs the scheduled job, or someone having ITOps open).","Equipment is checked in by hand, with its condition, when it comes back (History, or Assets → Equipment).","You can also do a quick offboard from the person's panel in Accounts (\"Offboard…\").","Other company systems (phone, fax, forms, CRM…) are listed under \"Other company systems\" with the accounts recorded for the person. Each ticked one becomes a step you do by hand in that system and answer on the screen. For a connected system (JustCall) the step is done when that system no longer lists the person. See \"Company systems in onboarding and offboarding\"."]},{"warn":"The vTiger parts need \"Provisioning · Offboard from vTiger\". Without it the screen says the vTiger steps are skipped — deactivate them in vTiger separately."}]},{"title":"When a step stops: Continue anyway, Skip or finish it in History","for":"admin","mod":["m365","onboarding"],"body":[{"bullets":["A failed step shows ✗ and the reason; the rest of the run continues.","If the vTiger user still owns records, deactivation stops and asks for a reason: type it and click \"Continue anyway\" (it is saved in the Audit Log), or \"Skip this step\".","Open the record in Microsoft 365 → People → History to \"Retry\" a failed step, \"Mark done\" work you did another way, or \"Skip\" an optional one.","In Onboard, a failed group or vTiger part shows ✕ with the reason; add the group in Accounts or create the vTiger user in vTiger, then note it."]},{"warn":"\"Mark done\" changes nothing in Microsoft 365 or vTiger. Use it only when the work is really done."}]},{"title":"Verify offboarding and the monthly access re-check","for":"admin","mod":["m365","onboarding"],"body":[{"p":"The \"Access verification\" card on every offboarding proves that the leaver's access is really gone. It re-reads each system instead of trusting the step results."},{"steps":["In Offboard, click \"Verify offboarding\" after the run (or \"Re-check\").","In History, open the offboarding — the card runs by itself when it completes; click \"Verify offboarding\" to check again.","Read each line: ✓ passed, ✕ failed, – not checked."]},{"bullets":["Microsoft 365 · Sign-in blocked, and Licenses removed (a deleted account passes both).","vTiger · User deactivated, and Records reassigned (no records still owned).","ITOps · Equipment returned (nothing still on loan).","Each company system in use · Account removed (recorded by hand): ✗ while an account is still recorded as open for the person or the step is unanswered; ✓ with the answer that was given. ITOps reports what was recorded, not what it read in that system.","A connected system (JustCall) · Account removed (read from JustCall): the system is asked at that moment. ✗ when it still lists a user for the person or cannot be read; ✓ with the time of the reading."]},{"p":"The card border is green for \"Clean\", red for \"Issues found\" and amber for \"Nothing could be checked\". The Onboarding list shows \"✓ verified\" or \"✕ access remains\". Every result is saved in the Audit Log as evidence."},{"h":"What \"unchecked\" means"},{"p":"\"Nothing could be checked (no connected system / no accounts found)\" means no check passed or failed. Usually Microsoft 365 or the vTiger bridge is not connected, or the person never had an account there. It is not a failure, but it is not proof either."},{"h":"Monthly access re-check"},{"bullets":["\"Re-check all offboardings\" on the Onboarding page re-verifies every completed offboarding now (up to the latest 300). Nothing is changed.","The same check runs once a month through the scheduled job. If anyone still has access, Super Admins, Admins and Department Admins get an in-app alert and the email \"Access re-check found a problem\"."]},{"tip":"A ✕ after completion usually means someone re-enabled the account or re-added a license. Fix it in that system, then click \"Re-check\"."},{"p":"When the vTiger user was only found by user name and nobody confirmed it is the same person, a result \"is still Active\" adds \"It may be somebody else with the same user name\". If it is the person who left, run \"Deactivate vTiger user\" on the record and confirm; if it is somebody else, nothing needs to be done in vTiger."}]},{"title":"Offboarding summary and access re-check emails","for":"admin","mod":["m365","onboarding"],"body":[{"p":"ITOps sends a few emails during onboarding and offboarding. You can change their wording under Settings → Email templates."},{"p":"Templates no longer send a welcome email or reading to sign — hand the new hire their sign-in details with the temporary password. Processes started before the upgrade still send theirs."},{"bullets":["\"Welcome — first-day information\": sent by the \"Send welcome email\" step to the new mailbox, or to the address set on the step (e.g. a personal email). It includes the start date, sign-in address, job title, manager and the extra text from the step. It never includes the password.","\"Onboarding document to sign\": one email per document from an \"Assign reading + signature\" step, with a private signing link.","\"Offboarding summary\": sent to whoever started the offboarding, whoever scheduled it, and the manager, when it completes or after a scheduled run. It lists every step and the access-check result.","\"Access re-check found a problem\": sent to Super Admins, Admins and Department Admins when the monthly re-check finds remaining access."]},{"tip":"The manager only gets the summary if the process has a manager email. For offboarding there is no manager field on the start form, so the summary goes to you (and the scheduler) only."},{"p":"Each email goes out in English or Spanish: the recipient's own ITOps language if they have an account, otherwise the default language. Editing the wording needs Settings (edit)."}]},{"title":"Troubleshooting onboarding and offboarding","for":"admin","mod":["m365","onboarding"],"body":[{"p":"Real messages from Onboard, Offboard and History, and what to do about each."},{"qa":[{"q":"\"License not assigned: License assignment cannot be done for user with invalid usage location.\"","a":"Microsoft licenses only an account that has a usage location (the two-letter country, for example US). Since build 0621-BT52 the location on the Onboard form is sent with the new account, and ITOps retries for a few seconds if Microsoft has not caught up yet; a license with no location is refused before anything is created. For an account created earlier without one: Accounts → open the account → set \"Usage location\" → assign the license."},{"q":"\"The Azure app is missing the \"User.ReadWrite.All\" Application permission…\" (or another permission)","a":"In Azure → App registrations → your ITOps app → API permissions, add that Application permission and click \"Grant admin consent\". Then, as a Super Admin, go to Microsoft 365 → Home → Diagnose → \"Refresh token & re-test\" and run the pre-flight again."},{"q":"\"Graph write access denied (HTTP 403)…\"","a":"Same cause: the Azure app lacks the write permission for that step. See \"What Microsoft 365 permissions ITOps needs\"."},{"q":"\"… NO seats available. Buy or free a license first.\" or \"NOT assigned — no seats left\"","a":"All seats of that license are used. Remove the license from a former employee or buy more, then \"Retry\". Microsoft 365 → Licenses → Licenses shows seats per license."},{"q":"\"Microsoft 365 is not connected\" or \"Microsoft 365 is not configured\"","a":"A Super Admin must enter the Tenant ID, Client ID and Client secret under Settings → Company systems → Microsoft 365 (Set up…)."},{"q":"\"vTiger bridge: Could not reach bridge…\" or \"The vTiger bridge is not configured\"","a":"Check the Bridge URL under Settings → Company systems → vTiger (Set up…) and click \"Test bridge\". The vTiger site must be reachable from the ITOps server."},{"q":"\"Bad signature.\", \"Bridge secret not set\" or \"Stale request (check server clocks)\"","a":"The secret in ITOps and on the vTiger server don't match, the itops-bridge.secret file is missing, or the two servers' clocks differ by more than 5 minutes. Fix it, then \"Test bridge\"."},{"q":"\"The vTiger bridge is build … — upload itops-bridge.php build o5.\"","a":"Upload the itops-bridge.php from the install package to the vTiger web root. The secret stays the same."},{"q":"\"… still owns N record(s)… Run \"Reassign vTiger records\" first\"","a":"Run \"vTiger: reassign records\" first, or type a reason when asked to deactivate anyway."},{"q":"\"You do not have permission for this (m365_users)\" (or m365_credentials, m365_licenses, m365_groups, m365_roles, provision_offboard…)","a":"Your role lacks that Microsoft 365 permission. See \"Microsoft 365 permissions: who can do what\"."},{"q":"\"Usage location must be a 2-letter country code.\"","a":"Fix it in the template (or the Onboard form) — two letters such as US."},{"q":"\"A vTiger user with that email already exists.\"","a":"The person is already in vTiger. ITOps links it by email; no second user is made."},{"q":"\"Pick a target user for reassignment.\" or \"Source and target users are the same.\"","a":"Choose a different active vTiger user to receive the records."},{"q":"\"You cannot offboard your own account.\" / \"You can't remove roles from your own account.\"","a":"Lock-out protection: ask another administrator."},{"q":"\"Not run. No vTiger user has this person's email. The vTiger user … was found by user name only\"","a":"ITOps found a vTiger user with the person's user name but another email, and will not deactivate it or move its records until someone confirms it is the same person. Look at the user it names. If it is the same person, answer \"Yes, the same person\" (Offboard tab), or click \"Run\" on the step in History and confirm. If it is somebody else, skip the step. Either answer is in the Audit Log."},{"q":"\"The vTiger user shown on the screen is not the one linked to this person now. Reload the page…\"","a":"The page was showing a vTiger user that no longer matches this person (the page was open for a long time, or the vTiger record changed). Nothing was started. Reload the page, pick the person again and check the vTiger user shown before you run the offboarding."},{"q":"\"No vTiger user matches that email. A vTiger user named … exists with another email\"","a":"An action was asked for by email only, and the only vTiger user that fits was found by user name. Reload the page so the screen shows that user, check it is the same person, and act from there."}]}]},{"title":"Time zone of the installation","for":"admin","mod":"","body":[{"p":"Every time in the app is recorded and shown in the installation's time zone, in 12-hour format: tickets and their due times, business hours, the scheduler, emails, reports and the calendar sync. It is chosen in the installer and shown in Settings → General → Time zone."},{"steps":["Settings → General → Time zone (a Super Admin changes it).","Pick the zone from the list, or choose Other and type its name (for example America/Guatemala).","Click Save, then reload the page to see every screen in the new zone."]},{"bullets":["Once the installation holds records, a change asks you to type CHANGE: created and updated times follow the new zone, but times the app wrote as clock values (due times, schedules, many logs) keep them and can look shifted by the difference. Choose the zone before going live.","Business hours have their own time zone field; it starts as the installation's.","A server administrator can fix the zone in config.php (ITOPS_TIMEZONE); the card then says so and cannot change it."]}]},{"title":"Updates: installing a new build","for":"admin","mod":"","body":[{"p":"Administration → Updates (Super Admin) installs a new build from a signed update bundle (a file ending in .itops-update) made by the License Hub."},{"steps":["Choose the bundle and click Check. Its signature, its package, the build, the free disk space and write access to every file are checked. Nothing changes yet.","Read the notes and any problem. Type INSTALL and click Install.","The app makes a database backup and a copy of the files it replaces, shows \"being updated\" for about a minute, puts the new files in place and runs the database update. Then click Reload now."]},{"bullets":["Never touched: config.php, the license file, data/ and people's uploads.","If something fails while the files are put in place, the previous files are put back at once.","Backups before updates keeps the three newest: \"Put the previous build back\" (type PUT BACK) restores the files; the database backup taken before the update can be downloaded there.","A bundle signed by a key this build does not carry, or changed after it was signed, is refused. A build with no release key cannot check where a bundle comes from: install that build once by uploading the files.","A build offered by the License Hub appears at the top with its notes: \"Download and check\" checks it the same way; installing still needs INSTALL."]}]},{"title":"Data: the data dictionary and the data grid","for":"admin","mod":"","body":[{"p":"Administration → Data (Super Admin only) shows every table of this installation: what it is for, its columns and its rows. Other roles, Admin included, do not see it."},{"p":"Overview and report: the number of tables and columns, the reference lists that can be changed (marked ✎), the tables that are empty right now, the tables no code of this build uses, and families of similar tables with advice on whether they could be merged. Nothing is merged or removed from here: such a change is made by a database update in a new build, after the report."},{"p":"Download the dictionary (on the overview) gives every table and its columns as one document you can open in any editor or keep with your records. Downloading it is in the Audit Log."},{"steps":["Pick a table on the left (\"Find a table\" and the chips narrow the list).","Data tab: type under a column to filter it. =value means exactly, !value not, >10 and <10 compare, ^start begins with, empty and !empty. Click a column name to sort.","Group by: counts per value; click a count to filter by it.","Export to Excel or CSV: the rows that match the filters and the sort, up to 50,000.","Dictionary tab: each column with its type, default, keys, the table it points to and what it holds."]},{"p":"Changing data: only the reference lists (departments, categories and similar) can be changed here, and only their marked columns. Double-click a ✎ cell, then press Enter to save or Esc to cancel. Values are checked (colors as #RRGGBB, statuses from their list, names not empty). If someone changed the value since you opened it, the change is refused and you reload."},{"warn":"Passwords, tokens, keys and other secrets are never shown, filtered, sorted, grouped or exported: they read \"•••• hidden\". Opening a table's rows (once an hour), every export, every change and every refusal is in the Audit Log."}]},{"title":"Deleted items: put back what was deleted","for":"admin","mod":"","body":[{"p":"Deleting anything in the app (a ticket, an article, an SOP, a credential, a contract, a vendor, an invoice, a form, a calendar entry, a role, a template, a file…) does not erase it. It moves to Administration → Deleted items, with what belongs to it: comments, files, versions, lines, tasks. A Super Admin sees everything there. A role with the permission Deleted items sees the deleted records of the parts of the app it can see: View to see them, Edit to put them back, Delete to delete them for good, each together with the same action on that part (for example Edit on Tickets to put a ticket back)."},{"p":"Put back returns the record exactly as it was, with the same number and its links. If something it pointed to is gone (for example its category), that field is left empty and the page says so. If another record took its name or number meanwhile, it is not put back until that one is renamed."},{"p":"Delete for good (type DELETE) removes one entry and its files from the disk. Empty Deleted items (type EMPTY) does it for all. Entries older than the kept days (30 unless changed on the page; 0 keeps them until emptied) are deleted for good once a day by the scheduled job."},{"p":"A record that other records still use cannot be deleted: a vendor with contracts, a contract with invoice lines, a role people have. The message says what uses it; change those first, or set the record inactive instead. Every delete, put back and delete for good is in the Audit Log."}]},{"title":"Maintenance window: automatic updates","for":"admin","mod":"","body":[{"p":"Off by default. When it is on, the scheduler installs a build the License Hub offers inside the days and hours chosen, with the same backup and way back as installing by hand."},{"steps":["Link the installation to the License Hub (Updates → License Hub).","Updates → Maintenance window: choose the days and the hours (the app's time zone), then Switch on.","The scheduler downloads the offered build, checks it and, when nothing is in the way, installs it inside the window. The result is in the Audit Log and under Last update."]},{"bullets":["A bundle with any problem is never installed automatically; it waits for a person.","A bundle uploaded by hand is never installed automatically.","Needs the scheduler (cron-sla.php) to run from the command line (a cPanel cron job with php)."]}]},{"title":"License Hub: the daily check-in","for":"admin","mod":"","body":[{"p":"Once a day each installation asks the License Hub for its license, so a renewal, a change of plan or a revocation arrives by itself. It is set on Administration → Updates → License Hub (Super Admin), or in the installer."},{"steps":["The owner of the License Hub makes a link code (License Manager → Installations). For an installation not installed yet, leave the installation ID empty: the first installation that uses the code within 30 days is linked.","Paste the link code in the installer (step \"License Hub\") or in Updates → License Hub and click Link. It carries the hub's address and a token; the token is stored encrypted and never shown again.","Click Check in now to try it. After that the check-in runs by itself once a day."]},{"bullets":["A license that arrives is used only if its signature matches the license key in this build and it is for this installation. Otherwise it is refused, nothing changes, the refusal is in the Audit Log and the hub is told at the next check-in.","The license file is written by this installation from the checked fields; the previous one is kept in data/updates/licenses.","A revocation counts only when it is signed with that same license key and names this installation and the license in use, so an address that is not the real hub cannot take a license away.","Sent: the installation ID, the build, the PHP and database versions, the number of active users, the last update's result, and the license number and state. Nothing about people, tickets or settings.","Switch check-in off to stop it (for example on a server with no internet access), or Unlink (type UNLINK) to remove the address and the token. Licenses can still be uploaded as a file.","On the License Hub, Installations lists every installation (from the licenses issued and from check-ins) with its license, users used and allowed, build and last check-in, and what needs attention: a term ending within 30 days or ended, more users than allowed, silent for 7 days, an older or revoked license still in use, a license it refused, not linked."]}]},{"title":"Installing the main installation (License Hub)","for":"admin","mod":"","body":[{"p":"There is only one main installation, run by Indisse-BTS: it issues the licenses and update bundles of every other installation. It is installed with install/hub.php; every organization uses install/ (the regular installer)."},{"steps":["Open https://YOUR-SITE/install/hub.php and follow the same steps as the regular installer.","License Hub setup: the hub's public HTTPS address (it goes into every link code), the organization it belongs to, and a backup passphrase (12+ characters, twice).","Finalize. The installer switches the License Manager on in config.php, creates the license key and the release key, and issues the hub its own license (Complete, no end date).","On the last page, download both key backups (they are offered once) and send the two key lines to be put into the builds. Open ITOps becomes available once both backups are downloaded."]},{"bullets":["Keep the backup files and the passphrase in two different safe places. Later backups: License Manager.","The installer locks itself once installed, like the regular one."]}]},{"title":"License Hub: clients, releases and channels","for":"admin","mod":"","body":[{"p":"On the main installation, License Manager keeps the client profiles, the licenses and the releases."},{"bullets":["Clients: organization, contact, email, phone, address and notes. When you issue a license, pick the client; the plan and modules are set on the license.","Releases start in Pilot: installations marked Pilot (Installations, one click) are offered them at once; the others after the waiting period (7 days by default) or when you click Promote to Stable.","Pause stops offering a release, Resume starts again, Withdraw (type WITHDRAW) stops it for good.","Each release shows how many linked installations already run it."]}]},{"title":"License Hub: billing","for":"admin","mod":"","body":[{"p":"On the main installation, License Manager → Billing keeps the price list, the charges of each license and the payments you record. No money moves through the app."},{"steps":["Price list: set a monthly and/or annual price for each plan and extra module (base price with the users it includes, plus a price per extra user).","Issue a license with Billing monthly or annual. The list price is shown; give a discount % or type the amount. The price stays with the license.","Charges are made for each period a few days ahead and are due some days after the period starts (Billing → Settings).","When a client pays, open the charge and click Record payment: amount, date, method and reference. Partial payments are fine."]},{"bullets":["A charge is due, partly paid, paid or overdue. Billing shows the totals, the aging and each client's balance; export charges or payments as CSV for your accountant.","A client with overdue charges is flagged in Clients and Installations, and issuing or renewing its license warns first. Nothing is held or revoked.","Mistakes are voided with a reason (a charge only when it has no payment); nothing is deleted. Everything is in the Audit Log.","Once a day the scheduler makes the charges coming due and notifies the Super Admins."]}]},{"title":"Threats & vulnerabilities (Defender)","for":"admin","mod":"","body":[{"p":"Microsoft 365 → Security → Threats & vulnerabilities shows the vulnerable software on your devices (from Defender advanced hunting), which devices have each vulnerability, Microsoft's details and write-ups about it, and Microsoft's threat write-ups. It is read only."},{"p":"Microsoft has no API for the Threat analytics reports of the Defender portal; the button at the top opens them there."},{"steps":["Permissions: ThreatHunting.Read.All for the vulnerabilities; ThreatIntelligence.Read.All for the write-ups and a vulnerability's details (Settings → Company systems → Microsoft 365 → Permissions).","The vulnerabilities need Defender vulnerability management (Defender for Endpoint Plan 2 or the add-on) and devices onboarded to Defender. Without it the list is empty and the page says why.","Devices → Compliance → More on a Windows device shows its Defender antivirus state from Intune (real-time and tamper protection, definitions, scans)."]}]},{"title":"Personal computers protected by Defender","for":"admin","mod":"","body":[{"p":"Microsoft 365 → Devices → Personal computers lets people protect the computer they own with Microsoft Defender, by choice. Their computer is not enrolled in Intune: no apps, no wipe, no access to their files."},{"steps":["Set up once: confirm the two switches Microsoft has no API for (Defender portal enforcement scope; Intune \"Allow Microsoft Defender for Endpoint to enforce Endpoint Security Configurations\"), create the device group, send the antivirus and firewall rules, upload the connection files from Defender (Settings → Endpoints → Onboarding / Offboarding → Local script).","Invite people. Each gets a personal link: they read what it means, agree by typing their name, and run a read-only check in PowerShell that reports their Windows edition and Defender state.","Windows Pro, Enterprise, Education and Mac: they download the connection file on their page and run it. The rules reach the computer through Defender.","Windows Home cannot join Defender for Endpoint. The page shows them how to keep the Defender built into Windows on; their check shows here.","Withdrawing: on their page; the disconnect file is offered there and Super Admins are notified."]},{"p":"Change the rules here, not in Intune: sending again replaces changes made there (the screen warns when Intune was changed afterwards). Real-time protection always stays on; exclusions of a whole disk or of Windows itself are refused. Every step, change and refusal is in the Audit Log."}]}]},{"cat":"Microsoft 365 & integrations","topics":[{"title":"Microsoft 365 data kept fresh in the background","for":"everyone","mod":"m365","body":[{"p":"The Microsoft 365 pages read Microsoft. To spare you the wait, the server reads them ahead of time and keeps what it read, so pages open at once. Since build BT72 this starts as soon as you sign in: for someone whose role sees Microsoft 365, the app asks the server to read every Microsoft 365 page that role can open (two at a time, in the background) and again every 15 minutes while the app is open. The scheduled job keeps the chosen pages fresh too, also when nobody is signed in."},{"h":"How a page opens (BT72)"},{"bullets":["A copy younger than 10 minutes (or kept fresh by the background job) opens at once.","An older copy, up to 24 hours, also opens at once; the app then asks the server for a new read in the background, so the next look is current. Nothing to click.","With no copy at all (the very first time), the page reads Microsoft and keeps the answer.","This covers every Microsoft 365 page: Home (also Rollout), People, Email (also Email security), Devices (also Device policies), Licenses, Security (also Alerts & actions, Access & sign-in) and Collaboration & activity.","Not kept: Diagnose and the scans you start with a button (Scan mailboxes, Check Copilot, Coverage, the license check): those always read now.","Anything changed through the Microsoft 365 pages drops every kept copy at once, so a change is never hidden behind an old copy. The \"Refresh\" button of a page always reads Microsoft.","Only people whose role has Microsoft 365 · View are given these pages; a kept copy is never shown to anyone else."]},{"h":"The line at the top"},{"bullets":["\"Microsoft 365 data updated 10:45 (2 min ago) · next about 11:00\": when the pages were last read, and when the next read is due.","\"Refresh now\" reads everything chosen at once. It runs in the background; when it is done, the pages read again. A form you are filling in and the Accounts list stay as they are.","Amber: a read failed (it is named, with Microsoft's words) or the scheduled job seems not to run. The last good copy of that page is kept.","Each page's own \"Refresh\" still reads Microsoft at once. Anything you change here (an account created, edited or licensed) shows at once."]},{"h":"Settings","mod":"integrations:edit"},{"steps":["Click \"Settings\" on the line (needs Integrations with Edit).","Tick \"On\", choose how often in business hours (10, 15, 30 or 60 minutes) and outside them (30 minutes to 4 hours, or not at all).","Tick what to keep fresh: Accounts, Licenses, Devices, Security, Service health, Groups, Guests (on by default); Apps and Usage reports (Microsoft updates those once a day).","Click \"Save\". The change is in the Audit Log."],"mod":"integrations:edit"},{"p":"Business hours are the ones under Settings → SLA & Hours; when those are not set, Monday to Friday 7:00 to 19:00. The reading is done by the scheduled job (cron-sla.php every 15 minutes, or the in-app scheduler). Reads only: nothing is changed in Microsoft. Each read is written to the Event Log (channel m365)."},{"qa":[{"q":"The line says the data is late.","a":"The scheduled job is not running. Check the cron job (Settings → SLA & Hours) or that the in-app scheduler is on (Settings → Email → Schedule)."},{"q":"A page shows data older than I expected.","a":"Use the page's own \"Refresh\" or \"Refresh now\" on the line. A change made directly in the Microsoft 365 admin center shows within about 10 minutes (the next read), or at once after \"Refresh\"."},{"q":"Several pages showed \"Something went wrong on the server\" at the same moment.","a":"Usually the database was busy for a moment (the hosting account's connection limit, a restart or a nightly backup). From build BT55 the app rides out a short blip by itself, reads try once more on their own, and a longer one says \"The database is busy or not answering right now (MySQL error n)\" with a reference. Give that reference to IT: the same reference is in the server error log. The Microsoft 365 pages also read at most 4 things at a time, so they no longer cause such a burst."},{"q":"Security shows \"Needs SecurityEvents.Read.All\" on Microsoft's next recommended actions.","a":"The app registration does not have that permission yet. In Entra: App registrations → your app → API permissions → Add → Microsoft Graph → Application permissions → SecurityEvents.Read.All → Add, then \"Grant admin consent\". The card shows at the next read."}]}]},{"title":"The Microsoft 365 area","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 has its own section in the menu, organised by what you manage. Each fact has one home; other pages link to it. Each page has a row of tabs at the top."},{"bullets":["Home: \"Needs attention\" (every problem in one prioritised list — Critical, Warning, Info — each with \"Fix →\"), \"Overview\" (cards for licenses, reclaimable seats, directory sync, device compliance, Secure Score, alerts, MFA gaps, service health, mailboxes, Teams, storage, Copilot, recommendations, app secrets, personal computers; click a card to open its screen), \"Service health\" (services, issues and Message center posts), and after a thin line \"Rollout\" and \"Diagnose\" (Super Admin).","People: \"Accounts\" (search the directory and manage one person), \"Onboard\", \"Offboard\", \"Groups\" (owners and members), \"Guests\", \"MFA\" (who is registered), \"At risk\" (the people the security assessment finds at risk, their follow-up and the changes waiting for approval) and \"History\".","Email: \"Mailboxes\" (every user, shared, room and equipment mailbox; click one for its \"send on behalf\" delegates and calendar access), \"Distribution lists\" (and who is in each), \"Message trace\" (was it sent, delivered or blocked) and \"Email security\" (SPF, DKIM and DMARC per domain, the mailbox scan for forwarding and hidden rules, and the Exchange Online controls).","Devices: \"Device inventory\" (every device in Entra and Intune, with its actions and recovery keys), \"Compliance\" (Intune compliance; Sync, Lock, and \"More\" for restart, Defender scan, retire, wipe and fresh start), \"Apps\" (apps Intune installs, and the software found on devices), \"Configuration\" (configuration profiles), \"Update rings\" (Windows updates: pause and resume), \"Device policies\" (compliance and app-protection policies, device security, back up and restore) and \"Wipe & retire\" (the requests waiting for a second person's approval).","Licenses: \"Licenses\" (seats per subscription; click one for its holders), \"Reclaim\" (disabled or idle accounts that still hold licenses), \"Reconcile\" (Microsoft 365 ↔ vTiger ↔ ITOps sign-ins, matched by email) and \"Coverage\".","Security: \"Alerts & actions\" (the one list of Defender alerts and incidents, which you can work and resolve), \"Secure Score\" (the score and Microsoft's next recommended actions), \"Access & sign-in\" (Conditional Access, sign-in methods, admin roles), \"App secrets\", \"Enterprise apps\" and \"Recommendations\".","Posture: the security assessment (findings, history, schedule).","Collaboration & activity: \"Teams\", \"Storage\" (OneDrive and SharePoint), \"Copilot\" and \"Audit log\" (the Entra directory audit log)."]},{"p":"Old bookmarks and links still open the right place: the former Overview, Accounts, Licensing, Entra ID, Usage & health, Security assessment and Risky people pages open Home, People, Licenses, People, Collaboration & activity, Posture and People → At risk."},{"bullets":["Reports are kept for 10 minutes so the screens open fast. The description then ends with \"· cached\"; click \"Refresh\" to read Microsoft again.","When a screen needs a Graph permission your Azure app doesn't have yet, it says \"Permission not granted\" and names the permission. Add it in Azure with admin consent, then click Refresh.","Dates are shown as MM/DD/YYYY in the installation's time zone.","Anything that changes accounts or licenses clears the cache, so a removed license disappears from the lists right away."]},{"tip":"Tabs you have opened stay ready while you move between them, and the data behind the other tabs of a page loads in the background, so switching is instant."},{"qa":[{"q":"I don't see Microsoft 365 in the menu.","a":"Your role needs \"Microsoft 365 · View\". People also shows for roles that only have \"Onboarding templates & history\" (just the History tab) or \"Security assessment\" (just At risk)."},{"q":"A tab I expect is missing.","a":"Onboard and Offboard need \"Microsoft 365 · Accounts\"; History needs \"Onboarding templates & history\" (view); Diagnose is Super Admin only."},{"q":"Where did Entra ID, Usage & health and Risky people go?","a":"Their tabs moved to where they are used: MFA, Groups and Guests to People; Device inventory to Devices; App secrets, Enterprise apps, Recommendations and Access & sign-in to Security; the Entra audit log, Teams, Storage and Copilot to Collaboration & activity; Service health to Home; Mailboxes to Email; Risky people to People → At risk. The Overview cards and the \"Fix →\" links open them there, and old links still work. Permissions did not change."}]}]},{"title":"Connecting Microsoft 365","for":"admin","mod":["m365_admin","settings:edit","m365"],"body":[{"p":"ITOps talks to Microsoft 365 through one Azure (Entra ID) app registration. Connect it once and the whole Microsoft 365 area, Server Guardian's Microsoft 365 cards and onboarding / offboarding all work."},{"steps":["In Azure → App registrations, create or open the ITOps app. Note its Directory (tenant) ID and Application (client) ID, and create a client secret.","Under API permissions, add the Application permissions you need (see \"What Microsoft 365 permissions ITOps needs\") and click \"Grant admin consent\".","In ITOps, go to Logs & Integrations → Integrations → \"System\" tab → \"Microsoft 365 connection\".","Enter the \"Tenant ID\", \"Client ID\" and \"Client secret\", then click \"Save Microsoft 365 settings\".","Open Microsoft 365 → Home → \"Diagnose\" and click \"Refresh token & re-test\". Each capability should show ✓ OK."],"bullets":["The \"System\" tab is Super Admin only.","The client secret is write-only and stored encrypted. Leave it blank to keep the saved one.","Microsoft sign-in (SSO) uses the same configuration — there is one tenant, one client ID and one secret for both. If the upgrade found two different saved secrets, a yellow note asks you to save the current one once."]},{"warn":"When the Azure client secret expires, every Microsoft 365 feature stops and Diagnose shows a token error. Create a new secret in Azure and save it here (and in Settings → Sign-in & AI too if you use SSO or Graph mail)."},{"tip":"After you add a permission in Azure, click \"Refresh token & re-test\". ITOps caches the token, so a new consent is not seen until the token is refreshed."}]},{"title":"Setting up the Teams app","for":"admin","body":[{"p":"Logs & Integrations → Integrations → \"Microsoft Teams\" turns ITOps into an app inside Teams: a tab with automatic sign-in, notifications in each person's Teams activity feed, and announcements that are confirmed inside Teams. Super Admin only. Nothing changes for people who keep using the browser."},{"h":"What you need first"},{"bullets":["ITOps served over HTTPS (the page checks this).","Microsoft 365 sign-in already working (Settings → Sign-in & AI). Teams uses the same Azure app registration and the same rules: a person without an ITOps account gets one with the Viewer role on first use, and a disabled or inactive account is refused.","Microsoft Graph connected, for the Teams notifications. The tab and the sign-in work without it.","The current .htaccess from the install package on the server: it allows Teams, and only Teams and Microsoft 365, to show ITOps in a frame."]},{"h":"1. In Azure (once)"},{"steps":["Entra admin center → App registrations → your ITOps app → \"Expose an API\".","Set \"Application ID URI\" to the value shown on the page (api://your-address/client-id). Use \"Copy\".","\"Add a scope\" named access_as_user, for admins and users.","\"Add a client application\" for the two Teams client IDs shown on the page, ticking the scope. The IDs for Outlook and the Microsoft 365 app are optional.","Under \"Manifest\", set requestedAccessTokenVersion to 2 and save."]},{"h":"2. Switch it on and add it to Teams"},{"steps":["Click \"Switch on\", then \"⬇ Download the app package\". The zip contains the app description and two icons, named after your ITOps.","Teams admin center → Teams apps → Manage apps → Actions → \"Upload new app\" → choose the zip.","Teams apps → Setup policies → your policy → add the app under \"Installed apps\" and \"Pinned apps\". Everyone then has it without installing it themselves; allow a few hours.","To try it alone first: Teams → Apps → Manage your apps → Upload an app → Upload a custom app (your tenant must allow custom app uploads)."]},{"tip":"If you rename ITOps or move it to another address, download the package again and upload it as an update. The version number goes up by itself, which Teams requires."},{"h":"3. Notifications in Teams"},{"bullets":["Three switches choose what is copied to each person's Teams activity feed: \"Announcements\" (on), \"Tickets\" and \"Alerts and reminders\" (off until you tick them).","They are sent by the scheduled job a few minutes after the bell, only to people who have the app in Teams. Switching a kind on never sends older notifications.","\"Send me a test\" sends one to you and explains a refusal. The line under it shows the last run: sent, people without the app, failures.","Normally nothing is needed in Azure for this: the permission travels in the app package. If the test reports a refusal after you uploaded the current package, add the Graph application permission TeamsActivity.Send with admin consent."]},{"h":"4. Device inventory"},{"p":"\"Add the device people open ITOps on to the Device inventory\" records, at sign-in, the operating system and the browser or Teams client as the browser reports them — in Teams and in a normal browser. See \"Device inventory: every computer that signs in\"."},{"h":"If something does not work"},{"qa":[{"q":"The tab stays blank or Teams says the app cannot be reached.","a":"Check that the server has the .htaccess from this build (Teams must be allowed to frame the page) and that the address in the package is the HTTPS address people can reach."},{"q":"\"The token was issued for another application\".","a":"The Application ID URI on the Azure app is not the value shown on the setup page. Copy it again; the address part must be in lower case."},{"q":"\"The token does not carry the access_as_user scope\".","a":"Add the scope under \"Expose an API\", and tick it for each client application."},{"q":"Teams asks every person for consent.","a":"The Teams client IDs are not pre-authorized. Add them under \"Expose an API\" → \"Add a client application\"."},{"q":"Notifications do not arrive.","a":"The person must have the app in Teams (setup policy, or installed by hand), the package must be the current one, and the scheduled job must be running. \"Send me a test\" names the cause for your own account."},{"q":"How do I turn it off?","a":"\"Switch off\" stops the sign-in from Teams and the Teams notifications at once. Remove the app in the Teams admin center when you no longer want it listed."}]}]},{"title":"What Microsoft 365 permissions ITOps needs","for":"admin","mod":["m365_admin","settings:edit","onboarding:edit","m365"],"body":[{"p":"The Azure app needs Application permissions (not Delegated), each with \"Grant admin consent\". Add only what you use. The onboarding \"Pre-flight check\" names any permission a step is missing."},{"h":"Onboarding, offboarding and Microsoft 365 → People"},{"bullets":["User.ReadWrite.All: create, update and disable users, edit contact information and custom attributes 1 to 15, set and remove the manager, assign and remove licenses, revoke sessions. Phone numbers of accounts that hold an administrator role are the exception: Microsoft refuses an application there, whatever the permission.","GroupMember.ReadWrite.All (or Group.ReadWrite.All): add to and remove from groups. Group.ReadWrite.All is also what changing group owners and creating groups on People → Groups need; it is optional.","Organization.Read.All: read licenses and seat counts.","MailboxSettings.ReadWrite: auto-reply and the forwarding rule.","Files.ReadWrite.All (or Sites.ReadWrite.All): share a leaver's OneDrive.","UserAuthenticationMethod.ReadWrite.All: \"Reset MFA\", sign-in methods and Temporary access pass on Microsoft 365 → People."]},{"h":"Read-only pages and Guardian"},{"bullets":["User.Read.All: Users tab and offboarding verification.","Reports.Read.All: Usage tab. Reports.Read.All or AuditLog.Read.All: MFA registration (2FA adoption card and scorecard).","ServiceHealth.Read.All: Service Health tab (optional).","SecurityEvents.Read.All and SecurityIncident.Read.All: Microsoft Defender card.","DeviceManagementManagedDevices.Read.All: Intune device compliance.","GroupMember.Read.All (or Group.Read.All): announcements and ticket notices to a Microsoft 365 group or distribution list read its members when they are sent."]},{"h":"Email through Graph"},{"bullets":["Mail.Send to send, and Mail.ReadWrite to turn mailbox messages into tickets."]},{"tip":"Check your work in Microsoft 365 → Home → Diagnose: \"Permissions in token\" lists what the token really carries, \"App registration in Azure\" shows what is still waiting for admin consent or was added as Delegated, \"Permissions that change something\" says for each kind of change whether it is Granted, Not granted or Not granted (optional), and the capability table shows which read tests pass — with the reason next to each one that fails. See \"I added a permission and it still says 403\"."},{"h":"Optional extras (reports)"},{"bullets":["DeviceManagementManagedDevices.Read.All — the Devices tab (DeviceManagementManagedDevices.PrivilegedOperations.All adds the Sync and Lock buttons).","DeviceManagementConfiguration.ReadWrite.All — read AND edit compliance policies, the All-policies inventory, backup/restore/clone and baseline seeding.","DeviceManagementApps.ReadWrite.All — app-protection (MAM) policies for personal phones (edit, back up, clone) and the phone-apps column of Rollout → Readiness (Read.All is enough for that).","Policy.Read.All — the Conditional Access card; Policy.ReadWrite.ConditionalAccess — create sign-in rules from templates and change their state; Policy.ReadWrite.SecurityDefaults — turn Security Defaults off.","MailboxSettings.Read (ReadWrite to disable rules) — the mailbox forwarding/rules audit. Mail.ReadWrite is only needed for email-to-ticket through Graph; scope it to the help-desk mailbox with RBAC for Applications.","SecurityEvents.Read.All / SecurityIncident.Read.All / SecurityAlert.Read.All — the Defender panel (SecurityAlert.ReadWrite.All to resolve alerts from ITOps).","AuditLog.Read.All — the MFA registration report, idle-license detection and the sign-in log behind Devices → Device inventory (idle detection and the sign-in log also need an Entra ID P1 licence in the tenant).","Device.Read.All — the Entra device list behind Devices → Device inventory (read-only).","Device.ReadWrite.All — disable, enable and remove Entra devices from the Device inventory (replaces Device.Read.All). Disabling may also need the Entra role \"Cloud Device Administrator\" on the ITOps enterprise application.","BitlockerKey.Read.All — show a BitLocker recovery key (BitlockerKey.ReadBasic.All only lists that a key exists). DeviceLocalCredential.Read.All — show the local administrator password kept by Windows LAPS.","People → Groups needs nothing new when GroupMember.ReadWrite.All (listed above) is granted. With only Group.Read.All the list works, read-only.","People → Guests needs nothing new: it uses User.Read.All, and User.ReadWrite.All to block or remove a guest.","Directory.Read.All — the delegated permissions (what administrators and people consented to) on Security → Enterprise apps. The applications themselves and their application permissions use Application.Read.All.","Collaboration & activity → Audit log uses AuditLog.Read.All, already listed above.","TeamsActivity.Send — only if Teams refuses the notifications of the Teams app (normally the permission comes with the app package). The Teams sign-in itself needs no Graph permission: it uses \"Expose an API\" on the same app.","Application.Read.All — the app-registration secret/certificate expiry list.","Policy.ReadWrite.AuthenticationMethod — allow or turn off sign-in methods (Security → Access & sign-in → Sign-in methods). UserAuthenticationMethod.ReadWrite.All (already listed for Reset MFA) also covers Temporary pass and removing a single method.","Without them, those panels show a card naming the missing permission; everything else keeps working.","DeviceManagementServiceConfig.Read.All — reads the enrolment restrictions so the Devices tab can warn when personal Windows PCs are allowed to enrol (BT15). DeviceManagementConfiguration.ReadWrite.All (already listed for the compliance editor) is what \"Seed device security\" uses."]},{"p":"RoleManagement.Read.Directory (or Directory.Read.All) — the admin-roles list, and the check that stops non-Super Admins from resetting the password, issuing a Temporary pass or resetting MFA for an account that holds a Microsoft 365 admin role. Without it, those actions are Super Admin only."},{"warn":"High-value permissions — review them monthly and keep only what you use: User.ReadWrite.All, UserAuthenticationMethod.ReadWrite.All, Policy.ReadWrite.ConditionalAccess, DeviceManagementConfiguration.ReadWrite.All, Files.ReadWrite.All / Sites.ReadWrite.All, Mail.ReadWrite, Device.ReadWrite.All, BitlockerKey.Read.All and DeviceLocalCredential.Read.All. Check what the token really carries under Microsoft 365 → Home → Diagnose → \"Permissions in token\"."},{"p":"Limiting mail access: Microsoft's current way to restrict an app to certain mailboxes is Exchange Online \"RBAC for Applications\" (Application Access Policies are now legacy). Scope Mail.ReadWrite / Mail.Send to the help-desk mailbox that way and remove the tenant-wide Mail.* consent in Entra. The mailbox-rule audit uses MailboxSettings.Read/ReadWrite, so it keeps working across all mailboxes."},{"p":"The full list — every permission, what uses it and whether it can be removed — is in BT14-SECURITY-VALIDATION.md in the support files pack (Reference folder)."}]},{"title":"I added a permission and it still says 403","for":"admin","body":[{"p":"You added a permission in Azure, came back, and the feature still says \"403\" or \"token doesn't have the required permissions\". Microsoft 365 → Home → Diagnose tells you which of four things happened, so you do not have to guess. Click \"Refresh token & re-test\" first: it throws away the saved token and asks Microsoft for a new one."},{"h":"Where to look"},{"bullets":["\"App registration in Azure\" (the card names your app): \"Waiting for admin consent\" lists the permissions that are on the app but not in the token. \"Delegated permissions\" lists the ones added with the wrong type.","\"Live capability tests\": every test that fails with 401 or 403 has a boxed line under Microsoft's message that names the cause.","\"What to do\" at the top repeats the actions in order."]},{"h":"The four causes"},{"qa":[{"q":"\"Admin consent missing\"","a":"The permission is on the app as an Application permission, but nobody clicked \"Grant admin consent for (your organization)\". Until then Microsoft leaves it out of the token. In Azure → App registrations → your app → API permissions, click that button — it needs a Global Administrator or a Privileged Role Administrator — and wait until the Status column shows a green tick \"Granted for …\". Then \"Refresh token & re-test\"."},{"q":"\"Added as Delegated\"","a":"Azure offers every permission twice: \"Delegated permissions\" (for a person who signs in) and \"Application permissions\" (for an app that works on its own). ITOps works on its own, so only Application permissions reach it — a Delegated one does nothing here, even with consent. Add it again: Add a permission → Microsoft Graph → \"Application permissions\" → the same name, then Grant admin consent. You can remove the Delegated one."},{"q":"\"Not on this app\"","a":"The permission is not on this app registration at all. If you did add it, it went to another app: compare the Application (client) ID in Azure with \"Client (app) ID\" on Diagnose. Organizations often have two apps with similar names."},{"q":"\"Permission is granted\"","a":"The permission is in the token and Microsoft still said no, so it is not a permission problem. Usual reasons: the organization does not have the licence the feature needs (Entra ID P1 for sign-in data, Intune for device policies), the feature is switched off, or the change is still spreading inside Microsoft — wait a few minutes and re-test."}]},{"h":"Good to know"},{"bullets":["Diagnose only reads. Nothing on this screen changes your organization.","Reading the app registration uses Application.Read.All (the same permission the \"App registrations\" secret-expiry check uses). Without it the card says so and the tests below still work; the boxed line then tells you what to check by hand.","A new consent normally shows up within a minute. If the permission is still \"waiting\" after you granted it, look at the Status column in Azure: \"Not granted for …\" means the click did not go through.","The names Diagnose asks for are the exact names to pick in Azure, for example BitlockerKey.Read.All, DeviceLocalCredential.Read.All and DeviceManagementServiceConfig.Read.All."]},{"tip":"Messages in the browser's developer console such as \"Permissions policy violation: unload is not allowed\" from a file called frame.js come from a browser extension or from Microsoft Teams, not from ITOps, and can be ignored."}]},{"title":"Accounts: the list (search, filter, columns, changing a cell, actions)","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → People → \"Accounts\" is a grid: every account, one per row, like a spreadsheet. The first view is the domain your organization chose in Settings → Company systems → \"Microsoft 365 · People — the domain shown first\" (else Microsoft's default domain, for example \"@example.org\"); guests and the other domains are under \"All domains\"."},{"h":"Finding accounts"},{"bullets":["The search box looks in the name, the sign-in name, the email and the columns shown.","Under every heading is a filter. A column with a short list of values (Sign-in, Licenses, vTiger, a field with choices…) offers them to pick, with \"(empty)\" for the rows without a value. Any other column takes a part of the text; type (empty) to see the rows without one.","Click a heading to sort by it. Click again for the other direction, a third time to go back to the name.","The domain list next to the search box shows one domain, with how many accounts it has: the domains Microsoft lists and those the accounts use. Your choice, \"All domains\" too, is remembered on that browser. \"Show all\" brings everyone back.","\"Clear filters\" removes the search and every filter.","Under the grid: where you are (\"1–50 of 758\"), \"← Previous\", \"Next →\" and \"Rows per page\" (25, 50, 100 or 250)."]},{"h":"Choosing the columns"},{"steps":["Click \"Columns\" and tick the ones to show: sign-in state, job title, department, company, office, phones, fax, your own custom fields, manager, email, first and last name, employee ID and type, the address, usage location, licenses, vTiger, other systems, type, created, last sign-in.","\"Manager\" and \"Last sign-in\" are marked \"slower\": they are read from Microsoft only while their column is shown, and take a few seconds more.","The order: \"Columns\" lists the columns shown under \"Shown, left to right\", numbered. ▲ moves one to the left, ▼ to the right. You can also drag a heading in the list and drop it on another. A column you tick under \"Hidden\" takes its usual place; move it from there.","\"Back to the standard columns\" undoes your choice and the order. The name is always first. Your columns and their order are remembered on that browser."]},{"h":"Changing a value in the grid"},{"steps":["Click the cell: job title, department, company, office, a phone, the fax, a custom field, the address… A box opens in the cell. A custom field with choices opens as a list.","Type the value and press Enter, or click elsewhere. Esc leaves the cell as it was.","The cell is saved exactly as \"Edit Microsoft 365 info\" saves it: checked by the same rules, sent to Microsoft 365, and written to the Audit Log with your name, the account, the old value and the new one.","If Microsoft 365 refuses the value, the reason shows under the cell and nothing changes. \"Leave it as it was\" closes the box."]},{"bullets":["Not changed in the grid: the sign-in name and the email (they change the mailbox), the manager, licenses and groups. Open the account for those.","An account copied from an on-premises directory cannot be changed here; change it in that directory.","Changing a cell needs \"Microsoft 365 · Accounts\"."]},{"h":"Actions on a row"},{"p":"The last column, \"Actions\", does the common things without opening the account. Each one asks first."},{"bullets":["\"Open the account\" and \"Edit contact information…\".","\"Reset password…\": a strong temporary password, to be changed at next sign-in. It is shown once in a box above the grid, with \"Copy\".","\"Reset MFA…\" and \"Revoke sessions…\".","\"Block sign-in…\" or \"Restore sign-in…\". You cannot block your own account.","\"Offboard…\" opens the Offboard tab with that person.","The result of each action stays above the grid until you remove it with ✕."]},{"h":"The account, in a panel on the right"},{"p":"Click a name. The account opens in a panel that slides over the right part of the list, below the tabs, with everything described in \"Accounts: managing one person\". The list underneath stays as it was: search, filters and page. ‹ and › go to the previous and the next account of the list. \"Edit Microsoft 365 info\" opens inside the same panel; \"← Back to the account\" returns to it. \"✕ Close\" or Esc closes the panel. When you changed something and did not save, ITOps asks first. On a phone the panel takes the whole screen; \"← Back to the list\" returns."},{"h":"Several accounts at once"},{"p":"Tick the rows: the box in the heading ticks the page, and \"Select all N\" takes every row that matches. \"Edit selected…\" opens the page described in \"Editing several accounts at once\"."},{"h":"Export"},{"p":"\"Export CSV\" saves the rows that match, on every page, with the columns shown."},{"qa":[{"q":"The list is not what Microsoft 365 shows right now.","a":"The list is read from Microsoft 365 and kept for five minutes; the line under the search box says when it was read. \"Refresh\" reads it again. A change you make here shows at once."},{"q":"\"Last sign-in\" says \"not available\".","a":"Sign-in dates need Entra ID P1 and the permission AuditLog.Read.All."},{"q":"I cannot click a cell.","a":"Your role needs \"Microsoft 365 · Accounts\"; or the account is copied from an on-premises directory; or that column is not a value of the account (the sign-in state, licenses, vTiger, other systems)."},{"q":"I see no boxes to tick.","a":"Ticking rows is for changing several accounts, which needs \"Microsoft 365 · Accounts\"."},{"q":"A person I expect is missing.","a":"Look at the domain list: guests and the accounts of another domain are under \"All domains\". Then click \"Clear filters\"."},{"q":"Where is the column \"Other systems\"?","a":"It needs the permission \"Company systems\" (View)."},{"q":"The page opens on \"@example.org\". I want everybody.","a":"Choose \"All domains\" once. It is remembered on that browser."},{"q":"My custom fields are not in the list.","a":"Click \"Columns\": your own fields are marked \"· custom\". A ticked one is in the list, after the standard columns, so on a narrow screen it may be off to the right: scroll the list, or move the column to the left with ▲ in \"Columns\" (or drag its heading). An empty cell means the account has no value in that field yet; a value kept somewhere else, for example an extension typed in \"Department\", is not copied by itself."}]}]},{"title":"Accounts: managing one person (password, MFA, licenses, groups, roles)","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → People → \"Accounts\" lists your directory as a grid, one account per row (see \"Accounts: the list\"). Click a name: the account opens in a panel over the right part of the list. The green or amber dot before a name shows whether sign-in is enabled; the column \"vTiger\" shows the linked vTiger user (★ = vTiger admin, \"no vTiger\" = nobody matched)."},{"p":"The panel on the right starts with the person's name and \"Actions\": the ones your role allows. Under them: the profile in three columns (job title, department, company, manager, office, phone numbers, your own custom fields), the block \"Systems\", then licenses, groups, sign-in methods, directory roles and recent sign-ins. \"Edit Microsoft 365 info\" at the top opens the edit page; \"+ Show change history\" lists what was changed on this account from ITOps, by whom and when. To change several accounts together, tick their rows in the list and choose \"Edit selected…\". ‹ and › at the top of the panel go to the previous and next account; \"✕ Close\" or Esc closes it. On a phone the panel opens full width; \"← Back to the list\" returns. The change history is shown to people who edit accounts or who can read the Audit Log."},{"h":"Systems: every system for this account"},{"bullets":["One row per system. Microsoft 365: sign-in enabled or blocked, how many licenses and groups. vTiger: the linked user and its status, in red with \"still active while Microsoft 365 is blocked\" when that is so. Then every company system in use (HubSpot, JustCall, eFax…) with the person's account there.","A system tracked by hand: \"+ Record an account\" opens a box for the account name and a note, in place. \"Edit\" corrects it. \"Close\" records that the account was removed in that system; ITOps does not remove it there. \"+ Show closed accounts\" lists what was closed, by whom and when, and offers \"Open again\".","A connected system (JustCall) shows what was read from it, with \"Read from JustCall: change it there.\"","In the list, the column \"Other systems\" says \"+2 system accounts\": how many accounts the person has in the other systems. It is red, with \"still open\", when their sign-in is blocked.","The rows of the company systems need the permission \"Company systems\" (View; Edit to record, correct and close). Without it the block shows Microsoft 365 and vTiger only.","There is no second list of the people under Company systems. The ones to look at are under Microsoft 365 → People → \"Needs attention\"."]},{"h":"Showing one domain only"},{"p":"When the organization has more than one verified domain, a list next to the search box lets you pick one. The first view is your default domain, for example \"@example.org\". The list then holds only the accounts whose sign-in name ends with that domain, and a line says how many there are. The search and the filters keep working inside the domain."},{"bullets":["\"All domains\" (or \"Show all\") brings everyone back.","Your choice, \"All domains\" too, is remembered on that browser, so the screen opens the same way next time.","Guests sign in with another organization's address, so they appear under \"All domains\" (and under the \".onmicrosoft.com\" domain), not under your own domains.","An organization with a single domain does not get the list."]},{"h":"Editing the account and the vTiger user"},{"p":"At the top right of the account panel: \"Edit Microsoft 365 info\" changes the person's Microsoft 365 contact information, and \"Edit vTiger user\" (shown when the person has a vTiger user and your role has vTiger · Users) opens their vTiger profile, employee record and password inside the panel. \"← Back to the account\" returns to the account. Everything about a person's accounts is in one place."},{"h":"How a person is linked to their vTiger user"},{"steps":["By email: a vTiger user whose email is the person's email or sign-in name. This is the normal case and the badge reads \"vTiger: jdoe\".","By user name, only when no email matched: a vTiger user whose user name is the part of the sign-in name before the \"@\" (jdoe@example.org → \"jdoe\"). The badge then adds \"· by user name\", and hovering it shows the email that is on the vTiger record."]},{"bullets":["A match by user name is a strong hint, not proof: two people on different domains can share the same first part. So when you offboard, \"Deactivate linked vTiger user\" starts unticked for these, with a note asking you to check it is the same person. Matches by email start ticked, as before. ITOps never deactivates such a vTiger user, or moves its records, until a person has confirmed it is the same person (see \"Offboarding in vTiger: reassign, then deactivate\").","Guests are matched by email only.","If two vTiger users match, the active one is used, then an admin, then the oldest.","The same rule is used by Reconcile, the Offboard tab and the offboarding steps in History, so they always agree with this screen."]},{"warn":"\"vTiger users are not shown.\" in amber at the top of the list means ITOps could not read vTiger at all — the message says why. The usual reason is an older bridge file on the vTiger server: upload vtiger-bridge/itops-bridge.php (build o5) from the install package to the vTiger web root, next to config.inc.php. Same secret, nothing else to change; then Integrations → vTiger provisioning → \"Test bridge\" should say build o5."},{"h":"Actions, at the top of the panel (each asks to confirm in place)"},{"bullets":["\"Reset password\" — generates a strong 16-character temporary password. Tick or untick \"Require change at next sign-in\", then \"Generate & reset\". The password is shown once, with \"Copy\".","\"Reset MFA\" removes every MFA method; they register again at next sign-in. \"Revoke sessions\" signs them out everywhere.","\"Block sign-in\" / \"Restore sign-in\". You can't block your own account.","\"Offboard…\" — a quick offboard from the panel: sign-in is always blocked; choose revoke sessions, remove all licenses, remove from all groups, deactivate the linked vTiger user and (optionally) reassign their vTiger records first. For auto-reply, forwarding, OneDrive handover, equipment or a scheduled last day use the Offboard tab.","Licenses and groups are folded: the heading says how many (\"+ Licenses (2)\") and the line under it names them. Click the heading to open the list. Licenses: ✕ removes one; \"+ Add license\" lists subscriptions with seats left.","Groups: ✕ removes; \"+ Add to group\" searches groups. Dynamic and on-prem-synced groups are greyed out (they can't be changed here).","Directory roles are folded like licenses and groups: \"+ Directory roles (1)\" with the names on one line, in red when one is high-risk. Click the heading to open the list. \"+ Assign role\" → pick the role → \"Yes, grant\". High-risk roles (Global Administrator and similar) are marked. Nobody can remove roles from their own account.","\"+ Manage methods\" lists sign-in methods with ✕ to remove one (a lost key or old phone). \"+ Temporary access pass\" issues a one-time pass (1–8 hours), shown once."]},{"p":"Every action is recorded in the Audit Log and the Event Log. Accounts are blocked, never deleted."},{"qa":[{"q":"Which permission does each button need?","a":"Edit contact information / Block / restore / Offboard / Onboard: \"Microsoft 365 · Accounts\". Custom fields (the definitions): \"Onboarding\" with Edit. Password, MFA, sessions, methods, Temporary access pass: \"· Credentials\". Licenses: \"· Licenses\". Groups: \"· Groups\". Directory roles: \"· Directory roles\". vTiger deactivate / reassign: \"Provisioning · Offboard from vTiger\"."},{"q":"Last sign-in says \"unknown\".","a":"Sign-in dates need Entra ID P1 and AuditLog.Read.All."}]},{"h":"Admin accounts are Super Admin only"},{"bullets":["Reset password, reset MFA, Temporary access pass, block sign-in, sign out everywhere and Offboard: when the account holds a Microsoft 365 admin role — directly, through a group that can hold roles, or eligible in PIM (Privileged Identity Management) — only a Super Admin can do it. The app checks the roles each time; when Microsoft does not answer, a Super Admin must do it. Every refusal is in the Audit Log.","A password reset done by someone other than a Super Admin always asks the person for a new password at the next sign-in.","Directory roles: the high-risk roles (Global Administrator, Privileged Role Administrator, Security, User, Exchange, SharePoint, Intune, Helpdesk, Password Administrator and similar) are assigned and removed only by a Super Admin; nobody gives a role to their own account. Groups that can hold admin roles are changed in the Entra admin center."]}]},{"title":"Editing an account: name, job, phones, address, manager","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → People → pick a person → \"Edit Microsoft 365 info\" opens in the account panel, in place of the account, with everything Microsoft 365 keeps about the person that an administrator normally changes. \"← Back to the account\" returns; with unsaved changes ITOps asks first. You do not need the Microsoft 365 admin center for it."},{"h":"What you can change"},{"bullets":["Name: First name, Last name, Display name. \"Use … as the display name\" builds it from the first and last name.","Organization: Job title, Department, Company, Office, Employee ID, Employee type, Manager (search a person; ✕ on the manager removes it; ✕ on a person you just picked takes the pick back), and your custom fields for this section.","Contact information: Office phone, Mobile phone, Fax number, Street address (it can have more than one line), City, State or province, ZIP or postal code, Country or region, and your custom fields for this section.","Settings: Usage location (two letters, for example US) and Preferred language."]},{"steps":["Change what you need. Every field you changed gets a blue outline and a line \"was: …\" with \"undo\".","The Save button counts the changes (\"Save 3 changes\") and the line next to it names them. Nothing is sent until you press it.","Press Save. Only the fields you changed are sent to Microsoft. The page closes and the account panel says what was saved.","To check later who changed what, open \"+ Show change history\" on the account, or search the person's sign-in name in the Audit Log."]},{"h":"Fill from company-wide values"},{"p":"If your administrator saved company-wide values (Onboarding Templates → \"Custom fields\"), the button \"Fill N empty fields from company-wide values\" puts them into the fields that are still empty, for example the company name, the office address or the main phone. It never replaces a value the account already has, and nothing is saved until you press Save. This is checked again when you save: if somebody filled the field in meanwhile, it is left alone and the message says which field. The button offers only fields that are empty on the account itself: a field you have just emptied on the page is being cleared, and the button does not fill it again. If a save is partly refused and the page stays open, a line under the results names the filled fields that were left alone."},{"h":"When Microsoft refuses part of it"},{"p":"Phone numbers, the fax number, custom fields and the manager are each sent on their own. If Microsoft refuses one of them, the others are still saved. The page stays open with a box that says, for each part, \"✓ Saved\", \"✗ Refused\", \"? Outcome not known\" or \"– Not sent\", Microsoft's own message and what to do. The refused fields keep their blue outline so you can try again or undo them. If no clear answer came back from Microsoft (a timeout), the part is marked \"? Outcome not known\": open the account again to see the values it has now."},{"bullets":["Phone numbers of an account that holds an administrator role: Microsoft does not let an application change them. Change that number in the Microsoft 365 admin center.","\"Insufficient privileges\" on everything: the app is missing User.ReadWrite.All with admin consent. Check Microsoft 365 → Home → Diagnose → \"Permissions that change something\".","An account that is copied from an on-premises directory is read-only here. The page says so at the top; change it in that directory."]},{"h":"The page shows the account as it is now"},{"p":"The page keeps only what you changed. Everything else is the account as it was last read from Microsoft 365. So when the account is read again while your page is open (after a save that was partly refused, or because a colleague changed it), you see the new values, your own changes stay outlined, and nothing you did not type is sent."},{"bullets":["A value a colleague changed meanwhile is shown as it is now and is not sent back.","A part Microsoft confirmed is shown as saved at once, even if the next reading of the account is a few seconds behind.","The manager is removed only by clicking its ✕, and only while the account still has the manager your page showed. If it has another manager by the time you save, nothing is changed: the page says so, forgets the removal and reads the account again. To remove the manager the account has now, click its ✕ again.","When a save sends several parts (a job title, a phone number, the manager), the manager is read once more right before it is removed. If somebody gave the account another manager in those seconds, the other parts are saved and the removal is not sent; the results box says \"Not removed: the account got another manager while this save was running\".","While a save is running, no manager can be searched or picked.","If the manager could not be read when the page opened, the page says so and does not offer to remove it. You can still set a new one.","A page left open from an older build is told to reload (Ctrl+F5) when it tries to remove a manager."]},{"h":"Dynamic groups"},{"p":"A group in Microsoft 365 can have a rule instead of a member list, for example \"everyone whose department is Sales\". When you change a value such a rule reads (department, job title, company, office, country, usage location, a custom attribute), Microsoft takes the person into the group or puts them out, usually within minutes, sometimes hours. Licenses, teams and access given through that group follow. Check People → Groups for groups marked \"Dynamic\" before changing those values for people who depend on them."},{"h":"If saving takes too long"},{"p":"The web host ends a request after about a minute, so a save gives each part a limited time. A part that could not be sent in time is shown as \"– Not sent\": it was certainly not changed. Press Save again; only what is still different is sent. If no answer comes back at all, the page says it is not known whether the changes were saved and reads the account again. Once it has, it tells you so: what is still outlined may not have been saved, and you can press Save again, because only what is still different from the account is sent. If the account cannot be read either, close the page and open the account again to see what it has. The Audit Log has an entry for every part that was sent."},{"h":"What is not edited here"},{"bullets":["Email address and sign-in name: changing them changes the mailbox addresses, so that stays in the Microsoft 365 admin center.","Hire date: Microsoft does not let an application write it.","Email aliases, shared mailboxes, mailbox permissions and distribution lists are Exchange settings that Microsoft does not offer to this kind of app."]},{"tip":"Email signatures: tools that read Microsoft 365, such as CodeTwo, pick up a new title or phone number by themselves. CodeTwo reads the accounts again about every 20 minutes. Outlook and Teams address books can take up to a day."},{"p":"Every part of a save is written to the Audit Log as soon as Microsoft answers it (action m365_user_update), with the old and the new value of each field. One save that changes a job title, a phone number and the manager is therefore three entries. A part that was refused, whose outcome is not known, or that was not sent is written too (m365_user_update_refused) with the value that was wanted and the reason. A refused removal of a manager is logged the same way. When the value that was wanted is \"nothing\" (a field you cleared, a manager you removed), the entry says \"wanted: empty\"."},{"qa":[{"q":"I do not see \"Edit Microsoft 365 info\".","a":"Your role needs \"Microsoft 365 · Accounts\" with Edit."},{"q":"Save is grey.","a":"Nothing differs from what the account already has, or the account is copied from an on-premises directory."},{"q":"Can I change several accounts at once?","a":"Yes: tick their rows in the list and click \"Edit selected…\". See \"Editing several accounts at once\"."},{"q":"I cleared a field and saved. What happened in Microsoft 365?","a":"The value was removed from the account. Two values cannot be emptied: the display name, and the usage location once it is set (change it to another country instead)."},{"q":"\"The manager was not removed and nothing else was changed…\"","a":"The account has another manager now than the one your page showed, or the page is from an older build. Nothing was changed. The page forgets the removal and reads the account again; if you still want to remove the manager the account has, click its ✕ and save. A page from an older build is told to reload (Ctrl+F5)."},{"q":"I do not see \"Show change history\" any more.","a":"The change history is a piece of the Audit Log. It is shown to people who edit accounts (\"Microsoft 365 · Accounts\" with Edit) or who can read the Audit Log. It shows what was done to that account only; entries about groups, devices, settings and bulk-run summaries are in the Audit Log itself."},{"q":"A value I pasted looks the same but was saved a little shorter.","a":"Invisible characters (zero-width spaces, direction marks) and control characters are removed, and repeated spaces become one. They make two values look the same and compare different, which breaks signatures and group rules."}]}]},{"title":"Editing several accounts at once","for":"admin","mod":"m365","body":[{"p":"When the same value belongs on many accounts (a department that was renamed, a new office address, a new manager for a team, the company name on everyone), change them together instead of opening each account."},{"steps":["Open Microsoft 365 → People. Every row of the list has a box to tick at its start.","Tick the accounts. Search, filter or pick a domain to find them; the selection is kept meanwhile. The box in the heading ticks every row of the page, and \"Select all N\" in the bar takes every row that matches.","Click \"Edit selected…\". A full page opens with the accounts at the top; ✕ takes one out.","Under \"What to change\", choose for each field you want: \"Set for everyone\", \"Set only where empty\" or \"Clear\", and type the value. Fields left on \"Do not change\" are not touched.","Click \"Preview\". ITOps reads every account and shows, per account, each value as old → new. Nothing is changed yet.","Type the confirmation it asks for (for example CHANGE 12: the number of accounts the run will change) and click \"Change 12 accounts\".","Read the result: every account is Changed, Skipped, Failed or Not known, with the reason. Click \"Done\"."]},{"h":"What can be changed this way"},{"bullets":["Organization: Manager, Job title, Department, Company, Office, Employee type, and your custom fields for this section.","Contact information: Office phone, Fax number, the address, and your custom fields for this section.","Settings: Usage location and Preferred language.","Not offered, because they belong to one person: first name, last name, display name, employee ID and mobile phone. Edit those on the account."]},{"h":"The three ways to set a field"},{"bullets":["\"Set for everyone\": every selected account gets the value, replacing what it had.","\"Set only where empty\": only accounts that have nothing in that field get the value. \"Use the company-wide values, only where empty\" sets all your company-wide values this way in one click.","\"Clear\": the value is removed. The usage location cannot be cleared once it is set; the preview says so for the accounts concerned and leaves that field alone."]},{"h":"What the preview leaves out"},{"bullets":["Accounts that already have every value: nothing to change.","Accounts copied from an on-premises directory: change them there.","The person you chose as manager is not made their own manager; their other fields still change.","An account that could not be read just now, or whose current manager could not be read when the manager is part of the change: the preview says \"N could not be read\" and is marked \"not complete\". A run is only applied on a complete preview: press \"Preview again\", or take those accounts out."]},{"warn":"There is no undo button. To reverse a bulk edit, run another one with the old value. The Audit Log shows what each account had before."},{"p":"If Microsoft refuses the first kind of change on an account (for example the app lost its permission), the run stops and the accounts after it are not attempted. If only that one account is protected, take it out of the selection and run again."},{"h":"When a run does not change everything"},{"p":"\"Not known\" means no clear answer came back for that account (a network cut, the host's time limit, or Microsoft answering late): the change may or may not have been made. \"Failed\" means Microsoft refused a part, or a part could not be sent in time; what was saved and what was not is named. In both cases the page offers \"Read the accounts again\": the preview runs again, the result of the run stays on screen above it, and the accounts that still show a change are the ones to apply to, with a new confirmation. Nothing is repeated by itself."},{"bullets":["While a run is in flight the page cannot be closed. If you leave it another way (the menu, closing the browser), the run stops: accounts not yet started are not changed, and what was changed is in the Audit Log.","When the current manager of an account cannot be read during a run, that account is not changed at all (not even its other fields).","Accounts the server did not get to within its time are sent again by the page; you only see the progress count."]},{"h":"Dynamic groups"},{"p":"Changing a department, a company name, an office, a country or a custom attribute for many people at once can move all of them in or out of dynamic groups whose rule reads that value, with the licenses and access those groups give. Look at the rules of your dynamic groups (People → Groups, marked \"Dynamic\") before a large run."},{"p":"Logging: every part of every account is written to the Audit Log as soon as Microsoft answers it (m365_user_update, or m365_user_update_refused for a part that was refused, not known or not sent), with old and new values, named with the sign-in name and \"(bulk edit <run>)\". Each portion of the run adds a summary entry (m365_users_bulk_update) with the instruction, the accounts and the result; when a run was stopped, the entry says so. Search \"bulk edit\" and the run code shown on the result to see the whole run. The same entries appear in each account's change history."},{"qa":[{"q":"How many accounts can I change at once?","a":"As many as you tick. They are sent a few at a time, and the page shows the progress."},{"q":"I see no boxes to tick, or no \"Edit selected…\".","a":"Your role needs \"Microsoft 365 · Accounts\" with Edit."},{"q":"The count in the confirmation is lower than what I selected.","a":"The confirmation counts the accounts that will really change. Accounts with nothing to change, or that cannot be changed, are left out; the preview lists them with the reason."},{"q":"\"This preview is not complete.\"","a":"Some accounts could not be read, so the preview does not show everything the run would do. Press \"Preview again\". If the same accounts fail again, take them out of the selection (✕ on the account at the top) and edit them one by one later."},{"q":"\"Type CHANGE and the number of accounts to confirm\" although I typed a number.","a":"The number must be exactly the number of accounts the run will change, as the page shows it."}]}]},{"title":"Custom fields and company-wide values","for":"admin","mod":"m365","body":[{"p":"Microsoft gives every account 15 spare text values, called custom attributes 1 to 15. They have numbers, not names. Administration → Onboarding Templates → \"Custom fields\" (next to \"New template\") is where you give the ones you use a name, such as Pronouns, Cost center or Desk extension. A named field then appears on every account: on the panel, and on \"Edit Microsoft 365 info\" in the section you chose. It is also on the Onboard screen (under \"+ More details\") and on every onboarding template (under \"Custom fields\"), so a new account can start with it."},{"h":"Add a field"},{"steps":["Open Administration → Onboarding Templates and click \"Custom fields\" (top right, next to \"New template\"). Since 0621-BT71 it is only there, no longer on Microsoft 365 → People.","Click \"+ Add a field\". \"Stored in\" proposes the first custom attribute nobody uses; the list shows for each attribute how many accounts already have a value (\"used by 12\" or \"empty\").","Type the Name people will see, choose \"Shown under\" (Contact information or Organization) and the \"Kind of value\": Free text, or A list of choices (write one choice per line).","Optional: a Help text, shown next to the field on the edit page.","Click Save."]},{"warn":"If you pick an attribute that already holds values, an amber note shows how many accounts and a few examples. Something else may be using it, for example an email signature or an older script. Naming it shows those values under your name; it does not change them. When in doubt, pick an empty attribute."},{"bullets":["A custom field cannot take the name of a built-in field (Department, Company, Manager…), so the Audit Log never mixes two fields up. A list can have up to 60 choices.","A saved field keeps its attribute, because the values of the accounts live there. To move it, remove the field and add a new one.","\"Shown on the edit page\" unticked hides the field without removing it.","\"Remove this field\" removes the name in ITOps. The values on the accounts stay as they are in Microsoft 365.","The table \"How the 15 custom attributes are used today\" counts the accounts with a value in each attribute and shows examples. \"Count again\" reads the directory again.","While a field is new you can still move it to another attribute; a company-wide value you typed for it moves with it.","\"Count again\" (above the usage table) reads the accounts again and refreshes that table only. What you are typing on the page stays.","The example values in the usage table are shown to the people who manage this page; others see the counts."]},{"h":"Company-wide values"},{"p":"Values that are the same for everybody: Company, Office, Office phone, Fax number, the address, Usage location, Preferred language, and any of your custom fields. They are used by one button on the edit page, \"Fill N empty fields from company-wide values\". They never replace a value an account already has, and saving this page writes nothing to any account."},{"h":"Using a custom field in an email signature"},{"p":"The values are stored on the account in Microsoft 365, not in ITOps, so other tools can read them. In CodeTwo, choose the same custom attribute number in the signature editor (it lists them as custom attributes 1 to 15). CodeTwo reads the accounts again about every 20 minutes. Values typed into CodeTwo's own attribute manager are different: they stay in CodeTwo and never reach Microsoft 365."},{"warn":"Dynamic groups: a group in Microsoft 365 can have a rule that reads a custom attribute. Once a field is named here and people fill it in, such a group takes them in or puts them out, and licenses or access given through it follow. Before you reuse an attribute, check the rules of your dynamic groups (People → Groups, marked \"Dynamic\")."},{"p":"Every save of this page is written to the Audit Log (action m365_custom_fields_save) with the fields (name, attribute, section, choices, help text, on or off) and the company-wide values before and after."},{"qa":[{"q":"Who can change this page?","a":"Roles with \"Onboarding\" and Edit. Everyone who can open Accounts can read it."},{"q":"Why at most 15 fields?","a":"That is the number of custom attributes Microsoft gives each account."},{"q":"A custom field is refused when I save an account.","a":"Custom attributes can be written for accounts that live only in the cloud. For an account copied from an on-premises directory, change the value there."}]}]},{"title":"Licensing: Licenses, Reclaim, Reconcile and Coverage","for":"admin","mod":"m365","body":[{"bullets":["\"Licenses\": one card per subscription, most used first — used / total, free seats (amber when 10% or less is left, red when full). Click a card to open the list of holders; with \"Microsoft 365 · Licenses\" you can tick people and \"Remove … from selected\".","\"Reclaim\": licensed accounts that are disabled, never signed in, or idle for 30 / 60 / 90 / 180 days. Click a row of the per-license summary to filter. Remove licenses per row (\"Remove licenses\" → \"Remove N\") or tick several and \"Reclaim selected\" (all licenses, or one license). \"Export CSV\" downloads the whole list.","\"Reconcile\": a read-only cross-check of Microsoft 365, vTiger and ITOps sign-ins, matched by email — status mismatches, Microsoft 365 only, vTiger only, reclaimable licenses, and access never used. Open a section to see who; \"Export CSV\" downloads everything.","\"Coverage\" (ITOps): active people without a license, and Business Premium holders whose device isn't enrolled in Intune."]},{"tip":"Idle detection needs Entra ID P1. Without it, Reclaim lists only disabled accounts that still hold licenses."},{"tip":"Removing licenses from several people at once (Licenses, Reclaim, Reconcile) asks you to type REMOVE first."}]},{"title":"Microsoft Entra screens: sign-in, groups, guests, devices, apps and the audit log","for":"admin","mod":"m365","body":[{"p":"Microsoft Entra ID is the identity service behind every Microsoft 365 account: who signs in, how they prove who they are, from which device, and which applications hold credentials. Its screens are where they are used: MFA, Groups and Guests under People; App secrets, Recommendations, Enterprise apps and Access & sign-in under Security; Device inventory under Devices; the audit log under Collaboration & activity."},{"bullets":["\"MFA\": who is registered for multi-factor sign-in. Starts on \"Not registered\"; \"Admins without MFA\" is the list to fix first.","\"Groups\": every group in the directory with its type, owners and member count. Click a group for its members; add or remove people and devices where Microsoft allows it — see its own topic.","\"Guests\": people from outside the organization who were invited in — who they are, whether they accepted and when they last signed in. Block or remove the ones nobody needs. See its own topic.","\"App secrets\": every app registration and when its secrets and certificates expire (expired, expiring in 30 days, no credentials). Starts on \"Needs attention\".","\"Recommendations\": Microsoft Entra's own advice for the tenant, with priority and status. Starts on the active ones; click a priority to filter."]},{"p":"MFA, App secrets and Recommendations are read-only. The ITOps tabs after the line:"},{"bullets":["\"Device inventory\": every device that signs in with a work account, company or personal, with the actions on registered devices — see its own topics.","\"Enterprise apps\": which applications hold access to the tenant, what they may do and who agreed to it. Read-only — see its own topic.","\"Audit log\": who changed what in the directory, as Microsoft recorded it. Read-only — see its own topic.","\"Access & sign-in\": MFA registration, who holds admin roles, app secrets, the sign-in methods people can use, and Conditional Access — click a rule to read in plain words who it applies to and what it requires. Changes there need \"Microsoft 365 · Tenant configuration\" (edit)."]},{"h":"\"About this screen\""},{"p":"Groups, Guests, Device inventory, Enterprise apps and Audit log — and the screens opened from them (Clean up stale devices, Pending invitations, New group) — have an \"About this screen\" button (ⓘ) in the top bar, next to the page title. Click it: a box opens over the page, in three columns:"},{"bullets":["\"What it does\": what the screen is for, in two or three lines.","\"What it needs\": the permission your role needs and the Microsoft permission the Azure app needs. A green tick means it is in place, a red cross that it is missing, an amber circle that it is optional and not in place. The Microsoft side is read from the token, so you know before you click.","\"What to expect\": what each action really does, what can be undone and what cannot, and what the screen never touches."]},{"p":"It is information only and never pushes the screen down (until build BT48 it was a box at the top of the page). A click elsewhere or Esc closes it. When something in \"What it needs\" is missing, the button shows \"1 missing\" in red without being opened."},{"qa":[{"q":"Why are Accounts and Licensing not on this page? They are Entra too.","a":"They are, but each is a job of its own that also touches Exchange and vTiger (onboarding, offboarding, reclaiming seats), so they keep their pages. Entra ID holds the Entra screens that are about sign-in, devices and applications."},{"q":"A card on Overview used to open Security and now opens Entra ID.","a":"That is expected: the screen moved, the card follows it."},{"q":"Where are the Defender alerts that were at the top of Access & sign-in?","a":"On Security → \"Alerts & actions\", with the same \"Working on it\" and \"Resolve\" buttons and the Secure Score next actions. Access & sign-in now holds only the Entra sections."}]}]},{"title":"Security and devices: alerts and incidents, Secure Score, Compliance and Device policies","for":"admin","mod":"m365","body":[{"p":"Each fact has one home. Where it shows elsewhere, it is a link (a small rounded button with →) that opens its home with the right filter."},{"bullets":["Security → \"Alerts & actions\": the one list of Microsoft Defender alerts and incidents. The counts at the top are filters: \"Open alerts\", \"Active incidents\" (who has each incident, when it last changed, how many open alerts it holds), and High, Medium and Low for the list you are looking at. \"Open in Defender ↗\" opens the item in the Microsoft portal. On an alert, \"part of an incident\" shows the incidents. \"Working on it\" and \"Resolve\" need \"Microsoft 365 · Tenant configuration\" (edit).","Security → \"Secure Score\": the score (as of date, % of the maximum) and Microsoft's next recommended actions, lowest score first. The \"Secure Score\" count on Alerts & actions opens it.","Security → \"Access & sign-in\": admin roles, sign-in methods and Conditional Access. Multifactor registration and app secrets are links here: \"5 of 7 registered\" and \"1 admin without MFA\" open People → MFA, \"1 expired\" opens Security → App secrets.","Devices → \"Compliance\": the one list of devices Intune manages. Counts filter it (compliant, non-compliant, \"Not synced in 7 days\"). \"Sync\" asks a device to check in; \"Lock\" locks a company device (type LOCK). Personal devices are marked and never locked. Both need \"Microsoft 365 · Tenant configuration\" (edit).","Devices → \"Device policies\": compliance and security policies, backup, invite to enrol. The devices are a line of links to Compliance (managed, non-compliant, not synced)."]},{"tip":"Other counts that open their list: Storage (\"Near full\"), Reconcile (\"M365 members\" opens People, \"vTiger users\" opens vTiger users), Rollout readiness (each count filters the people below), the Posture score (opens its history) and the IT Budget's Microsoft 365 tiles (seats open Licenses, reclaimable opens Reclaim)."}]},{"title":"Email: mailboxes, delegates, calendar access, distribution lists and message trace","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Email covers day-to-day mailbox requests without opening the Exchange admin center."},{"bullets":["\"Mailboxes\": every mailbox in one list (people, shared, room and equipment), with its other addresses, size, % of quota and last activity. The counts at the top are filters: each kind, \"With send-on-behalf delegates\", \"Near quota\" (90% or more) and \"People inactive 30d\". Search finds a mailbox by any of its addresses. \"Export CSV\" saves what you see.","Click a mailbox to see who may send on its behalf and who can see or change its calendar (\"Default\" is everyone in the organization). With \"Microsoft 365 · Mailboxes\" (edit) you can add or remove a delegate and give, change or take away calendar access. Taking something away asks you to confirm first; every change is written to the Audit Log, with what changed.","\"Distribution lists\": mail lists and mail-enabled security groups; click one for its members. Microsoft does not yet let apps change a list's members, so the link opens the Exchange admin center for that. Microsoft 365 groups and teams are on People → Groups.","\"Message trace\": search the last 90 days, up to 10 days at a time, by sender, recipient or words in the subject. The result shows each message's status (Delivered, Failed, Quarantined, Filtered as spam…); click a status to show only those. Every search is written to the Audit Log. From a mailbox, \"Message trace for this address\" opens it with the address filled in.","Who sees what: anyone with Microsoft 365 (view) sees the mailbox list and distribution lists. Delegates, calendar access and Message trace need \"Microsoft 365 · Mailboxes\" (view); changing them needs it with edit. Roles with \"Microsoft 365 · Tenant configuration\" received the same level of Mailboxes when this version was installed. Any attempt without the permission is refused and written to the Audit Log."]},{"p":"One-time setup in Microsoft (an administrator of the tenant):"},{"bullets":["Mailboxes, delegates and calendar access use Microsoft's Exchange Admin API, which is in preview. In Entra → App registrations → your app → API permissions → Add → \"APIs my organization uses\" → Office 365 Exchange Online → Application → Exchange.ManageAsAppV2 → Grant admin consent. Then in the Exchange admin center → Roles → Admin roles → Recipient Management → Assigned, add the app.","Message trace needs the Microsoft Graph application permission ExchangeMessageTrace.Read.All with admin consent.","Until this is done the screens say what is missing instead of failing, and \"Mailboxes\" falls back to the usage report (size and activity). Home → Diagnose tests both."]},{"tip":"The app can only run the Exchange commands it needs (read mailboxes, change send-on-behalf delegates, read and change calendar permissions, read list members). It cannot delete or create mailboxes."}]},{"title":"Devices: restart, scan, retire and wipe with a second person's approval, apps, configuration and update rings","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Devices handles the day-to-day Intune work without opening the Intune admin center."},{"bullets":["Compliance → \"More\" on a device. \"Now\": Restart (type RESTART), Defender quick scan and Defender full scan (Windows). These are sent at once and need \"Microsoft 365 · Tenant configuration\" (edit).","\"With a second person's approval\": Retire (removes the organization's apps, data, email profiles and settings and takes the device out of Intune; the person's own files stay), Wipe (factory reset; you can keep the enrollment and, on Windows, the person's files) and Fresh start (reinstalls Windows; you can keep the person's files). Say why and type the device name; the request then waits.","Devices → \"Wipe & retire\": the requests. Someone else with \"Microsoft 365 · Retire and wipe devices\" approves (typing the device name) or denies (saying why). Nobody approves their own request. Only an approved request is sent to Intune. A request nobody answers lapses after 24 hours. The person who asked can withdraw it while it waits. The people who can approve get a bell; the person who asked gets one when it is approved, denied or could not be sent.","Before sending, the device is read again: if Intune no longer has it, or it now has another name, nothing is sent and the request says why. \"check in Intune\" on a sent request shows what the device reported (pending, done, failed).","Personal devices: only Retire is possible. Restart, scans, lock, wipe and fresh start are never sent to a device the organization does not own. A device whose owner Intune does not know is treated the same way until it is set to Corporate in Intune.","\"Apps\": the apps Intune installs (required) or offers in Company Portal (available), and who gets each (groups, all users, all devices; an exclusion is struck through). Counts filter: required, available only, not assigned, and per platform. Switch to \"Software found on devices\" for what is actually installed, most widespread first; click a program for its versions and which devices have each.","\"Configuration\": the configuration profiles (including settings-catalog profiles), who gets each, and on how many devices it worked, failed or conflicts. Counts filter: with errors, with conflicts, not assigned.","\"Update rings\": how long each Windows ring waits for quality (monthly) and feature updates, the install deadline, and whether it is paused. \"Pause\" stops a ring taking those updates for up to 35 days, when an update causes trouble; \"Resume\" starts them again. This needs \"Microsoft 365 · Tenant configuration\" (edit) and is written to the Audit Log.","Changing apps, profiles and rings themselves stays in the Intune admin center (\"Open in Intune ↗\")."]},{"p":"One-time setup in Microsoft (Graph application permissions with admin consent):"},{"bullets":["DeviceManagementManagedDevices.PrivilegedOperations.All: restart, scans, retire, wipe, fresh start.","DeviceManagementApps.Read.All: Apps. DeviceManagementManagedDevices.Read.All: software found. DeviceManagementConfiguration.Read.All: Configuration and Update rings; DeviceManagementConfiguration.ReadWrite.All to pause and resume a ring.","Home → Diagnose tests the reads. Until a permission is granted, the screen names it instead of failing."]},{"tip":"Give \"Microsoft 365 · Retire and wipe devices\" (Settings → Roles) to at least two people. It is not given to any role automatically. An organization with one administrator: a Super Admin can switch the second person off per action in Settings → Approvals; the action is then sent as soon as the one person confirms (reason and typed name still asked), and the list shows it as \"sent, no second person\". Every request, approval, denial, withdrawal, lapse, refusal and change of the setting is in the Audit Log."}]},{"title":"Groups: owners, members, new groups and what can be changed","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → People → \"Groups\" lists every group in the directory. Use it to see who is in a group before you rely on it for access, licenses or policies, to add or remove members and owners without opening a person's account, and to create a new security group."},{"h":"Reading the list"},{"bullets":["Type: \"Microsoft 365\" (a mailbox, files and often a team — marked \"Team\"), \"Security\" (used for access, licenses and policies), \"Distribution list\" and \"Mail-enabled security\".","Under the type: \"Dynamic membership\" (a rule decides who is in), \"Synced from on-premises\", \"Can hold admin roles\".","Members and Owners: how many. \"—\" means Microsoft did not return the number this time.","Flags: \"No owner\" on a Microsoft 365 group or team that nobody owns, and \"Empty\" on a group without members.","Tiles filter the list (Microsoft 365, Security, No owner, Empty); the chips filter mail lists, dynamic and synced groups. \"Export CSV\" downloads the rows you see."]},{"h":"Members"},{"steps":["Click a group. Owners are on the left, members on the right — people, devices and groups inside the group under their own headings. \"disabled\" marks an account that is blocked from signing in but still in the group; \"guest\" marks an external person.","\"+ Add person\": search by name or email and click the person.","\"+ Add device\": search the Device inventory and click the device. This is how a computer is put in the company-PC group that the device policies are assigned to.","\"remove\" next to a member takes them out, after a confirmation that says what they lose."]},{"h":"Owners"},{"steps":["Click a group. Its owners are on the left.","\"+ Add owner\": search by name or email and click the person. Owners must be people from the organization who can sign in; guests and blocked accounts are refused.","For a Microsoft 365 group or team, \"Also add as a member\" is ticked: an owner who is not a member cannot work in the team. Untick it if you only want them to manage it.","\"remove\" next to an owner takes the ownership away, after a confirmation. They stay a member if they were one."]},{"bullets":["The last owner of a Microsoft 365 group or team cannot be removed: Microsoft does not allow it. Add the new owner first, then remove the old one.","Owners can be changed for cloud security groups and Microsoft 365 groups, dynamic ones included (the rule decides the members, not the owners).","In Microsoft Teams a change of owner can take up to 2 hours to appear.","When the buttons are missing, the line under the owners says why: the kind of group, your role, or the Microsoft permission Group.ReadWrite.All."]},{"h":"Creating a group"},{"steps":["Click \"+ New group\" at the top right. A full page opens.","Type a name (3 to 120 characters) and, if you like, a description of what the group is for.","Under \"Owners\", search for a person and click them. At least one owner, up to five.","Click \"Create group\". The page closes and the new group is open in the list, ready for \"+ Add person\" or \"+ Add device\"."]},{"bullets":["What you get is a security group in the cloud with members you choose yourself: the kind used to assign licenses, Intune policies and access to apps or SharePoint sites.","It has no mailbox, no team and no shared files. For those, create a team in Microsoft Teams.","The group gives nothing to anyone by itself. It starts to matter when you assign something to it.","A name that another group already uses is refused, so two groups are never mixed up."]},{"h":"What cannot be changed here, and where to do it"},{"bullets":["Members of dynamic groups: change the rule in the Entra admin center. The rule is shown when you open the group.","Groups synced from on-premises: change members and owners in Active Directory.","Distribution lists and mail-enabled security groups: the Exchange admin center. Microsoft does not let an application change them.","Groups that can hold admin roles: the Entra admin center.","Deleting a group: the Entra admin center. ITOps never deletes groups, because deleting a Microsoft 365 group also removes its team, mailbox and files."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\" to see groups; \"Microsoft 365 · Groups\" to change members and owners and to create groups (the same permission as on a person's account).","Azure app, members: GroupMember.ReadWrite.All — the permission that adding people to groups on Microsoft 365 → People already uses. With only Group.Read.All the list works, read-only.","Azure app, owners and new groups: Group.ReadWrite.All (Application, admin consent). It is optional: without it \"+ Add owner\", \"remove\" on owners and \"+ New group\" are hidden, the screen names the permission, and everything else works. After granting it, click \"Refresh token & re-test\" on Home → Diagnose.","The list is kept for 10 minutes (\"· cached\"); any change made here refreshes it. Every change is in the Audit Log."]},{"qa":[{"q":"A group I know has members shows \"—\".","a":"Microsoft did not answer the count. Open the group to see its members, or click Refresh."},{"q":"Applications that are members are not listed.","a":"Microsoft does not return applications (service principals) as group members in this version of its interface."},{"q":"What should I do about \"No owner\"?","a":"Open the group and click \"+ Add owner\". Without an owner, nobody can approve members, renew the group or clean it up. If the button is missing, the Azure app lacks Group.ReadWrite.All: grant it, or add the owner in the Teams or Entra admin center."},{"q":"I created a group but it is not in the list.","a":"Microsoft can take a few seconds to show a new group. Click \"Refresh\". The green line above the list keeps the name you gave it."},{"q":"Can I create a Microsoft 365 group or a team here?","a":"No. ITOps creates security groups only. A Microsoft 365 group comes with a mailbox, a site and usually a team, and is best created from Microsoft Teams by the person who will own it."}]}]},{"title":"Guests: external accounts, pending invitations and clean-up","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → People → \"Guests\" lists every guest account: people from outside the organization who were invited into a team, a SharePoint site or an app. Guests are easy to forget — nobody offboards them — so this is the place to check them every few months."},{"h":"Reading the list"},{"bullets":["\"From\": the company when Entra knows it, and the domain of the person's address. The chips above the list filter by the most common domains.","\"Invitation\": \"Accepted\", or \"Pending\" when the person never clicked the invitation — a pending guest cannot use anything yet.","\"Last sign-in\": the last time the guest signed in, or \"never\". \"—\" means Microsoft does not provide the dates (see \"What it needs\").","Flags: \"Invitation pending\", \"Pending 30+ days\" (invited over a month ago and never accepted), \"Not used 90 days\" (accepted but no sign-in for 90 days, or never), \"Sign-in blocked\".","The four tiles filter the list. \"Export CSV\" downloads the rows you see."]},{"h":"Blocking, re-inviting and removing"},{"steps":["Click a guest. The details show the address, the invitation, the account name in Entra and what each flag means.","\"Block sign-in\" stops the guest from signing in but keeps the account and its memberships; \"Restore sign-in\" undoes it. Use it when you are not sure the guest is finished.","\"Resend invitation\" appears on a guest who has not accepted yet. Microsoft emails a new invitation to the guest's address; nothing else about the account changes. The button is off while the guest's sign-in is blocked: restore sign-in first.","\"Remove guest…\": type the guest's email address and click \"Remove guest\". The guest loses access to every team, site and app at once."]},{"bullets":["A removed guest stays under \"Deleted users\" in the Entra admin center for 30 days and can be restored there. After that the person has to be invited again.","Files and messages the guest left in teams and sites stay where they are.","Only guests can be removed here. A staff account is never deleted from this screen: staff are offboarded from Accounts → Offboard.","To see or change a guest's groups, open People → Groups and the group."]},{"h":"Pending invitations: several at once"},{"steps":["Click \"Pending invitations…\" at the top right (the number is how many are waiting).","The list shows every guest who has not accepted, oldest first, with the days waited. Guests waiting more than 30 days are ticked; change the ticks as you like.","\"Resend invitation to N guests\" sends the invitation again to the ticked guests, after a confirmation.","To remove instead: type REMOVE and the number of ticked guests (for example REMOVE 3) and click \"Remove N guests\".","The result lists every guest with what happened. \"← Back to all guests\" returns to the full list."]},{"bullets":["Only guests whose invitation is still pending are handled. A guest who accepted in the meantime is skipped; a staff account can never be removed this way.","A ticked guest whose sign-in is blocked is not re-invited; the screen says how many.","A resent invitation keeps the guest \"pending\" until the person accepts. Refresh later to see who did."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\" to see guests; \"Microsoft 365 · Accounts\" to block, re-invite and remove them.","Azure app: nothing new. The list uses User.Read.All; blocking, removing and resending invitations use User.ReadWrite.All — both already there if onboarding and offboarding work. (User.Invite.All alone is enough for resending.)","Resending also needs guest invitations to be allowed in your tenant: Entra admin center → External Identities → External collaboration settings. If Microsoft refuses, the message says so.","Last sign-in dates need AuditLog.Read.All and Entra ID P1 (part of Business Premium). Without them the guests are still listed, the dates show \"—\", and nobody is flagged \"Not used 90 days\".","The list is kept for 10 minutes (\"· cached\"); blocking or removing a guest refreshes it. Every change is in the Audit Log."]},{"qa":[{"q":"How do I invite a new guest?","a":"Not from ITOps. People invite guests from Teams or SharePoint, or an administrator from the Entra admin center. ITOps resends invitations that were never accepted and removes guests nobody needs."},{"q":"After \"Resend invitation\" the message says Microsoft created a new guest account.","a":"Rarely, Microsoft does not match the address to the existing guest and makes a second account. Refresh the list: you will see two guests with that address. Remove the older one that stays pending."},{"q":"A guest is \"Not used 90 days\" but I know they work with us.","a":"They may only receive email from the team, which is not a sign-in. Ask the team's owner before removing; blocking first is the safe step."},{"q":"Why does a guest show a strange account name with #EXT#?","a":"That is how Entra names guest accounts: the person's own address with \"_\" instead of \"@\", followed by #EXT# and your tenant. The \"Email\" field is the address they sign in with."}]}]},{"title":"Device inventory: every computer that signs in","for":"admin","body":[{"p":"Microsoft 365 → Devices → \"Device inventory\" lists every device that signs in with a work account — company computers and personal ones — without installing anything on them. It is built from two things Microsoft already records — the Entra device list and the Entra sign-in log — plus what ITOps itself sees when a person opens it (in Teams or in a browser). Reading it changes nothing; a registered device can also be disabled, removed or looked up for its recovery key from its row — see \"Device actions and recovery keys\"."},{"h":"What each row tells you"},{"bullets":["Device and person: the device name and model when Entra knows them, and the person who uses it. \"+2 more\" means other people have signed in on the same device.","OS: the operating system, with its exact version when the device is registered in Entra.","Type: \"Company\" (joined to the organization, or marked company-owned in Intune), \"Personal\" (a personal device the person registered with their work account), \"Unregistered\" (seen only in the sign-in log) or \"Unknown\" (Entra does not say).","Intune: \"Managed\" and whether it is compliant, or \"Not managed\".","Last seen: the latest sign-in or activity, with the city it came from. Click a row for the details: everyone seen on it, the app and browser of the last sign-in, the IP address, when it was first recorded and what each flag means."]},{"h":"Flags"},{"bullets":["\"Not managed\": Intune does not manage this computer, so its disk encryption, firewall and updates are not known. Normal for personal computers.","\"OS out of support\": the operating system no longer gets security updates (Windows 10 or older, macOS 13 or older).","\"Not seen 90 days\": probably retired, lost or replaced.","\"Owner disabled\": the person's Microsoft 365 account is disabled but the device is still listed. Check it after an offboarding.","\"Removed from Entra\" and \"Device disabled\": the device was deleted or disabled in Entra."]},{"h":"Using the screen"},{"steps":["Open the tab. The first time, ITOps reads Entra and up to 30 days of sign-ins; this can take a minute.","Click a tile (Company, Personal, Unregistered, Unknown) or a flag to filter. \"Computers\", \"Phones & tablets\" and \"All\" choose the kind of device; the screen starts on Computers.","Switch to \"By person\" to see what each person uses — for example who works from a personal or unregistered computer.","Search by device, person, operating system or city. \"Export CSV\" downloads the rows you are looking at.","\"Sync now\" reads Microsoft again (at most once a minute). The scheduled job also syncs once a day.","\"Clean up stale devices…\" at the top opens the bulk clean-up: disable devices nobody uses, then remove them later. See its own topic."]},{"h":"Good to know"},{"bullets":["An \"Unregistered\" row comes from the sign-in log. It groups one person's sign-ins from one operating system, so it can stand for more than one physical computer.","For an \"Unregistered\" row, \"Last seen\" is the last time the person had to sign in on it (password or MFA). Apps that stay signed in do not add new entries, so the date can be weeks old on a computer that is used every day. Opening ITOps on the device (in Teams or a browser) also counts as \"seen\", and the row then shows \"in Teams\" or \"in ITOps\" under the date. The details show \"Person last active\", and the row is only flagged \"Not seen 90 days\" — or removed after 180 days — when the person has not been active either.","The sign-in log does not tell Windows 10 from Windows 11. For a device that is not registered, the exact version (and \"OS out of support\") is known once its owner has opened ITOps on it, in Teams or in a browser.","Microsoft keeps sign-ins for 30 days. ITOps keeps what it has read, so the history builds up from the day you install this build. Unregistered and removed devices leave the list after 180 days without activity.","Disk encryption, firewall and update status are only known for computers Intune manages — see Devices → \"Compliance\".","Microsoft 365 → Home has a \"Personal computers\" card, and \"Needs attention\" lists devices whose owner is disabled, computers out of support and devices not seen for 90 days.","Access ends with the account: when a person is offboarded their devices stop signing in, and the row is flagged \"Owner disabled\".","What ITOps records itself comes from the browser: operating system, version when the browser gives it (Chromium browsers), and the browser or Teams client. It is an indication, not proof, and it can be switched off under Integrations → Microsoft Teams → \"Device inventory\". If a person has exactly one registered device with that operating system, the report is attached to it; otherwise to their \"Unregistered\" row."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\".","Azure app: Device.Read.All for the Entra device list, and AuditLog.Read.All for the sign-in log (the sign-in log also needs Entra ID P1, which is part of Microsoft 365 Business Premium). With only one of the two, the screen shows what it can and names what is missing.","To act on devices: \"Microsoft 365 · Entra devices\" and, for recovery keys, \"Microsoft 365 · Recovery keys\" — see the next topic."]},{"qa":[{"q":"A person uses a personal PC but I only see an \"Unregistered\" row.","a":"They sign in through the browser or chose \"sign in to this app only\", so the PC never registered in Entra. The row still shows the operating system, the last sign-in and where it came from."},{"q":"The same person has an Unregistered row and a registered device with the same operating system.","a":"Some of their sign-ins did not carry the device identity (for example a private browser window). It can be the same computer."},{"q":"Can I lock or wipe a device from here?","a":"Not lock or wipe: those are Intune actions, on Devices → \"Compliance\", for company devices only. From the inventory you can disable or remove the device's registration in Entra and look up its BitLocker recovery key — see \"Device actions and recovery keys\". Nothing here ever erases a computer."},{"q":"The location looks wrong.","a":"It is Microsoft's estimate from the IP address. VPNs and mobile networks often show another city."}]}]},{"title":"Device actions and recovery keys (BitLocker, LAPS)","for":"admin","mod":"m365","body":[{"p":"In Devices → \"Device inventory\", click a device that is registered in Entra. Under its details, \"Actions in Entra\" shows what can be done with it — and, in words, why something cannot. ITOps reads the device from Entra again at that moment, so the buttons match its real state, not yesterday's sync."},{"h":"Disable and enable"},{"bullets":["\"Disable\" stops the device from using its identity with Microsoft 365: single sign-on ends and sign-in rules that ask for a known device block it. Nothing on the computer is erased, and \"Enable\" brings it back.","Offered for Windows devices only. Microsoft does not let an application disable a Mac, a phone or a Linux computer; for those the screen says so and you use the Entra admin center.","Not offered for computers synced from an on-premises Active Directory (\"Hybrid joined\"): disable them on-premises, or the next sync undoes it."]},{"h":"Remove from Entra"},{"steps":["Disable the device first and wait until you are sure nobody misses it. This is Microsoft's own advice for cleaning up stale devices, and ITOps enforces it for Windows: \"Remove from Entra…\" appears only once the device is disabled.","Click \"Remove from Entra…\". Read the three points: the registration cannot be restored, the BitLocker recovery keys and local administrator password Entra holds for it are deleted with it, and nothing on the computer itself is erased.","Type the device name and click \"Remove from Entra\". The row is flagged \"Removed from Entra\" at once and leaves the list later."]},{"bullets":["A Mac, phone or Linux device cannot be disabled by an application, so it can be removed directly — but only when it has not been seen for 90 days or its owner's account is disabled.","Never offered while Intune manages the device (retire or delete it in Intune first, on Devices → \"Compliance\"), while Windows Autopilot holds it, or for hybrid computers.","Rows that come from the sign-in log (\"Unregistered\") have nothing to disable or remove: the device was never registered."]},{"h":"Recovery key and local administrator password"},{"steps":["Click \"Recovery key & admin password\". ITOps lists the BitLocker recovery keys Entra holds for the computer — the drive and the date, not the key.","Type why you need it (a ticket number or a few words).","Click \"Show key\" on the right drive, or \"Show password\" for the local administrator password that Windows LAPS backed up. Compare the \"Key ID\" with the one on the person's BitLocker screen (the first 8 characters are enough).","Read it to the person or click \"Copy\". \"Hide\" removes it from the page; it also hides itself after two minutes."]},{"bullets":["Every view is recorded: ITOps's Audit Log keeps who asked, for which device, which key and the reason — never the key or the password. Microsoft records the read in the Entra audit log as well.","ITOps does not store keys or passwords, and the browser is told not to keep the answer.","BitLocker keys exist only for Windows computers whose key was saved to Entra. Local administrator passwords exist only for computers joined to the organization with Windows LAPS set up; a personal (registered) PC has none.","After a recovery key has been used, Windows can make a new one by itself when Intune's BitLocker policy has recovery-password rotation switched on. Until then the key you read stays valid, so treat it as a secret."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\", plus \"Microsoft 365 · Entra devices\" to disable, enable and remove, and \"Microsoft 365 · Recovery keys\" to see keys and passwords. Neither is given to any role automatically — not even to roles with \"Tenant configuration\". Super Admins have both.","Azure app (Application permissions with admin consent): Device.ReadWrite.All to disable, enable and remove; BitlockerKey.Read.All for recovery keys; DeviceLocalCredential.Read.All for local administrator passwords. Add only the ones you will use.","If \"Disable\" is refused although Device.ReadWrite.All is granted: in the Entra admin center → Roles and administrators → \"Cloud Device Administrator\", add the ITOps enterprise application as a member. Microsoft requires that role for enabling and disabling devices."]},{"qa":[{"q":"Why is \"Remove\" missing for a computer I want to delete?","a":"The line under the buttons says why: it is still enabled (disable it first), Intune still manages it, Autopilot holds it, or it is synced from on-premises."},{"q":"I removed a device by mistake.","a":"An Entra device cannot be restored. Register or join the computer again (Settings → Accounts → Access work or school). Its old recovery keys are gone, which is why ITOps asks you to look them up first if they may still be needed."},{"q":"It says \"Entra holds no recovery key for this computer\".","a":"The drive is not encrypted, or the key was saved to a personal Microsoft account or printed instead. Intune's BitLocker policy (Devices → Device policies → \"Seed device security\") makes Windows save it to Entra."},{"q":"\"No local administrator password is stored for this computer.\"","a":"Windows LAPS is not set up for it, or it has not backed up a password yet. It needs a LAPS policy in Intune and \"Enable Microsoft Entra Local Administrator Password Solution\" in Entra → Devices → Device settings."},{"q":"Who looked at a recovery key last month?","a":"Logs & Integrations → Audit Log, search \"bitlocker\" or \"laps\". Each entry has the person, the device, the key ID and the reason they typed."}]}]},{"title":"Cleaning up stale devices: disable, wait, remove","for":"admin","mod":"m365","body":[{"p":"Over time the Entra device list fills with computers and phones nobody uses any more: replaced laptops, a phone someone traded in, the PC of a person who left. Devices → \"Device inventory\" → \"Clean up stale devices…\" retires them several at a time, in the two steps Microsoft advises: disable first, remove later."},{"h":"Step 1 — Disable"},{"steps":["Open the Device inventory and click \"Sync now\" if the last sync is old. The clean-up works from that list.","Click \"Clean up stale devices…\".","Step 1 lists Windows devices that are registered, still enabled, not managed by Intune and not seen for 90 days. All are ticked; untick any you want to leave alone.","Click \"Disable N devices\" and confirm."]},{"bullets":["A disabled device can no longer sign in with its device identity. Nothing is deleted and nothing on the computer changes.","It is reversible: open the device's row in the inventory and click \"Enable\".","If someone still uses one of them, they will tell you — that is the reason for waiting before step 2."]},{"h":"Step 2 — Remove"},{"steps":["Come back after about 30 days.","Step 2 lists Windows devices that are disabled and not seen for 90 days, and phones, tablets and Macs not seen for 90 days or whose owner's account is disabled.","Read \"Why it is listed\". A Windows device is ticked only once it has been disabled from ITOps for 30 days; the line says who disabled it and when. Devices disabled somewhere else show \"date not known\" and are left unticked.","Tick or untick as needed, type REMOVE and the number of ticked devices (for example REMOVE 4), and click \"Remove N devices\"."]},{"warn":"Removing cannot be undone from ITOps. For a computer joined to the organization — marked \"Recovery keys go with it\" — the BitLocker recovery keys and the local administrator password Entra holds are deleted with it. If the disk may still be needed, look the key up first (the device's row → \"Recovery key & admin password\")."},{"h":"What ITOps checks before it changes anything"},{"bullets":["Each device is read from Microsoft again just before it is changed. One that was used since the last sync is skipped.","Never touched: computers managed by Intune (retire them on Devices → Compliance), registered with Windows Autopilot, or joined to an on-premises domain. The line under step 2 says how many stale devices were left out and where to handle them.","Phones, tablets and Macs go straight to step 2 because Microsoft does not let an application disable them.","Rows that only come from the sign-in log (\"Unregistered\") are not in Entra, so there is nothing to remove; they leave the inventory by themselves.","After each step the result lists every device: Disabled or Removed, Skipped with the reason, or Failed with Microsoft's answer. If Microsoft refuses the first device for lack of permission, the rest is not attempted."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · Entra devices\" to disable and remove. With \"Microsoft 365 · View\" only, both lists are shown read-only.","Azure app: Device.ReadWrite.All (Application, admin consent). The \"About this screen\" button (ⓘ in the top bar) shows whether the token carries it.","If Microsoft refuses to disable although the permission is there, give the app's enterprise application the Entra role \"Cloud Device Administrator\" (Entra admin center → Roles and administrators).","Every device changed is written to the Audit Log, one entry per device, marked as part of a bulk action."]},{"qa":[{"q":"Why is a device I disabled yesterday not ticked in step 2?","a":"The waiting time is not over. It is listed with \"Waiting time not over: 30 days are advised\". You can tick it yourself if you are sure nobody needs it."},{"q":"A device was skipped with \"seen in the last 90 days\".","a":"Someone used it after the last sync, so it is no longer stale. Sync the inventory and it will leave the list."},{"q":"Can I change the 90 and 30 days?","a":"Not in this version. 90 days is the same limit as the \"Not seen 90 days\" flag in the inventory. A single device can always be disabled or removed from its own row, whatever its dates."},{"q":"I removed a device that was still in use.","a":"An Entra device cannot be restored. The person registers or joins the computer again (Settings → Accounts → Access work or school). This is why step 1 exists: disable first and wait."}]}]},{"title":"Enterprise apps: which applications hold access","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Security → \"Enterprise apps\" answers a question that is otherwise hard to see in one place: which applications can reach your tenant's data, what exactly each one may do, and who agreed to it. It is read-only."},{"h":"Two kinds of access"},{"bullets":["\"Without a person\" (application permissions): the app works by itself, at any time, for the whole tenant — for example a backup tool that reads every mailbox. Only an administrator can grant these.","\"On behalf of people\" (delegated permissions): the app acts as the person who is signed in, limited to what that person can reach. Either an administrator agreed for everyone (\"admin consent\"), or people agreed one by one for themselves.","Click an app to see every permission, the Microsoft service it belongs to, and for delegated ones whether it is for everyone or how many people consented."]},{"h":"Flags — what to look at first"},{"bullets":["\"High privilege\": the app may read or change mail, files, accounts or the directory without anyone signing in. Expected for tools you chose (ITOps itself is one); question any you do not recognise.","\"User consent · sensitive\": one or more people — not an administrator — let the app read their mail, files or contacts. This is how consent phishing works: a fake \"sign in to view the document\" page asks for these permissions. Check the app with the people who consented.","\"User consent\": people agreed by themselves, but only to basics such as signing in and their own profile.","\"Unverified publisher\": a third-party app whose publisher Microsoft has not verified.","\"Sign-in disabled\": nobody can sign in to it, yet its permissions are still granted."]},{"h":"What is listed"},{"bullets":["Every application that was granted a permission in your tenant, plus third-party applications and your own that were added to it.","Microsoft's own background services that hold no grant are left out: every tenant has hundreds of them.","\"From\" says whose application it is: your organization, Microsoft, or a third party.","Application permissions are read for Microsoft Graph, Exchange Online and SharePoint — the services that hold mail, files and the directory.","Permissions marked \"sensitive\" are the ones on ITOps's own watch list (mail, files, accounts, directory, roles, device secrets). It is a guide for where to look, not a verdict."]},{"h":"Taking access away"},{"p":"ITOps does not change applications. Use \"Open in the Entra admin center ↗\" on the app: \"Permissions\" to review and revoke what was granted, \"Properties\" → \"Enabled for users to sign in\" = No to stop it at once, or delete the application. To stop people from consenting by themselves: Entra admin center → Enterprise applications → Consent and permissions → User consent settings."},{"p":"Why ITOps does not do it for you: stopping an application or revoking its access needs Microsoft permissions (Application.ReadWrite.All, AppRoleAssignment.ReadWrite.All) that would let ITOps grant itself any access in the tenant. A web application should not hold those, so these few clicks stay in Microsoft's own admin center."},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\".","Azure app: Application.Read.All (already used by \"App secrets\") for the applications and their application permissions; Directory.Read.All for the delegated permissions. Without Directory.Read.All the screen still works and says that the delegated part is missing.","The list is kept for 10 minutes; \"Refresh\" reads Microsoft again."]},{"qa":[{"q":"ITOps itself is flagged \"High privilege\".","a":"Correct: it holds the permissions you granted so it can onboard and offboard people, read reports and so on. The list in the details is exactly what its Azure app may do — the place to check when you remove a permission you no longer use."},{"q":"An app I removed is still listed.","a":"The list is cached for 10 minutes. Click Refresh."},{"q":"Who are the people who consented?","a":"ITOps shows how many, not who. The Entra admin center lists them under the app → Permissions → \"User consent\"."}]}]},{"title":"Entra audit log: who changed what in the directory","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Collaboration & activity → \"Audit log\" shows Microsoft's own record of changes in the directory: accounts created, blocked or deleted, password resets, group members added or removed, devices, applications and their permissions, admin roles and policies. It is read-only. Do not confuse it with ITOps's own Audit Log (Logs & Integrations), which records what people did inside ITOps."},{"h":"Using it"},{"steps":["Choose the period: 24 hours (the screen opens there), 7 days or 30 days.","Click a category chip (for example UserManagement, GroupManagement, ApplicationManagement, Policy) to ask Microsoft for that category only. The chip with ✕ removes the filter.","\"Failed only\" keeps the entries that did not succeed. Search matches the activity, the person, the target and the IP address.","Click an entry to see what changed — the value before and after — plus the reason, the service that recorded it and the IP address.","\"Export CSV\" downloads the entries you see."]},{"h":"Good to know"},{"bullets":["\"By\" is the person who made the change, or the application when a program did it (marked \"app\"). Changes made from ITOps appear under the name of its application; ITOps's own Audit Log has the name of the person who clicked.","Microsoft keeps this log for 7 days on Entra ID Free and 30 days with Entra ID P1 (part of Business Premium).","At most the newest 1,000 entries of 24 hours, or 2,000 of a longer period, are read. When that limit is reached the screen says so: choose a category or a shorter period.","Sign-ins are not here: see a person's recent sign-ins on Accounts, and devices on Device inventory.","Answers are kept for 5 minutes; \"Refresh\" reads Microsoft again."]},{"h":"What it needs"},{"bullets":["Your role: \"Microsoft 365 · View\".","Azure app: AuditLog.Read.All — the same permission the MFA report and the Device inventory use."]},{"qa":[{"q":"Who disabled this account, and when?","a":"Choose 7 or 30 days, click UserManagement, search the person's name. \"Update user\" with AccountEnabled true → false is the entry."},{"q":"Did someone add an app or grant it permissions?","a":"Category ApplicationManagement: look for \"Add service principal\", \"Consent to application\" and \"Add app role assignment to service principal\". Then check the app on Enterprise apps."}]}]},{"title":"Service health, mailboxes, Teams, storage and Copilot","for":"admin","mod":"m365","body":[{"bullets":["\"Service health\": services that are not operational, open issues (tick \"show resolved\" for the rest) and Message center posts (tick \"action / major only\" for the ones with a deadline or a major change).","\"Mailboxes\": size, % of quota (amber at 75%, red at 90%), items and last activity. Tiles filter to \"Near quota\" or \"Inactive 30d\".","\"Teams\": messages, calls and meetings per person over 30 days; tiles filter active / inactive.","\"Storage\": OneDrive accounts and SharePoint sites, biggest first, with \"near full only\".","\"Copilot\": licensed vs active vs idle, the daily active-user trend, which Copilot apps are used, and per-person last activity. The period is the one Microsoft answers for: Microsoft's newer Copilot reports cover 28 days, so the page then says \"over the last 28 days\" and \"Active 28d\"."]},{"p":"All five read Microsoft's usage reports (Reports.Read.All; Service health needs ServiceHealth.Read.All and ServiceMessage.Read.All). Microsoft's reports lag by one to two days."},{"qa":[{"q":"Copilot showed \"The period value 'RL30' is not supported … Use 'RL28' instead\" or \"Invalid period value specified: RL28\".","a":"That was Microsoft changing its Copilot reports: it now reports 28 days. From build BT56 the app reads Microsoft's message, asks for the period it accepts (D28) and remembers it, so the page loads and says \"over the last 28 days\". Press \"Refresh\" on the page if it still shows the old message."}]}]},{"title":"Microsoft 365 permissions: who can do what","for":"admin","mod":["roles","users"],"body":[{"p":"The Microsoft 365 area is split by kind of change, so a role can read everything but change only what it should. Set them under Administration → Roles & Permissions → \"Microsoft 365\"."},{"bullets":["Microsoft 365 · View — every Microsoft 365 screen, read-only, including Guests, Enterprise apps and the Entra audit log (m365.view).","Microsoft 365 · Accounts — edit contact information, manager and custom fields of one account or of several at once; Onboard, Offboard, block and restore sign-in; also block, re-invite and remove guests on People → Guests, one at a time or under \"Pending invitations\" (m365.users).","Microsoft 365 · Credentials — reset password, reset MFA, revoke sessions, sign-in methods, Temporary access pass (m365.credentials).","Microsoft 365 · Licenses — assign, remove and reclaim licenses (m365.licenses).","Microsoft 365 · Groups — add people and devices to groups and remove them: on a person, on People → Groups, and the template groups at onboarding. Also change group owners and create security groups on People → Groups (m365.groups).","Microsoft 365 · Directory roles — assign and remove Entra admin roles (m365.roles). Not given to any role automatically.","Microsoft 365 · Entra devices — disable, enable and remove devices in Entra from the Device inventory, one at a time or with \"Clean up stale devices\". Not given to any role automatically.","Microsoft 365 · Recovery keys — see BitLocker recovery keys and local administrator (LAPS) passwords; each view asks for a reason and is recorded. Not given to any role automatically.","Provisioning · Onboard to vTiger / Offboard from vTiger — create the vTiger user; reassign records, deactivate and verify (provision.onboard / provision.offboard). These are needed for the vTiger steps of any onboarding or offboarding, also in History and in a template; a vTiger admin is handled by a Super Admin only.","Onboarding templates & history — view the History tab and the templates; edit = create and change onboarding templates, work the steps of a process and the vTiger provisioning connection. Without \"All records\" a person sees the processes they started and those of their own department.","Microsoft 365 · Tenant configuration — the ITOps extras: Rollout ticks and emails, device and app-protection policies, Conditional Access, email security.","Onboarding · Edit — also names the custom fields and keeps the company-wide values (Onboarding Templates → \"Custom fields\"). Everyone with Microsoft 365 · View can read them.","Company systems (under Administration in the grid, with the Settings permissions) — View: each person's accounts in the other systems, shown on their account under Microsoft 365 → People (the block \"Systems\" and the count in the list), and \"Needs attention\" under Microsoft 365 → People. A role that has only this permission gets \"Settings\" in its menu with that one tab. Edit: record, correct and close accounts. Not given to any role automatically. The steps inside an onboarding or offboarding are answered by whoever runs it; which systems are in use is set by a Super Admin or a role with Integrations · Edit."]},{"p":"Upgrading keeps everyone's access: roles that had \"M365 Admin\" (edit) get Accounts, Credentials, Licenses and Groups; roles that could edit onboarding get the two Provisioning permissions. Nobody gets Directory roles, Entra devices or Recovery keys automatically: tick them for the people who need them. Super Admins always have them."},{"p":"Whatever the role: actions on admin accounts and the high-risk directory roles are Super Admin only (see \"Accounts: managing one person\")."}]},{"title":"API keys and webhooks","for":"admin","mod":"integrations","body":[{"p":"Logs & Integrations → Integrations connects other systems to ITOps: API keys let them send data in, and webhooks tell them when something changes."},{"h":"Create an API key"},{"steps":["Go to Logs & Integrations → Integrations → \"API keys\" → \"+ New key\".","Give it a name for the system (e.g. HR system) and an optional expiry date.","For each module the system needs, choose \"Read only\", \"Read + write\" or \"Read + write + delete\". Leave the rest at \"No access\".","Click \"Create key\" and copy the key. It is shown only once."]},{"bullets":["A key can never have more access than you do, and it can never manage integrations.","\"Revoke\" stops a key immediately."]},{"h":"Add a webhook"},{"steps":["Go to \"Webhooks\" → \"+ New webhook\".","Enter a name and the receiver's URL (https only).","Pick the events (or \"All events\") and click \"Create webhook\".","Copy the signing secret from the table and give it to the developer. Click \"Test\" to send a ping."]},{"bullets":["Each delivery is signed. The receiver must check X-ITOps-Signature before trusting it.","Receivers must reply 2xx within 5 seconds. Failures retry up to 5 times (about 1, 3, 9 and 27 minutes apart). See them in \"Delivery log\"; \"Retry failed now\" retries at once.","\"Pause\" / \"Resume\" stops and restarts a webhook without deleting it.","A webhook goes only to a public internet address: an address inside your network (or a name that leads there) is refused, and \"Test\" shows only the HTTP status the receiver answered, never what it wrote back."]},{"tip":"\"How to connect\" has copy-ready examples and a button to open the full integration guide for developers."},{"p":"Permissions: Integrations (view) to see this page, Integrations (edit) to create or change keys and webhooks."}]},{"title":"Announcement banner and queued webhooks","for":"admin","mod":"integrations","body":[{"p":"Two system switches on Logs & Integrations → Integrations → \"System\" let a Super Admin post a notice to everyone and change how webhooks are sent."},{"tip":"The banner is one line for everyone, with no record of who saw it. For a full message to chosen people, by email and Teams as well, with \"I have read this\", use Announcements in the menu."},{"h":"Post an announcement banner"},{"steps":["Go to Logs & Integrations → Integrations → \"System\".","Under \"Announcement banner\", type the message (up to 240 characters), for example \"Scheduled maintenance Saturday 8–10pm ET\".","Pick the level: \"Info (blue)\", \"Warning (amber)\" or \"Critical (red)\".","Click \"Save\". The banner shows across the top of ITOps for everyone; refresh to see it."]},{"p":"To remove the banner, clear the text and click \"Save\"."},{"h":"Queue webhook deliveries"},{"p":"Tick \"Queue webhook deliveries\" and click \"Save\". Actions then finish at once, and the scheduled job sends webhooks in the background with automatic retry. Use it when you have several webhooks or a slow receiver."},{"warn":"Queued webhooks are only sent when the scheduled job (cron-sla.php) runs. Without it, or without someone having ITOps open, deliveries wait."},{"tip":"The \"System\" tab is Super Admin only. Other admins see \"Super-admin only.\""}]},{"title":"Implementing Business Premium: the ITOps playbook","for":"admin","mod":["m365","m365_admin"],"body":[{"p":"Microsoft 365 Business Premium includes sign-in protection (Entra ID P1: MFA and Conditional Access), device management (Intune), Defender for Business, Defender for Office 365 Plan 1 and the Windows Pro → Business upgrade. This topic is the short version. The full plan — timeline, who does what, every email, checklists and an FAQ — is the organization's own Business Premium implementation guide; Microsoft 365 → Home → Rollout turns it into a checklist you tick off in ITOps."},{"h":"The rule that keeps it gentle: device tiers"},{"bullets":["A — Company PC with Windows Pro/Business: joined to Entra and enrolled in Intune (Defender, BitLocker, updates, compliance, remote lock). IT does it with the person, about 15 minutes.","B — Company PC with Windows HOME: Business Premium does NOT include a Home → Pro upgrade and Defender for Business doesn't support Home. Buy the Pro upgrade (about US$99) and treat it as A, or treat it as C until you do.","C — Personal computer (any edition, or a Mac) — VOLUNTARY: never enrolled. We recommend working in the browser; a browser-only rule (downloads blocked) is optional and would be announced first.","D — Personal phone — VOLUNTARY: never enrolled. Three equal choices: don't use it for work, the phone's browser, or the Outlook/Teams apps (app protection switches on inside them only).","E — Company phone: enrolled with the Company Portal app (only when the organization provides phones)."]},{"tip":"So no — not everyone needs Windows Pro. Only company PCs you want fully managed do. And MFA doesn't need a personal phone either: people choose the Authenticator app, a company security key, or a text message. Nobody's personal device is ever enrolled, and IT can't see personal files, photos, messages or location."},{"h":"The phases (about 10 weeks)"},{"steps":["Step 1 · Prepare (week 0) — IT and leadership only: two break-glass admin accounts; stop personal computers from enrolling in Intune (Windows \"personally owned\" = Block, MDM user scope limited to the company-PC group — Devices → Device policies checks both); computer inventory by tier; allow the sign-in methods; security keys; the personal-device statement; pilot groups (people and their company PCs); staff guides; manager briefing and announcement.","Step 2 · Sign-in approval / MFA (weeks 1–2) — everyone, the one required step: Authenticator app, security key or text message; the three sign-in rules start REPORT-ONLY and are switched On after about a week of clean results; weekly reminders until everyone has a method.","Step 3 · Email protection (weeks 2–3) — nobody notices: SPF, DKIM, DMARC at p=none, Standard preset, block auto-forwarding and SMTP AUTH, mailbox audit; later DMARC → quarantine.","Step 4 · Company computers (weeks 3–9) — company PCs only, in four parts: A get ready (back up policies, connect Defender for Business to Intune, turn on Windows LAPS); B pilot (compliance baseline in report-only + \"Seed device security\" for the pilot PC group, then a one-week review); C everyone in waves (seed device security again for the all-company-PCs group); D turn the rules on (attack-surface rules to Block, compliance to \"Block after 7 days\", optional Defender risk requirement).","Step 5 · Keep it healthy (every month) — 30 minutes: Secure Score, non-compliant company PCs, Defender alerts and attack-surface detections, readiness, key stock, unused licences."]},{"h":"Lost or stolen device"},{"steps":["Devices → \"Lock\" (type LOCK).","Microsoft 365 → People → the person → \"Revoke sessions\" + \"Reset password\".","Company device that won't be recovered: wipe it from the Intune admin center (ITOps deliberately doesn't offer wipe). On a personal phone, only the work data inside the protected apps is removed."]},{"warn":"Never create or switch On a sign-in rule without the break-glass accounts excluded. ITOps refuses to create a rule without them — that exclusion is what saves you if a rule locks everyone out."},{"qa":[{"q":"Do all users need Windows Pro?","a":"No. Only company-owned PCs you want enrolled need Pro/Business. Personal computers of any edition work in the browser; company Home PCs are upgraded or treated as personal until they are."},{"q":"Will anyone be locked out on day one?","a":"No. Sign-in rules start report-only, the device baseline can start as \"Report only (never block)\", and the enforce phase gives a 7-day grace period — announced ahead with the rollout emails."},{"q":"Do staff have to use their personal phone?","a":"No. When the organization provides no phones, phone use is voluntary. For sign-in, a company security key replaces the phone. People who want work on their phone choose the browser or the protected Outlook/Teams apps; the phone itself is never managed."}]}]},{"title":"The Rollout tab: 5 steps, staff emails and readiness","for":"admin","mod":["m365","m365_admin"],"body":[{"p":"Microsoft 365 → Home → Rollout turns the Business Premium plan into 5 steps: 1 Prepare · 2 Sign-in approval (MFA) · 3 Email protection · 4 Company computers · 5 Keep it healthy. Only step 2 is required of everyone. Step 4 touches company PCs only — using a personal phone or computer stays voluntary, and nothing in the plan installs anything on one."},{"h":"What's on the page"},{"bullets":["The five step cards across the top show where you are (\"You are here\") and how far each step is. Click a card to jump to it.","\"Next up\" always shows the single next task, with its buttons (Open, ✉ Email, Check). Tick it and the next one appears.","Each step opens to its tasks; step 4 is split into A get ready · B pilot · C everyone · D turn the rules on. Only the current step is open at first.","Tasks are tagged REQUIRED, RECOMMENDED or OPTIONAL. Tick one when it is done, or press \"Skip…\" and write why — the reason is kept with who and when (\"undo\" reverses it). Required tasks can't be skipped.","\"Optional tightening\" (collapsed at the bottom) holds the rules that would restrict personal devices. Each is a decision, not a deadline.","\"Check readiness\": every licensed person, their sign-in method (security key, app, or text/call only), their company computer, and phone apps (information only).","\"Add the user guides to the Knowledge Base\": 20 draft articles in English and Spanish. Running it again refreshes drafts only; published guides are never touched.","Progress recorded before BT15 is kept — every task has the same id as before."]},{"h":"Sending a communication"},{"steps":["Press ✉ Send communication (or ✉ Email on a step).","Pick the email: announcement, manager briefing, set up sign-in approval, your security key is ready, sign-in approval date, personal computer (safe way), company computer join, phone choices (optional), reminder, company-computer rules date, or rollout complete.","Pick who gets it: everyone with a licence, all managers (Entra \"manager\" field), a group such as the pilot, people with no sign-in method yet, or specific emails.","Fill in only the fields that email uses (dates, what's still to do, who signs it, where to collect a key).","Press Preview recipients — it shows the count and a sample. Then Send. At most 500 per send."]},{"tip":"Each person gets English and Spanish in one email. The wording is editable under Settings → Email templates → Security rollout."},{"qa":[{"q":"Who can use it?","a":"Anyone with Microsoft 365 view can see the checklist and readiness. Ticking or skipping steps and sending email need \"Microsoft 365 · Tenant configuration\" (edit)."},{"q":"Readiness shows — instead of values","a":"A permission is missing; the yellow note names it (AuditLog.Read.All for MFA, DeviceManagementManagedDevices.Read.All for computers, DeviceManagementApps.Read.All for phone apps)."}]}]},{"title":"Sign-in methods, security keys and Temporary Access Pass","for":"admin","mod":["m365","m365_admin"],"body":[{"p":"MFA doesn't need a personal phone. Microsoft 365 → Security → Access & sign-in → \"Sign-in methods people can use\" controls which methods staff may choose, and ITOps marks our advice for each."},{"bullets":["Microsoft Authenticator app — recommended: allow.","Security keys / passkeys (FIDO2) — recommended: allow. USB keys the company provides; no phone needed; the strongest option.","Temporary Access Pass — recommended: allow. How IT hands out keys and helps people who lost a phone or key.","Text message and phone call — your choice. Weakest, but works on any phone; fine as a start or backup.","Email one-time code and certificates — not needed for staff MFA."]},{"p":"\"Allow\" switches a method on for all users. \"Turn off\" asks you to type OFF, because anyone using that method must pick another at their next sign-in."},{"h":"Handing out a security key"},{"steps":["Record the key in Assets & Vendors → Equipment and loan it to the person.","Microsoft 365 → People → the person → \"+ Temporary access pass\". Give them the pass in person.","Sit with them: aka.ms/mysecurityinfo → sign in with the pass → Add sign-in method → Security key → USB → set a key PIN → touch the key.","Rollout → Check readiness now shows \"security key\" for them."]},{"h":"Lost key or new phone"},{"steps":["Microsoft 365 → People → the person → \"+ Manage methods\" → ✕ on the lost key or the old phone.","Issue a Temporary pass so they can sign in and register the replacement.","If you suspect misuse, also Reset password and Sign out everywhere."]},{"warn":"Never send a Temporary Access Pass by email or chat — it is as good as a password for its lifetime. ITOps shows it once and does not store it."},{"qa":[{"q":"\"Could not issue the pass\"","a":"Temporary Access Pass isn't allowed yet (Microsoft 365 → Security → Access & sign-in → Sign-in methods → Allow), or ITOps lacks UserAuthenticationMethod.ReadWrite.All."},{"q":"The Sign-in methods card asks for a permission","a":"Policy.Read.All to read it; Policy.ReadWrite.AuthenticationMethod to change it."}]}]},{"title":"Intune policies: inventory, backup, restore and clone","for":"admin","mod":["m365","m365_admin"],"body":[{"p":"Devices → \"All policies\" reads every Intune policy type — compliance, configuration profiles (including Windows Update rings), settings catalog and endpoint security (Defender antivirus, firewall, BitLocker, attack-surface reduction) and app protection — including ones created in the Intune portal. It shows the platform, who it applies to and how many devices succeeded, failed, conflict or are pending."},{"h":"Back up before you change anything"},{"steps":["Press \"Load all policies\", then \"Back up all\" (or Back up on one row).","ITOps stores the complete policy exactly as Microsoft returned it, with who took it and when.","Backups are listed underneath, newest first."]},{"h":"Restore and clone"},{"bullets":["Restore as new: re-creates a backed-up policy — useful if someone deletes or breaks one in the portal.","Clone: copies a live policy, e.g. to test a change on the pilot group before touching the real one.","Both ALWAYS create a NEW policy; nothing is overwritten. You're asked whether to copy the original's assignments — say no (safest), check it, then assign it."]},{"h":"Editing"},{"bullets":["Compliance policies: Edit on the compliance table (PIN, encryption, Defender, OS minimum, what happens when a device breaks the rules, and who it applies to — all devices, all users or a group).","App protection (phones): Edit on the app-protection table (app PIN and length, backup, Save-as, printing, copy/paste, wipe after days offline, assignment).","Settings catalog / endpoint security: back up, clone and restore here; change individual settings in the Intune admin center."]},{"h":"Seeding the baseline"},{"p":"\"Seed recommended baseline\" now asks for a mode — Report only (marks non-compliant, never blocks; start here) or Enforce (block after a 7-day grace) — and whether to assign it to a pilot group or everyone. Existing policies with the same name are skipped."},{"warn":"Backups need the BT12 database update: open db-update.php once while signed in as a Super Admin. Until then, the backups section says so."}]},{"title":"Device security for company PCs (antivirus, firewall, BitLocker…)","for":"admin","body":[{"p":"The compliance baseline only CHECKS a computer (is BitLocker on? is Defender on?). Device security CONFIGURES it. Microsoft 365 → Devices → Device policies → \"Seed device security\" creates six Intune profiles and assigns them to a device group of company PCs that you choose. Personal computers are never included."},{"h":"What it creates"},{"bullets":["Antivirus — real-time, behaviour and cloud protection (High), blocks potentially unwanted apps, daily quick scan, signatures every 4 hours.","Firewall — on for domain, private and public networks; unsolicited inbound connections blocked.","Attack surface reduction — 12 rules that stop common malware tricks (Office macros, downloaded scripts, password theft from memory, unsigned USB programs, ransomware). They start in AUDIT: nothing is blocked, detections are only reported.","BitLocker — silent disk encryption (TPM only, nothing extra to type); the recovery key is saved to Entra before encryption starts.","Windows Update ring — quality updates after 3 days, feature updates after 60, installs outside 7:00–19:00, restart deadline 7 days plus 2 days grace.","Local admin passwords (Windows LAPS) — every PC gets its own 20-character local administrator password, rotated every 30 days and stored in Entra."]},{"h":"How to use it"},{"steps":["In Entra, create a device group with the pilot company PCs (and later one with all company PCs — a dynamic group on \"device ownership = Company\" works well).","Microsoft 365 → Devices → Device policies → Seed device security → tick the items → choose the pilot device group → Create & assign.","Wait a week. The Device security card shows, per item, how many PCs applied it (ok / error / conflict / pending).","Run it again with the all-company-PCs group. Nothing is duplicated: existing ITOps profiles just get the new group added.","After two clean weeks, check security.microsoft.com → Reports → Attack surface reduction rules, add any exclusions, then press \"Switch to Block…\" on the card and type BLOCK. \"Back to Audit\" reverses it."]},{"h":"Things ITOps does not do for you"},{"bullets":["Defender for Business onboarding: in security.microsoft.com → Settings → Endpoints → Onboarding choose Intune, and in Intune → Endpoint security → Microsoft Defender for Endpoint switch the connector On. The card shows CONNECTED once it is done.","Windows LAPS also needs Entra → Devices → Device settings → \"Enable Microsoft Entra LAPS\" = Yes.","Removing or changing a profile: unassign or edit it in Intune (or with the policy inventory). PCs revert at their next check-in; BitLocker stays encrypted."]},{"tip":"The full manual procedure, with every value, is INTUNE-DEFENDER-SETUP.md in the support files pack (Reference folder)."}],"mod":"m365_admin"},{"title":"Personal computers in Intune (enrolment guard-rail)","for":"admin","body":[{"p":"Personal devices are voluntary, so a personal PC must never be enrolled. It happens anyway when someone adds their work account in Windows while automatic enrolment is open to all users. Microsoft 365 → Devices → Device policies warns you when that is possible and lists any personal Windows PCs already enrolled."},{"h":"Close the gap (both settings)"},{"steps":["Intune admin center → Devices → Enrollment → Device platform restriction → Windows → Personally owned = Block.","Entra admin center → Devices → Device settings (older portals: Mobility (MDM and MAM) → Microsoft Intune) → MDM user scope = Some → the group of company-PC users. Leave MAM user scope = All so phone app protection keeps working."]},{"h":"A personal PC is already enrolled"},{"bullets":["It is marked PERSONAL in the device list. ITOps has no Lock button for it — IT never acts on a device the company does not own.","If it should not be there (for example a former employee's own laptop): first copy its BitLocker recovery key from Entra → Devices → the device → BitLocker keys (so the owner is never locked out), then delete the device record in Intune and in Entra. Deleting the record does not wipe or change the computer.","The owner can also remove the leftover work connection: Settings → Accounts → Access work or school → Disconnect."]},{"tip":"To see which personal computers people actually use — without enrolling them — open Devices → \"Device inventory\" and click the \"Personal\" or \"Unregistered\" tile."}],"mod":"m365_admin"},{"title":"Sign-in rules (Conditional Access) from templates","for":"admin","mod":["m365","m365_admin"],"body":[{"p":"Microsoft 365 → Security → Access & sign-in → Sign-in protection lists every Conditional Access rule and whether MFA-for-all and legacy blocking are in force. With \"Microsoft 365 · Tenant configuration\" (edit) you can create rules from six tested templates and change their state."},{"h":"Reading what a rule does"},{"p":"Click any rule in the list — one made from a template or one somebody created in the Entra admin center. ITOps reads the rule from Microsoft and describes it in plain words:"},{"bullets":["\"Applies to\" and \"Except\": everyone, guests, or the people, groups and admin roles it names — by name, not by id.","\"When they use\": all apps, Office 365, the admin portals or named apps; or an action such as setting up MFA.","\"Only when\": the kind of app (browser, mobile and desktop apps, legacy clients), device platforms, locations, a device filter, sign-in or user risk.","\"Then\": block, require MFA, a compliant device, an app protection policy… and whether all of them or one of them is needed.","\"During the session\": sign-in frequency, whether the browser may stay signed in, browser-only access."]},{"p":"Warnings appear above the description: the rule is report-only or off; no account is excluded from a rule that applies to everyone (keep an emergency account out); the rule blocks everyone from everything; or it refers to a person, group or app that no longer exists. Reading a rule needs only \"Microsoft 365 · View\" and Policy.Read.All; the On / Report-only / Off buttons still need \"Tenant configuration\"."},{"h":"The templates"},{"bullets":["Require MFA for admin roles — do this first.","Require MFA for all users — replaces Security Defaults.","Block legacy sign-in — old protocols can't do MFA.","Phones must use protected apps — Outlook/Teams/OneDrive on phones only through app-protected apps.","Desktop apps need a compliant company device — personal computers still reach mail and files in the browser.","Personal computers: browser-only, no downloads — pair it with SharePoint admin center → Access control → Unmanaged devices → \"Allow limited, web-only access\"."]},{"h":"Safe by design"},{"steps":["Every rule is created REPORT-ONLY: it logs what would happen and blocks nobody.","You must name at least one emergency (break-glass) account; it's excluded from the rule and remembered for next time.","Watch Entra → Sign-in logs → Report-only for about a week.","Press On (type ON). Report-only and Off are one click."]},{"h":"Security Defaults"},{"p":"Security Defaults can't run alongside Conditional Access. When it's on, a \"Turn Security Defaults off\" button appears (type OFF). ITOps only allows it once a \"Require MFA for all users\" rule exists — switch that rule On the same day."},{"warn":"Needs Policy.ReadWrite.ConditionalAccess and Policy.Read.All (turning Security Defaults off also needs Policy.ReadWrite.SecurityDefaults). The browser-only experience in Outlook on the web also needs the OWA command in Email → Email security → hardening checklist."},{"tip":"Switching a rule On asks you to type ON; switching it Off asks you to type OFF."}]},{"title":"Email security: SPF, DKIM, DMARC and the mailbox audit","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Email → Email security covers three layers of email protection: who may send as your domain (DNS, checked live), the Exchange Online settings (assessed with PowerShell, recorded as evidence), and whether any mailbox is already compromised (the audit)."},{"h":"The three DNS records"},{"bullets":["SPF — lists the servers allowed to send as your domain. Must include spf.protection.outlook.com and end in -all.","DKIM — Microsoft signs your outgoing mail once the two selector CNAMEs are published and signing is enabled.","DMARC — tells the world what to do with mail that fails: p=none (monitor) → p=quarantine → p=reject. The page grades each domain and shows the exact record to publish."]},{"h":"The mailbox audit"},{"steps":["Click \"Scan mailboxes\" (up to 300 licensed mailboxes per run; needs the MailboxSettings.Read Application permission — ReadWrite to disable rules).","Red rows forward mail OUTSIDE your domains — the classic sign of a compromised or leaking mailbox. Amber rows silently delete mail.","For any rule you can't explain: \"Disable\", then Microsoft 365 → People → the person → \"Reset password\", \"Revoke sessions\", \"Reset MFA\"."]},{"p":"Vendor routing domains (for example CodeTwo's *.smtp.codetwo.online) are listed but never get DKIM or DNS advice — their DNS belongs to the vendor."},{"h":"Exchange Online controls — assess, change, verify, evidence"},{"p":"Exchange Online settings aren't available through Microsoft Graph, so ITOps can't read or change them; you manage them in Exchange Online PowerShell (and preset protection in the Defender portal). ITOps never runs these commands."},{"steps":["Copy \"Step 1 — Read-only assessment\" and run it. It changes nothing.","For each control (DKIM, forwarding, SMTP AUTH, Outlook on the web for personal computers, preset protection), compare the output with \"Good looks like\".","Only where needed, run the \"Change\" commands. DKIM is created disabled, the CNAMEs Microsoft prints are published exactly, then signing is enabled. Forwarding changes only the Default policy. SMTP AUTH is turned off only after listing the scanners, printers and apps that use it.","Run \"Verify\".","Press \"Record result\": Verified OK, Needs change, Exception accepted or Not applicable, with the key output lines. ITOps saves who and when; every change is also in the Audit Log."]},{"warn":"Outlook on the web for personal computers is optional and needs TWO things: the Exchange OWA setting AND a Conditional Access rule with app-enforced restrictions (\"Personal computers: browser-only\" on Security → Access & sign-in). ITOps shows whether that rule exists. Choose ReadOnly (view attachments in the browser, no download) unless attachments must not be viewed at all (ReadOnlyPlusAttachmentsBlocked)."},{"tip":"Server Guardian re-checks SPF/DKIM/DMARC on every scan and raises an alert if a record breaks — you'll know before customers start landing in spam."}]},{"title":"Security assessment: the rule library, baselines and the tenant's security settings","for":"admin","mod":"security_assessment","body":[{"p":"Microsoft 365 → Posture checks the tenant against ITOps's library of security rules and tells you, for each one, what it found, who or what it affects, why it matters, how to fix it, whether the tenant already owns the license it needs, and what to do first. It only reads: nothing here changes the tenant."},{"h":"The library and the baselines"},{"bullets":["57 rules in eight areas: identity and sign-in, admin accounts, tenant settings, applications, email, devices and Windows, sharing and collaboration, and Secure Score.","Three baselines choose which rules count: Essentials (22 rules, any tenant), Business standard (50, for Business Premium tenants; the default) and Strict (all 57, some needing Entra ID P2). Change it with the menu next to \"Run now\"; the score changes at once, without a new scan.","\"Rules of the baseline\" lists only those; \"Every rule in the library\" shows the others too, marked with their level."]},{"h":"The tenant profile"},{"bullets":["\"Tenant profile\" (next to the baseline) is answered once: staff, where people work, personal phones for company email, countries people sign in from, likely targets, outside requirements (customers, cyber insurance, a regulated field).","Emergency access accounts: the two cloud-only Global Administrator accounts kept out of every Conditional Access policy. Name them here by their sign-in address; the rule \"Two emergency access accounts are ready\" checks them, and later Conditional Access changes will always leave them out.","Rules use the profile to decide what applies (for example, app protection for phones applies when people read company email on personal phones)."]},{"h":"Running it"},{"steps":["Click \"Run now\" (it takes up to a minute), or let it run on its own: weekly by default; the menu changes it to daily or by hand only.","Look at the score and the counts. Click a count (Failed, Warnings, Not licensed…) to see only those rules, or use the filters and the search (it also finds accounts and domains).","Click a rule to open it: what was found, the affected accounts, apps, domains or devices, why it matters, the steps to fix it, the effort and effect on people, what to do first (click one to open it), and the license and Microsoft permission it needs.","After fixing something, run it again. A rule that changed since the run before says \"Better\" or \"Worse since last run\"."]},{"h":"Reading the results"},{"bullets":["Passed, Warning, Failed: the result. Severity (High, Medium, Low) says how much it matters.","\"You already pay for this\": the rule failed, and the tenant's subscriptions already include what it needs. The line under the score lists what the tenant owns (Entra ID P1 and P2, Intune, Defender, Exchange Online, SharePoint Online).","\"Needs …\" (Not licensed): the tenant does not have the license the rule needs. It is shown and left out of the score.","Could not be read: Microsoft refused the read: a permission is missing (Microsoft 365 → Home → Diagnose shows which). Left out of the score; never counted as passed.","Does not apply: nothing to check here (for example, no Windows computers are enrolled).","The score counts the rules of the chosen baseline that could be read and are licensed; high severity weighs 3, medium 2, low 1, and a warning counts half.","History keeps every run (the last 60): open one to see the tenant as it was. Export CSV gives one run as a spreadsheet, with the baseline, license fit, effort, effect and what to do first per rule."]},{"h":"The plan"},{"p":"Posture → Plan turns the latest scan into a plan. It takes the rules of the chosen baseline that failed or warned (and that the tenant is licensed for), puts them in four stages (Prepare, Report-only, Enforce, Tighten), and orders each stage so that what other items wait on comes first (the emergency accounts before everything that needs them), then by severity and effort. It is built by rules: the same scan always gives the same plan."},{"bullets":["Decide each item: \"Do it\" (an owner and a wanted-by date), \"Make it a task\" (creates a ticket in the service desk with the rule, what was found and the steps; assigned to the owner), \"Accept the risk\" (a reason, someone who reviews it, and an expiry at most a year away), \"Not for us\" (a reason) or \"Later\".","Sign-off: once every item is decided, the client contact who agreed to the plan is named and the version is signed off. A signed version is kept as it is.","\"Rebuild from the latest scan\" refreshes the draft; \"Start a new version\" begins the next one from a signed plan. Decisions carry over; an accepted risk whose expiry has passed comes back undecided, saying so.","\"Fixed since\": items whose rule passes in the latest scan. The counts at the top filter the list. Export CSV gives the version as a spreadsheet.","Every build, decision, task, sign-off and refusal is in the Audit Log."]},{"h":"Microsoft's recommended actions"},{"p":"The tab of that name lists Microsoft's own recommended actions for the tenant (the actions behind Secure Score), with their points, effect on people and effort, To do or Done. Where one of ITOps's rules checks the same thing, the action links to it. It is a second opinion next to the library, so Microsoft's newest advice still shows."},{"h":"Microsoft permissions"},{"p":"Application permissions with admin consent: User.Read.All, AuditLog.Read.All, RoleManagement.Read.Directory, Policy.Read.All, Application.Read.All, Domain.Read.All, Organization.Read.All, DeviceManagementManagedDevices.Read.All, DeviceManagementConfiguration.Read.All, DeviceManagementApps.Read.All, DeviceLocalCredential.ReadBasic.All, BitlockerKey.ReadBasic.All, RoleEligibilitySchedule.Read.Directory, SharePointTenantSettings.Read.All and SecurityEvents.Read.All; the Exchange rules use the Exchange connection (Exchange.ManageAsAppV2). A missing permission only leaves its rules unread."},{"tip":"Coming next: fixes made from ITOps (report-only first, with an impact preview) and an AI planning assistant that tailors and explains the plan."}]},{"title":"The planning assistant: suggested decisions, explanations, staff notices and KB articles for the security plan","for":"admin","mod":"security_assessment","body":[{"p":"Microsoft 365 → Posture → Plan has a planning assistant once the AI integration is set up (Settings → Sign-in & AI)."},{"bullets":["Suggest decisions: for each undecided item of the draft plan, the assistant proposes Do it, Make it a task, Accept the risk, Not for us or Later, with one sentence why. It uses the baseline, the tenant profile (Posture → Tenant profile) and the findings.","A suggestion is only shown (\"Suggested: …\" on the item). Open the item and press \"Use it\" to fill the decision and the note; nothing is decided until you save. Suggestions about rules that are not undecided items of the plan are left out, and the count says so.","On each item: Explain in plain words (for a manager who is not technical), Draft a staff notice, Draft a KB article. Edit the text, fill in [date] and [IT contact], then copy it or save it as a KB article draft or an announcement draft. Nothing is published or sent from here.","What the assistant is given: the rules, their area, severity, stage, effort, effect on people, license, what was found as counts, the decisions and the tenant profile. Never people's names, addresses or device names.","Every request is in the Audit Log with what was asked and how many answers were kept (not the text). Asking for suggestions and drafts needs Security assessment (edit); an explanation needs view. Saving needs Knowledge Base (create) or Announcements (create)."]}]},{"title":"Proof: drift, the executive report, the house baseline and the Scorecard","for":"admin","mod":"security_assessment","body":[{"p":"Microsoft 365 → Posture has three tabs that show the work holds: Drift, Executive report and House baseline."},{"bullets":["Drift: after every scan, a rule of the baseline in use that passed in the scan before and now fails or warns is recorded. The people with Security assessment (edit) and Super Admins get a bell, and the Audit Log has it (\"sa_drift\").","Each drift lists what changed between the two scans: Conditional Access and admin role changes made in the app (with who made them), and, when Microsoft 365 is connected, the Entra audit log and the Intune audit log. Exchange changes are not in those logs: check the Exchange admin center audit. Reading the audit logs needs AuditLog.Read.All and DeviceManagementApps.Read.All.","Someone with edit acknowledges each drift with a short note (who changed it and why, or what was done). \"Passes again now\" shows when the latest scan has it fixed.","Executive report: \"Build the report\" makes one page for the client — the score and its trend over six months, the plan and its sign-off, the top ten open risks, the risks accepted and when they expire, drift in the last 90 days and what improved. Print it or save it as PDF, or download it.","House baseline: \"Make it from the baseline in use\" starts your own rule set. Tick rules in or out, and write a note on why. Export gives a file; at the next client, Import reads it (rules this version does not know are left out and listed) and can put it in use. The house baseline then appears in the baseline list at the top.","Scorecard: add a measurable with the source \"Security assessment — score\", \"— failed rules\" or \"— drift\". Score and failed rules use the last scan before the end of each period; drift counts what was found in the period."]},{"p":"Everything here — scans, drift, acknowledgements, reports, house baseline changes, imports and exports — is written to the Audit Log. Nothing here changes the tenant."}]},{"title":"Conditional Access: policies from templates in report-only, what they would do, turning them on and putting a change back","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Security → Conditional Access changes Conditional Access in the tenant without opening the Entra admin center, with guard rails."},{"bullets":["First mark the emergency access accounts (Posture → Security assessment → Tenant profile). Nothing is created or turned on here until they are, and they are left out of every policy made here. A policy that does not leave them all out cannot be turned on from here.","Templates: block legacy sign-in, multifactor for everyone, multifactor for admins, phishing-resistant sign-in for admins, block device code sign-in, compliant device for admins, compliant device or protected app for everyone, challenge risky sign-ins and fix high-risk users (Entra ID P2), block sign-in from other countries (you name the allowed countries). Each is created in report-only: nothing changes for anyone, Microsoft only records what it would have done.","\"What it would do\" on a policy reads the sign-in log (last day, 7 or 30 days) and lists who would have been blocked or asked for more. Give a new report-only policy a few days before turning it on.","On, Report-only and Off on each policy. Delete is offered only for policies made here; others are turned off instead.","Security defaults: when on, policies cannot be turned on. \"Switch to Conditional Access\" (type SWITCH) turns security defaults off and turns on four policies that do the same; if Microsoft refuses one, security defaults are turned back on and nothing else changes.","Changes made here: every change keeps the policy as it was, and \"Put back\" undoes it (a deleted policy is created again, a state goes back, security defaults come back on).","Second person: Settings → Approvals → \"Change Conditional Access\" (off by default). When on, a change waits for someone else with \"Microsoft 365 · Conditional Access\"; it lapses after 24 hours.","Every sign-in of an emergency access account raises a bell for Super Admins and Conditional Access holders and goes in the Audit Log (checked by the scheduled job).","A failed rule or plan item that a template fixes has a \"Fix in …\" button that opens this tab on that template.","Permissions: \"Microsoft 365 · Conditional Access\" (edit), not given to any role automatically. Graph: Policy.Read.All, Policy.ReadWrite.ConditionalAccess and Application.Read.All to change, AuditLog.Read.All for \"What it would do\" and the emergency watch, User.Read.All for the emergency accounts."]}]},{"title":"Defender incidents and admin roles: handling an incident, removing a role or making it eligible","for":"admin","mod":"m365","body":[{"p":"Microsoft 365 → Security handles two more things without opening Microsoft's portals."},{"bullets":["Alerts & actions → Open incidents → \"Handle\" on an incident: its alerts (with the people and devices they touch) and comments. Assign it (to you or someone with \"Microsoft 365 · Security incidents\"), mark it \"Working on it\", add a comment, make a ticket of it (once per incident; the ticket gets the alerts and the Defender link), and resolve it.","Resolving asks what it was, as Microsoft does: a true positive (malware, phishing, compromised account…), expected activity (a security test, a line-of-business app…) or a false positive, plus what was found and done. That text is kept with the incident in Defender.","Security → Admin roles: everyone who holds a directory role, permanent or eligible, and what makes each admin account risky: synchronized from on-premises, licensed (used every day), no multifactor sign-in, not signed in for 90 days, disabled, guest. Each count filters the list.","Remove a role (type the account's address to confirm), or \"Make eligible\" (Entra ID P2): the person keeps the role but switches it on in Entra when needed. At least two people always stay Global Administrator permanently, and an emergency access account keeps its role. Roles held by a group are changed in Entra.","Changes made here: every change is kept and \"Put back\" undoes it.","Second person: Settings → Approvals → \"Change an admin role\" (off by default). When on, someone else with \"Microsoft 365 · Directory roles\" approves; requests lapse after 24 hours.","A failed admin rule in Posture (Global Administrator count, separate admin accounts, cloud-only admins, roles when needed, admin multifactor) has a \"Fix in …\" button that opens Admin roles on the right filter.","Permissions: \"Microsoft 365 · Security incidents\" (new, not given to any role automatically) and \"Microsoft 365 · Directory roles\". Graph: SecurityIncident.ReadWrite.All; RoleManagement.ReadWrite.Directory; RoleEligibilitySchedule.ReadWrite.Directory for eligible roles; AuditLog.Read.All for last sign-in and multifactor registration."]}]},{"title":"Risky people: who is at risk and the automatic follow-up","for":"admin","mod":"security_assessment","body":[{"p":"Microsoft 365 → People → At risk lists every account the security assessment finds at risk, one row per person, with a score from 0 to 100, a level (High 50+, Medium 25+, Low) and the reasons. It refreshes with every assessment run."},{"bullets":["Reasons and their points: Microsoft marks the account compromised (60), high sign-in risk (50), admin without multifactor sign-in (40), medium sign-in risk (30), no multifactor sign-in (25), unencrypted computer (20), admin role on the everyday account (15), not used for 90 days (15), device that breaks the security rules (15), never signed in (10), text message or call as the only second step (10), low sign-in risk (10).","Microsoft's own sign-in risk needs Entra ID P2 and the permission IdentityRiskyUser.Read.All; without them the other reasons still count, and the page says what could not be read.","Microsoft's list (the tab beside People at risk) is Microsoft's own risky-users list. Microsoft gives it to apps only when the tenant has Microsoft Entra ID P2; Microsoft 365 Business Premium includes Entra ID P1, where the Entra admin center shows the people with limited data (risk level \"None\", no reason). The tab says which is missing — the permission (with the steps in the Entra admin center) or the license — and \"Check again\" asks Microsoft afresh once it is added. One P2 license is enough to try it; Microsoft's licensing expects one for each person the feature protects. Until then, People at risk and the fixes on the person's account work with P1: reset the password (an admin-set password counts as remediating Microsoft's risk), revoke sessions, require multifactor registration again, block sign-in.","Click a person to see each reason, its points and what they are asked to do. A ▲ or ▼ shows how the score moved since the run before."]},{"h":"The automatic follow-up"},{"steps":["Switch it on under Follow-up, choose the levels to follow (High, Medium, Low), the days to fix it, when to remind, and what happens at the deadline. While it is on, the assessment runs every day.","Someone newly at a followed level gets an email with their own reasons, the steps and the deadline.","If it is still open after the reminder days, they get one reminder.","At the deadline: their manager (from Microsoft 365) gets an email, IT gets a ticket, and the changes ITOps can make are proposed under Approvals.","When a later assessment no longer finds them at a followed level, the follow-up closes as Fixed, the ticket is resolved with a note, and open proposals are withdrawn."]},{"h":"Approvals: nothing changes without one"},{"bullets":["Proposed changes: add to the MFA-required group (set the group under Follow-up), sign out everywhere, block sign-in.","Approve carries it out at once in Microsoft 365; Dismiss asks why. Approving also needs the matching Microsoft 365 permission (Groups, Accounts or Tenant configuration), admin accounts need a Super Admin, and nobody can approve a change on their own account.","Dismiss under Follow-up stops following someone for 30 days (for example a shared account you accept), resolves their ticket and withdraws their proposals."]},{"p":"The three emails are in Settings → Email templates → \"Risky people follow-up\" (English and Spanish). Every message, ticket, proposal, approval and refusal is in the Audit Log."}]}]}],"quickstarts":{"user":{"title":"End-user Quick Start","intro":"How to sign in, ask IT and Operations for help, and follow your request. Keep this page handy.","body":[{"h":"1. Sign in"},{"steps":["Open the ITOps link, type your email and password, and choose \"Sign In\". Or choose \"Sign in with Microsoft 365\" if you see it.","If asked for a code, type the 6-digit code from your authenticator app and choose \"Verify\" (or \"Use a backup code instead\").","8 wrong passwords in 15 minutes locks sign-in for about 15 minutes. Forgot your password? Ask your ITOps administrator; there is no reset link."]},{"h":"2. Set up your account (once)"},{"steps":["Click your name at the top right to open \"Account\".","\"Email language\": choose \"English\", \"Español\" or \"Organisation default\".","\"Set up 2FA\": scan the QR code, type the code, choose \"Verify & turn on\".","Choose \"Copy codes\" and store your 10 backup codes somewhere safe, then \"Done\"."]},{"h":"3. Ask for help"},{"bullets":["No account needed: use the \"Submit a Help Request\" page or a request form your team shared, or email the help desk. Save the TK- number you get.","If a suggested article fixes it, choose \"This solved it — no ticket needed\"."]},{"steps":["In the app: Service Desk → Tickets → \"+ New Ticket\".","Choose a \"Subject\" group, then a \"Category\". Leave \"Priority\" at \"Medium\" unless it's urgent.","Put all the detail in \"Description\": what's wrong, error messages, when it started, what you tried.","Choose \"Create Ticket\". Leave \"Assignee\" and the due boxes empty."],"mod":"tickets:create"},{"h":"4. Add files","mod":"tickets"},{"bullets":["Open your ticket → \"Upload\" → drag a file in or \"Browse\". One file at a time, up to 50 MB: pictures, audio/video, PDF, Word, Excel, PowerPoint, CSV, TXT, XML or JSON.","Or use the camera icon in the top bar: \"Photo\", \"Video\" or \"Screenshot\" → \"📎 Attach to ticket\".","Files attached to emails are NOT saved to the ticket. Upload them in the app."],"mod":"tickets"},{"h":"5. Follow and reply","mod":"tickets"},{"bullets":["Find your tickets under Dashboard → \"My Tickets\" or Service Desk → Tickets. Use \"Opened by me\" / \"Assigned to me\", \"Still open\", and the search box to narrow the list. The \"Open TK-… in ITOps\" button in ticket emails takes you straight there.","Reply in \"Add a comment…\" → \"Post\". The person working on it gets a bell and an email, so you can go back and forth until it's solved.","Or reply to a ticket email keeping the TK- number in the subject (text only).","Status: open → in progress → pending (waiting, often on you) → resolved → closed. Not fixed after \"resolved\"? Comment on the same ticket."],"mod":"tickets"},{"h":"6. Watch the bell"},{"bullets":["The bell shows \"New comment\", reminders and requests, with a red unread count.","Click an item to open the page; \"Mark all read\" clears the count."]},{"h":"7. Find answers yourself","mod":"kb"},{"bullets":["Knowledge → Knowledge Base has your team's how-to articles. Search them from the top search box."],"mod":"kb"},{"bullets":["Knowledge → Ask IT: type your question in plain words and choose \"Send\"."],"mod":"kb_assist"},{"h":"8. Procedures you must acknowledge","mod":"sops"},{"steps":["Open Knowledge → SOPs (the bell tells you when one is waiting).","Read the procedure and choose \"Acknowledge this version\"."],"mod":"sops"},{"tip":"Click the question mark in the top bar at any time to open the Help Center. ITOps signs you out after about 30 minutes of inactivity, so save your work."}]},"agent":{"title":"Support Agent Quick Start","intro":"A daily checklist for working the ticket queue in Service Desk → Tickets.","mod":"tickets:all","body":[{"h":"1. Start of day"},{"steps":["Check the bell for \"Ticket assigned to you\", \"New comment\" and \"… SLA due soon\" / \"… SLA breached\".","Service Desk → Tickets → first filter \"Unassigned\" (+ \"Still open\"): triage these first.","Then switch to \"Assigned to me\" and work the red and amber SLA badges first.","Use the refresh button to reload. The list holds the 1,000 newest tickets; use the top search for older ones."]},{"h":"2. Triage a new ticket"},{"steps":["Open it → \"Edit\".","Set \"Category\" and \"Priority\" (Critical, High, Medium, Low, Planning).","Due times are filled in automatically from the category and priority; adjust \"Response due\" / \"Resolution due\" only if you agreed something else.","Pick an \"Assignee\" → \"Save Changes\". They get a bell notification and an email."]},{"h":"3. Work it"},{"bullets":["A normal comment is PUBLIC: the requester sees it and may get it by email. Tick \"Internal note\" first for team-only notes (yellow, INTERNAL).","Use \"🔔 Notify\" to message a colleague privately (bell, optional email).","\"Upload\" adds files (up to 50 MB; pictures, audio/video, PDF, Office, CSV, TXT, XML, JSON). \"Transcribe\" turns audio or video (up to 25 MB) into text.","AI: in \"Edit\" → \"Summarize & suggest\" → check → \"Apply to form\" → \"Save Changes\"; \"Copy\" the draft reply into a comment and edit it before you \"Post\"."]},{"h":"4. Keep the status honest"},{"bullets":["open → in progress when you start. Saving off open records the first response.","pending when waiting on the requester. The badge says \"Paused\": no SLA alerts, and the due times move on by the time spent in Pending.","resolved when fixed, closed when finished, cancelled for duplicates or withdrawn requests.","Changing the priority or category recalculates the due times (unless you type your own in the same edit)."]},{"h":"5. SLA badges"},{"bullets":["Blue \"Due …\" on track. Amber due soon (response under 1h, resolution under 4h). Red \"Overdue …\". Green \"Met\". Purple \"Paused\" (pending).","The list shows the resolution badge; the ticket shows \"Response\" and \"Resolution\"."]},{"h":"6. Watch for"},{"bullets":["\"EXT\" requesters have no ITOps login. Email is their only channel. Their email replies ring your bell and send you a \"Requester replied\" email.","Comments starting \"(email from UNRECOGNISED sender …)\" are internal notes. Verify the sender before acting.","Email attachments aren't saved. Ask for uploads or upload them yourself."]},{"h":"7. Close out"},{"steps":["Post a final comment explaining the fix.","Set \"Status\" to resolved (or closed) → \"Save Changes\". The requester is emailed if status emails are on."]},{"steps":["If the fix will come up again, write it up in Knowledge → Knowledge Base → \"New Article\"."],"mod":"kb:create"},{"tip":"Always read AI output and transcripts before posting them. You are responsible for what the requester receives."}]},"admin":{"title":"Administrator Quick Start","intro":"A setup checklist for a new ITOps install, then the routine that keeps it healthy. Most settings live under Administration → Settings, and several steps need a Super Admin.","mod":["settings:edit","users:edit"],"body":[{"h":"Part 1: New install checklist"},{"h":"1. Check the install"},{"steps":["Sign in with the Super Admin account the installer created.","Delete the install/ folder on the server, or deny web access to it.","Browse to https://YOUR-SITE/config.php and https://YOUR-SITE/sql/. Both must return 403.","Settings → \"General\": \"Backend connection\" should say \"API reachable and database connected\". Under \"About\", note the Version.","Settings → \"Maintenance\": \"Database Updates\" should say \"Your database is up to date.\" If not, click \"Apply updates now\"."]},{"h":"2. Make it yours"},{"steps":["Settings → \"Branding\": \"Application name\", then upload a PNG \"Logo\" and a \"Favicon\" (SVG files are refused).","Optional: set the \"Public form redirect URL\" and the \"Navigation icons\"."]},{"h":"3. Email"},{"steps":["Settings → \"Email\": tick \"Enabled\" for outbound email, set \"From name\", \"From address\" and \"Send via\", then click \"Save settings\". Saving once also creates the cron token.","Click \"Send test email to myself\" and check the Result in the outbound email log.","Choose the ticket email tick boxes (acknowledgements, replies and status changes are off by default).","Optional: turn on \"Email-to-Ticket Intake\" for your help-desk mailbox, then \"Test connection\" and \"Run now\".","Settings → \"Email templates\" → \"Header, footer & language\": pick the default language and check the footer. Review the ticket emails."]},{"h":"4. Categories and the SLA clock"},{"steps":["Administration → Ticket Categories: add groups and categories, with \"Response SLA (hours)\" and \"Resolution SLA (hours)\" only where a category needs its own; blank uses the priority targets. Give each an owner and backup who can edit tickets.","Settings → \"SLA & Hours\" → \"Priority targets\": check the hours for each priority, then \"Save priority targets\".","Settings → \"SLA & Hours\": set business hours (check the time zone spelling) and holidays, then \"Save business hours\".","In the same tab, check the alert warning times and the weekly digest box, then \"Save SLA settings\".","Back on Ticket Categories, read the \"Routing & SLA check\" box and fix anything red or amber."]},{"h":"5. Scheduled jobs"},{"steps":["In cPanel → Cron Jobs, add cron-mail.php and cron-sla.php every 5 minutes, and \"cron-sla.php digest\" weekly. The exact lines are in the Help Center topic on scheduled jobs.","Without cron, leave \"Run automatically while ITOps is open\" ticked. The weekly digest and exact-time offboarding still need cron.","Check Logs & Integrations → Event Log, channel cron, for \"SLA scan complete\" entries."]},{"h":"6. Microsoft 365 and sign-in"},{"steps":["Settings → \"Sign-in & AI\" → \"Microsoft 365 / Azure\": enter the tenant ID, client ID, secret and redirect URI, tick \"Enable SSO\", \"Save\", then \"Test Graph connection\".","The same tenant, client ID and secret also power the Microsoft 365 pages, Server Guardian and onboarding (they are shown in Logs & Integrations → Integrations → \"System\" → \"Microsoft 365 connection\"). Add the application permissions in Azure with admin consent, then check Microsoft 365 → Home → \"Diagnose\".","Remember: first-time Microsoft sign-ins get the Viewer role automatically."]},{"h":"7. Roles, people and security"},{"steps":["Administration → Roles & Permissions: build your roles from the presets. See \"Recommended role setups\". Only agents should get Tickets \"All records\".","Administration → Users (or Bulk Import): add people and give them roles. Keep Super Admin to one or two people.","Settings → \"General\" → \"Session security\": choose who must use 2FA and set the idle timeout. Then set up 2FA on your own account."]},{"h":"8. Optional extras"},{"steps":["Settings → \"Sign-in & AI\" → \"AI assist\": provider, model and key.","Knowledge → KB Content Gaps → \"Seed starter articles\", then review and publish the drafts.","Administration → Forms: build request forms.","vTiger: deploy vtiger-bridge/itops-bridge.php, save the bridge secret, click \"Test bridge\". Then build onboarding templates in Administration → Onboarding Templates."]},{"h":"Part 2: Ongoing routine"},{"h":"Every week"},{"steps":["Read the weekly SLA digest. Look into falling compliance or a growing overdue count.","Logs & Integrations → Event Log: filter to Error and fix anything new.","Settings → \"Email\": scan the outbound email log for failed sends.","Knowledge → KB Content Gaps: turn the most-asked questions into articles, then click \"Mark covered\"."]},{"h":"Every month"},{"steps":["Administration → Users: set leavers to Inactive and check new Microsoft sign-ins that got the Viewer role.","Check who holds Super Admin and which roles include SENSITIVE modules.","Logs & Integrations → Audit Log: look for login_lockout, mfa_failed, settings_updated and role changes you don't recognise. Export a CSV if you keep records.","Read the monthly access re-check result (the \"Access re-check found a problem\" email, or the Event Log, channel onboarding).","Look at contracts and credentials marked Expiring, Due soon or Overdue.","Logs & Integrations → Integrations: revoke API keys and pause webhooks nobody uses."]},{"h":"When a new build arrives"},{"steps":["Follow \"Updating ITOps to a new build\": extract the full zip over the folder, run the database update if the CHANGELOG says \"DB UPDATE REQUIRED\", upload a new vTiger bridge only if asked, hard-refresh, and check the build stamp under Settings → General → About."]},{"h":"Once a year"},{"steps":["Add next year's holidays under Settings → \"SLA & Hours\".","Rotate the vTiger bridge secret with \"Rotate secret…\", and renew the Azure client secret before it expires.","Review the 2FA policy, the idle timeout and your role setups."]},{"tip":"The database update is safe to run at any time. It only applies what's missing."}]}}};
const $=id=>document.getElementById(id);
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function bodyHtml(body){
  let h='';
  (body||[]).forEach(it=>{
    if(it.mod&&!allowed(it.mod)) return;   // block meant for another role (e.g. an agent-only paragraph)
    if(it.p) h+='<p>'+esc(it.p)+'</p>';
    else if(it.h) h+='<h4>'+esc(it.h)+'</h4>';
    else if(it.bullets){ h+='<ul>'+it.bullets.map(b=>'<li>'+esc(b)+'</li>').join('')+'</ul>'; }
    else if(it.steps){ h+='<ol>'+it.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>'; }
    else if(it.tip){ h+='<div class="tip"><b>Tip:</b> '+esc(it.tip)+'</div>'; }
    else if(it.warn){ h+='<div class="warn"><b>Important:</b> '+esc(it.warn)+'</div>'; }
    else if(it.qa){ h+='<div class="qa"><div class="qah">Common questions</div>'+it.qa.map(x=>'<div class="qai"><div class="q">'+esc(x.q)+'</div><div class="a">'+esc(x.a)+'</div></div>').join('')+'</div>'; }
  });
  return h;
}
function searchText(t){ let s=t.title+' '; (t.body||[]).forEach(it=>{ if(it.mod&&!allowed(it.mod))return; s+=(it.p||'')+' '+(it.tip||'')+' '+(it.warn||'')+' '+(it.h||'')+' '+((it.qa||[]).map(x=>x.q+' '+x.a).join(' '))+' '+((it.bullets||[]).join(' '))+' '+((it.steps||[]).join(' '))+' '; }); return s.toLowerCase(); }

const list=$('list'), results=$('results');

/* ---------- Role-aware Help Center ----------
   Topics carry "mod" = the permission module they are about ("tickets", "tickets:edit", or a list = any of).
   The signed-in user's role decides which topics show (same rules as the app's menu — keep in sync with
   itopsCanFrom in index.html / itops_can in api/index.php). Not signed in = general topics only. */
const PERM_INHERIT={security_assessment:['m365_admin','edit'],m365_mail:['m365_admin','edit'],license:['settings','edit'],calendar:['tickets','view'],kb_assist:['kb','view'],kb_gaps:['kb','edit'],event_log:['audit','view'],integrations:['settings','edit'],branding:['settings','edit'],email_cfg:['settings','edit'],sla_cfg:['settings','edit'],m365_users:['m365_admin','edit'],m365_credentials:['m365_admin','edit'],m365_licenses:['m365_admin','edit'],m365_groups:['m365_admin','edit'],provision_onboard:['onboarding','edit'],provision_offboard:['onboarding','edit']};
function itopsWild(w){ return !!w&&w!=='0'&&!(Array.isArray(w)&&!w.length)&&!(typeof w==='object'&&!Array.isArray(w)&&!Object.keys(w).length); }
function canFrom(role,p,mod,act){
  act=act||'view'; if(role==='super_admin')return true; p=p||{};
  if(itopsWild(p['*']))return true;
  if(mod==='dashboard')return true;
  const v=p[mod];
  if(v==null){
    if(mod==='my_signatures'||mod==='my_equipment')return act==='view';
    if(Object.keys(p).some(k=>Array.isArray(p[k])))return false;
    if(mod==='changelog')return act==='view';
    const inh=PERM_INHERIT[mod]; if(inh)return canFrom(role,p,inh[0],act==='view'?'view':inh[1]);
    return false; }
  if(Array.isArray(v))return act==='view'?v.length>0:v.includes(act);
  if(v==='none'||v===false)return false;
  if(act==='view')return true;
  if(act==='create'||act==='edit')return ['crud','create_edit','dept_manage','own','full',true].includes(v);
  if(act==='delete')return ['crud','dept_manage','full',true].includes(v);
  if(act==='all')return ['crud','dept_manage','full','read_all','all',true].includes(v);
  return true;
}
let ME=null;          // {role, role_permissions, display_name} when signed in
let SHOW_ALL=false;   // admins can switch to "all topics"
// BT101: topics of modules that are not part of this installation are left out for everyone ("all topics" included)
let PERMS_OFF={};
const CAT_MOD={'Tickets & support':'tickets','Forms & intake':'forms'};
function modOff(mod){ const l=(Array.isArray(mod)?mod:[mod]).filter(Boolean); return l.length>0&&l.every(x=>PERMS_OFF[String(x).split(':')[0]]); }
function allowed(mod){
  if(modOff(mod)) return false;
  if(!mod) return true;
  if(SHOW_ALL) return true;
  if(!ME) return false;
  return (Array.isArray(mod)?mod:[mod]).some(x=>{ const [m,a]=String(x).split(':'); return canFrom(ME.role,ME.role_permissions,m,a||'view'); });
}
function visibleCats(){ return CONTENT.categories.map(c=>({cat:c.cat,topics:c.topics.filter(t=>!modOff(t.mod||CAT_MOD[c.cat])&&allowed(t.mod))})).filter(c=>c.topics.length); }

let flat=[];
function render(){
  list.innerHTML='';
  const cats=visibleCats();
  cats.forEach((c)=>{
    const row=document.createElement('button'); row.className='catrow'; row.type='button';
    row.innerHTML='<span class="catname">'+esc(c.cat)+'</span><span class="cnt">'+c.topics.length+'</span><span class="chev">›</span>';
    const wrap=document.createElement('div'); wrap.className='topics'; wrap.hidden=true;
    c.topics.forEach(t=>{
      const tr=document.createElement('button'); tr.className='toprow'; tr.type='button';
      tr.innerHTML='<span>'+esc(t.title)+(t.for==='admin'?' <span class="tag">Admin</span>':'')+'</span>';
      const tb=document.createElement('div'); tb.className='topbody'; tb.hidden=true; tb.innerHTML=bodyHtml(t.body);
      tr.addEventListener('click',()=>{ const op=!tb.hidden; tb.hidden=op; tr.classList.toggle('open',!op); });
      wrap.appendChild(tr); wrap.appendChild(tb);
    });
    row.addEventListener('click',()=>{ const op=!wrap.hidden; wrap.hidden=op; row.classList.toggle('open',!op); });
    list.appendChild(row); list.appendChild(wrap);
  });
  flat=[]; cats.forEach(c=>c.topics.forEach(t=>flat.push({c:c.cat,t:t,s:searchText(t)+' '+c.cat.toLowerCase()})));
  const total=CONTENT.categories.reduce((n,c)=>n+c.topics.length,0), shown=flat.length;
  const note=$('rolenote');
  if(note){
    if(!ME) note.innerHTML='Showing general topics. <b>Sign in</b> to '+esc(APP_NAME)+' to see the guides for the features your role uses.';
    else if(ME.role==='super_admin'||shown===total) note.innerHTML='';
    else note.innerHTML='Showing the '+shown+' topics for your role'+(ME.role_name?' (<b>'+esc(ME.role_name)+'</b>)':'')+'.'+(ME.canAll?' <a href="#" id="allt">'+(SHOW_ALL?'Show only my topics':'Show all '+total+' topics')+'</a>':'');
    const at=$('allt'); if(at) at.onclick=(e)=>{ e.preventDefault(); SHOW_ALL=!SHOW_ALL; render(); };
  }
  const q=$('q'); if(q&&q.value) q.dispatchEvent(new Event('input'));
}
$('q').addEventListener('input',function(){
  const q=this.value.trim().toLowerCase();
  if(!q){ list.style.display=''; results.style.display='none'; results.innerHTML=''; return; }
  list.style.display='none'; results.style.display='';
  const hits=flat.filter(x=>x.s.indexOf(q)>=0);
  results.innerHTML = hits.length ? hits.map(x=>'<div class="rcard"><div class="rcat">'+esc(x.c)+'</div><div class="rtitle">'+esc(x.t.title)+(x.t.for==='admin'?' <span class="tag">Admin</span>':'')+'</div>'+bodyHtml(x.t.body)+'</div>').join('') : '<div class="rnone">No matching topics.</div>';
});
render();   // general topics right away; refined as soon as we know who is signed in
(function loadMe(){
  const API0=location.pathname.replace(/\/[^/]*$/,'')+'/api';
  const hdr={}; try{ const tk=localStorage.getItem('itops_token'); if(tk) hdr['X-ITOps-Token']=tk; }catch(_){}
  fetch(API0+'/auth/me',{headers:hdr,credentials:'include'}).then(r=>r.ok?r.json():null).then(d=>{
    const u=d&&d.user; if(!u) return;
    ME={role:u.role,role_permissions:u.role_permissions||{},role_name:u.role_name||'',display_name:u.display_name||''};
    // people who manage roles may look at every topic (e.g. to help a colleague)
    ME.canAll=u.role==='super_admin'||canFrom(u.role,ME.role_permissions,'roles','view')||canFrom(u.role,ME.role_permissions,'settings','edit');
    render();
    loadVisuals(API0,hdr);
    fetch(API0+'/modules',{headers:hdr,credentials:'include'}).then(r=>r.ok?r.json():null).then(m=>{
      if(!m||!Array.isArray(m.perms_off)||!m.perms_off.length) return;
      PERMS_OFF={}; m.perms_off.forEach(p=>{PERMS_OFF[p]=true;}); render();
    }).catch(()=>{});
  }).catch(()=>{});
})();

/* ---------- BT50: visual guides ----------
   Only the pages given to this person's role or to them are listed (a Super Admin sees all and can change who sees
   them). A page is fetched with the person's sign-in and shown in a sandboxed frame: it can draw, it cannot reach
   the person's session. */
let VIS_API=null, VIS_HDR={}, VIS_IDS=[];
function visFromHash(){ const h=(location.hash||'').match(/^#v=([a-z0-9-]+)$/); if(h&&VIS_IDS.indexOf(h[1])>=0&&$('vview').hidden) openVisual(h[1]); }
window.addEventListener('hashchange',visFromHash);
function loadVisuals(api,hdr){
  VIS_API=api; VIS_HDR=hdr||{};
  fetch(api+'/help/visuals',{headers:VIS_HDR,credentials:'include'}).then(r=>r.ok?r.json():null).then(d=>{
    const box=$('vis'), l=$('visl'); if(!d||!box)return;
    const vs=d.visuals||[];
    if(!vs.length){ box.hidden=true; return; }
    l.innerHTML=vs.map(v=>'<button type="button" class="visc" data-vis="'+esc(v.id)+'"><b>'+esc(v.title)+'</b><span>'+esc(v.description||'')+'</span><i>Open ›</i></button>').join('');
    l.querySelectorAll('[data-vis]').forEach(b=>b.addEventListener('click',()=>openVisual(b.getAttribute('data-vis'))));
    const m=$('vismanage'); if(m){ m.hidden=!d.can_manage; wireManage(m); }
    box.hidden=false;
    VIS_IDS=vs.map(v=>v.id); visFromHash();
  }).catch(()=>{});
}
/* BT71: "Who sees them…" opens Settings → Help visuals in the app itself. Inside the app's Help panel this page is a frame:
   it asks the app to go there (and close the panel) instead of loading a second copy of the app inside the panel. */
function wireManage(a){ a.href=appUrl+'#help_visuals'; a.target='_top';
  a.onclick=function(e){ let framed=false; try{ framed=window.parent&&window.parent!==window&&window.parent.location.origin===location.origin; }catch(_){ framed=false; }
    if(!framed) return true;   // a page of its own: follow the link
    e.preventDefault(); try{ window.parent.postMessage({type:'itops-help-goto',page:'help_visuals'},location.origin); }catch(_){} return false; }; }
/* BT51: the pages can be read light or dark. The first time it follows the theme chosen in the app (or the computer's);
   a choice made here is remembered on this browser. The page gets it from here only: the frame keeps no storage. */
function visTheme(){ let t=null; try{ t=localStorage.getItem('itops_vis_theme')||localStorage.getItem('itops_theme'); }catch(_){}
  if(t!=='light'&&t!=='dark') t=(window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light'; return t; }
function visThemeShow(t){ document.querySelectorAll('[data-vtheme]').forEach(b=>b.setAttribute('aria-pressed',String(b.getAttribute('data-vtheme')===t)));
  const f=document.querySelector('#vbody iframe'); if(f){ f.classList.toggle('dark',t==='dark'); try{ f.contentWindow.postMessage({type:'itops-theme',theme:t},'*'); }catch(_){} } }
document.querySelectorAll('[data-vtheme]').forEach(b=>b.addEventListener('click',()=>{ const t=b.getAttribute('data-vtheme'); try{ localStorage.setItem('itops_vis_theme',t); }catch(_){} visThemeShow(t); }));
function closeVisual(){ const v=$('vview'); v.hidden=true; $('vbody').innerHTML=''; document.body.style.overflow=''; if(/^#v=/.test(location.hash)) history.replaceState(null,'',location.pathname+location.search); }
function openVisual(id){
  const v=$('vview'), body=$('vbody'); $('vtitle').textContent='Loading…'; body.innerHTML='<div class="vmsg">Loading…</div>'; v.hidden=false; document.body.style.overflow='hidden';
  fetch(VIS_API+'/help/visuals/'+encodeURIComponent(id),{headers:VIS_HDR,credentials:'include'}).then(r=>r.json().then(j=>({ok:r.ok,j}))).then(({ok,j})=>{
    if(!ok||!j||!j.html){ $('vtitle').textContent='Visual guide'; body.innerHTML='<div class="vmsg">'+esc((j&&j.error&&j.error.message)||'This page could not be opened.')+'</div>'; return; }
    $('vtitle').textContent=j.title||'Visual guide';
    const th=visTheme();
    const f=document.createElement('iframe'); f.className='vframe'+(th==='dark'?' dark':''); f.title=j.title||'Visual guide'; f.setAttribute('sandbox','allow-scripts'); f.setAttribute('data-vis-frame',id);
    f.srcdoc=String(j.html).replace('<html lang="en" data-theme="light">','<html lang="en" data-theme="'+th+'">'); visThemeShow(th);
    body.innerHTML=''; body.appendChild(f);
    try{ history.replaceState(null,'','#v='+id); }catch(_){}
  }).catch(()=>{ body.innerHTML='<div class="vmsg">This page could not be opened. Check the connection and try again.</div>'; });
}
$('vclose').addEventListener('click',closeVisual);
$('vfull').addEventListener('click',()=>{ const f=document.querySelector('#vbody iframe'); const el=f||$('vview'); if(el.requestFullscreen) el.requestFullscreen().catch(()=>{}); });
document.addEventListener('keydown',e=>{ if(e.key==='Escape'&&!$('vview').hidden&&!document.fullscreenElement) closeVisual(); });
/* ---------- Branding + logo for exports ---------- */
/* BT20: the guide is written with the product name "ITOps"; when the client renamed the app (Settings → Branding →
   App name) every topic, quick start and export shows THEIR name instead. Header names such as X-ITOps-Signature
   are technical and stay as they are. */
function brandContent(n){
  if(!n||n==='ITOps') return;
  const re=/(?<![-\w])ITOps(?![-\w\u2060])/g;   // "ITOps\u2060" = the product name on purpose
  const walk=o=>{ if(typeof o==='string') return o.replace(re,n); if(Array.isArray(o)){ for(let i=0;i<o.length;i++) o[i]=walk(o[i]); return o; }
    if(o&&typeof o==='object'){ for(const k in o) o[k]=walk(o[k]); return o; } return o; };
  walk(CONTENT);
}
// APP_NAME is declared at the top (used by the first render)
const API=location.pathname.replace(/\/[^/]*$/,'')+'/api';
fetch(API+'/branding').then(r=>r.json()).then(b=>{
  if(!b)return;
  if(b.app_name){ APP_NAME=b.app_name; brandContent(APP_NAME); render(); } document.title='IT Help Center';
  if(b.logo){ const lg=$('logo'); lg.src=b.logo; lg.style.display='block'; }
}).catch(()=>{});
const appUrl=location.pathname.replace(/\/[^/]*$/,'')+'/';
$('foot').textContent='Powered by ITOps · © 2026 Indisse-BTS. All rights reserved. Licensed, not sold.';   // BT96: the product and its owner (fixed)

